// ---------- GUIDE SHEET ----------
function GuideSheet({ guide, onClose }) {
  useEffect(() => {
    const onKey = (e) => {if (e.key === "Escape") onClose();};
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [onClose]);

  if (!guide) return null;

  const fakeSteps = [
  "Open your system settings and confirm you're connected to the right network.",
  "Restart the affected service from the menu bar — the fastest fix 8/10 times.",
  "Sign out of your account, then sign back in with your OneLogin credentials.",
  "If prompted for a verification code, approve the OneLogin Protect push or use the most recent code.",
  "Confirm everything loads and no warning banner is shown.",
  "If anything above fails, come back here and file a ticket — we'll have your context."].
  slice(0, guide.steps || 5);

  return (
    <div
      onClick={onClose}
      style={{
        position: "fixed", inset: 0, zIndex: 100,
        background: "rgba(33,30,30,0.35)", backdropFilter: "blur(4px)",
        animation: "fadeIn .25s var(--ease) both",
        display: "flex", justifyContent: "flex-end"
      }}>

      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          width: "min(580px, 100%)", height: "100%",
          background: "#FFF9E6",
          borderLeft: "1px solid #211E1E",
          boxShadow: "-12px 0 0 #211E1E",
          padding: "28px 32px 36px",
          overflowY: "auto",
          animation: "sheetIn .4s var(--ease) both"
        }}>

        <style>{`@keyframes sheetIn { from { transform: translateX(30px); opacity: 0; } to { transform: none; opacity: 1; } }`}</style>

        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 24 }}>
          <div style={{
            display: "inline-flex", alignItems: "center", gap: 8,
            padding: "5px 10px",
            background: "#FDC831",
            border: "1px solid #211E1E",
            borderRadius: 4,
            fontFamily: "'Archivo', sans-serif",
            fontSize: 10.5, fontWeight: 800,
            letterSpacing: "0.04em", textTransform: "uppercase",
            color: "#211E1E",
          }}>
            {guide.tag} · {guide.time}
          </div>
          <button onClick={onClose} style={{
            width: 32, height: 32,
            background: "#FFFFFF",
            border: "1px solid #211E1E",
            borderRadius: 4,
            boxShadow: "1px 1px 0 #211E1E",
            display: "grid", placeItems: "center",
            color: "#211E1E", cursor: "pointer",
          }}>
            <IconClose size={14} stroke={2.5} />
          </button>
        </div>
        <h1 style={{
          fontFamily: "'Archivo', sans-serif",
          fontSize: 32, fontWeight: 800, letterSpacing: "-0.03em", lineHeight: 1.1,
          margin: "0 0 10px", color: "#211E1E",
        }}>
          {guide.title}
        </h1>
        <p style={{ fontSize: 14, color: "#4A3F2E", lineHeight: 1.55, marginTop: 0, marginBottom: 28 }}>
          A short walkthrough. If you get stuck at any step, return to the IT Hub and your context is saved.
        </p>

        <ol style={{ listStyle: "none", padding: 0, margin: 0 }}>
          {fakeSteps.map((s, i) =>
          <li key={i} style={{
            display: "grid", gridTemplateColumns: "36px 1fr", gap: 16,
            padding: "16px 16px",
            background: "#FFFFFF",
            border: "1px solid #211E1E",
            borderRadius: 8,
            boxShadow: "2px 2px 0 #211E1E",
            marginBottom: 12,
          }}>
              <div style={{
              width: 30, height: 30, borderRadius: "50%",
              background: "#FDC831",
              border: "1px solid #211E1E",
              color: "#211E1E",
              display: "grid", placeItems: "center",
              fontFamily: "'Archivo', sans-serif",
              fontSize: 13, fontWeight: 800,
            }}>{i + 1}</div>
              <div style={{ fontSize: 14.5, color: "#211E1E", lineHeight: 1.55, paddingTop: 4, fontWeight: 500 }}>
                {s}
              </div>
            </li>
          )}
        </ol>

        <div style={{
          marginTop: 28, padding: "18px 20px",
          background: "#FFFFFF",
          border: "1px solid #211E1E",
          borderRadius: 10,
          boxShadow: "2px 2px 0 #211E1E",
          display: "flex", alignItems: "center", gap: 12,
        }}>
          <div style={{
            flex: 1,
            fontFamily: "'Archivo', sans-serif",
            fontSize: 14, color: "#211E1E", fontWeight: 700,
          }}>
            Did this resolve it?
          </div>
          <button style={{
            padding: "8px 14px",
            background: "#FFFFFF",
            border: "1px solid #211E1E",
            borderRadius: 4,
            boxShadow: "1px 1px 0 #211E1E",
            fontFamily: "'Archivo', sans-serif",
            fontWeight: 800, fontSize: 11.5,
            letterSpacing: "0.04em", textTransform: "uppercase",
            color: "#211E1E", cursor: "pointer",
          }}>No, file ticket</button>
          <button style={{
            padding: "8px 14px",
            background: "#FDC831",
            border: "1px solid #211E1E",
            borderRadius: 4,
            boxShadow: "1px 1px 0 #211E1E",
            fontFamily: "'Archivo', sans-serif",
            fontWeight: 800, fontSize: 11.5,
            letterSpacing: "0.04em", textTransform: "uppercase",
            color: "#211E1E", cursor: "pointer",
            display: "inline-flex", alignItems: "center", gap: 6,
          }}>
            <IconCheck size={12} stroke={2.8} /> Yes, fixed it
          </button>
        </div>
      </div>
    </div>);

}

