// ---------- DISPATCH ----------
// Maps hardware item id → art component. Fallback = generic device box.
const DEVICE_ART_MAP = {
  // Laptops
  mbp14: ArtMacBookPro, mbp16: ArtMacBookPro, mba15: ArtMacBookAir, tp14: ArtDellLaptop,
  // Monitors
  studio: ArtStudioDisplay, lg27: ArtMonitor27, dell27: ArtMonitor27, dell34: ArtUltraWide,
  // Keyboards
  mag: ArtMagicKeyboard, mxmini: ArtMXKeys, mxkeys: ArtMXKeys,
  // Mice
  magic: ArtMagicMouse, mx3: ArtMX3Mouse,
  // Audio
  airpods: ArtAirPods, sony: ArtOverEar, bose: ArtOverEar,
  // Extras
  dock: ArtDock, yubi: ArtYubiKey, stand: ArtLaptopStand, webcam: ArtWebcam,
};

function DeviceArt({ id, w = 56, h = 38, style, category }) {
  const Comp = DEVICE_ART_MAP[id];
  if (Comp) return <Comp w={w} h={h} style={style} />;
  // Fallback by category
  if (category === "Laptop") return <ArtMacBookPro w={w} h={h} style={style} />;
  if (category === "Monitor") return <ArtMonitor27 w={w} h={h} style={style} />;
  if (category === "Keyboard") return <ArtMagicKeyboard w={w} h={h} style={style} />;
  if (category === "Mouse") return <ArtMX3Mouse w={w} h={h} style={style} />;
  if (category === "Audio") return <ArtAirPods w={w} h={h} style={style} />;
  return <ArtDock w={w} h={h} style={style} />;
}

Object.assign(window, { DeviceArt, DEVICE_ART_MAP });

// ─── slice-pickers (a42a53a8) ──────────────────────────────────
// ============================================================================
// SLICE PICKERS — v2
// Keyboard-first, parse-as-you-type date + time inputs with brutalist Slice
// chrome. Replaces the OS-native <input type="date/time"> which was breaking
// the visual language.
//
// Design decisions (distilled from Linear, Cal.com, Raycast, Notion):
//   - Type-to-pick: "next fri", "in 2 weeks", "5/10", "jun 3", "tomorrow"
//   - Keyboard nav: ↑↓←→ moves day, PgUp/PgDn moves month, Enter selects, Esc closes
//   - Dense connected grid (no gaps, just 1px dividers) for that spreadsheet feel
//   - Today = yellow underline chip (not a dashed border — too noisy)
//   - Time: segmented hour / minute text inputs with auto-advance + AM/PM toggle
//     (scroll columns feel like iOS wheels, always slow)
//   - Single combined <SliceDateTimePicker> for offboarding — one datetime
//
// Exports:
//   <SliceDatePicker value onChange label required error minDate />
//   <SliceTimePicker value onChange label required error />
//   <SliceDateTimePicker dateValue timeValue onDateChange onTimeChange ... />
// ============================================================================

const SP_DAY_MS = 24 * 60 * 60 * 1000;

// --- date helpers ----------------------------------------------------------
function spParseISO(s) {
  if (!s || typeof s !== "string") return null;
  const m = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return null;
  return new Date(+m[1], +m[2] - 1, +m[3]);
}
function spFormatISO(d) {
  if (!d) return "";
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}
function spSameDay(a, b) {
  if (!a || !b) return false;
  return a.getFullYear() === b.getFullYear() &&
         a.getMonth() === b.getMonth() &&
         a.getDate() === b.getDate();
}
function spAddDays(d, n) {
  const x = new Date(d);
  x.setDate(x.getDate() + n);
  return x;
}
function spStartOfMonth(d) {
  return new Date(d.getFullYear(), d.getMonth(), 1);
}
function spWeekdayMon0(d) {
  // Monday = 0 ... Sunday = 6
  return (d.getDay() + 6) % 7;
}
function spMonthLabel(d) {
  return d.toLocaleDateString("en-US", { month: "long", year: "numeric" });
}
function spPrettyDate(d) {
  // "Fri, May 10 · 2025" — compact but readable
  return d.toLocaleDateString("en-US", { weekday: "short", month: "short", day: "numeric", year: "numeric" });
}

// Natural-language parser. Returns a Date or null.
function spParseFuzzy(input, today) {
  if (!input) return null;
  const q = input.trim().toLowerCase();
  if (!q) return null;
  const base = new Date(today);
  base.setHours(0, 0, 0, 0);

  if (q === "today") return base;
  if (q === "tomorrow" || q === "tmr" || q === "tmrw") return spAddDays(base, 1);
  if (q === "yesterday") return spAddDays(base, -1);

  // "in N days/weeks/months"
  let m = q.match(/^in\s+(\d+)\s+(day|days|d|week|weeks|w|month|months|mo)s?$/);
  if (m) {
    const n = +m[1];
    const u = m[2];
    if (u.startsWith("d")) return spAddDays(base, n);
    if (u.startsWith("w")) return spAddDays(base, n * 7);
    if (u.startsWith("mo") || u.startsWith("m")) {
      const r = new Date(base); r.setMonth(r.getMonth() + n); return r;
    }
  }

  // "next friday", "this tuesday"
  const dayNames = ["sunday","monday","tuesday","wednesday","thursday","friday","saturday"];
  const dayShort = ["sun","mon","tue","wed","thu","fri","sat"];
  m = q.match(/^(next|this|coming)?\s*(sun|mon|tue|tues|wed|thu|thur|thurs|fri|sat|sunday|monday|tuesday|wednesday|thursday|friday|saturday)$/);
  if (m) {
    const prefix = m[1] || "this";
    const name = m[2].slice(0, 3);
    const target = dayShort.indexOf(name);
    if (target >= 0) {
      const todayDow = base.getDay();
      let delta = (target - todayDow + 7) % 7;
      if (delta === 0) delta = prefix === "next" ? 7 : 0;
      else if (prefix === "next") delta += 0; // "next fri" already in the future
      return spAddDays(base, delta || 7);
    }
  }

  // ISO direct
  const iso = spParseISO(q);
  if (iso) return iso;

  // "5/10", "5/10/2025", "10-5", "10-5-25"
  m = q.match(/^(\d{1,2})[\/\-](\d{1,2})(?:[\/\-](\d{2,4}))?$/);
  if (m) {
    const a = +m[1], b = +m[2], y = m[3] ? +m[3] : base.getFullYear();
    // Default MM/DD (US); swap if the first number is obviously a day (>12)
    let month, day;
    if (a > 12) { day = a; month = b; } else { month = a; day = b; }
    const yr = y < 100 ? 2000 + y : y;
    const d = new Date(yr, month - 1, day);
    if (!isNaN(d)) return d;
  }

  // "jun 3", "june 3", "3 jun"
  const months = ["january","february","march","april","may","june","july","august","september","october","november","december"];
  const monthsShort = months.map(x => x.slice(0, 3));
  const monRe = monthsShort.join("|");
  m = q.match(new RegExp(`^(${monRe})\\w*\\s+(\\d{1,2})(?:,?\\s+(\\d{2,4}))?$`));
  if (!m) m = q.match(new RegExp(`^(\\d{1,2})\\s+(${monRe})\\w*(?:,?\\s+(\\d{2,4}))?$`));
  if (m) {
    const isMonthFirst = isNaN(+m[1]);
    const mon = isMonthFirst ? monthsShort.indexOf(m[1]) : monthsShort.indexOf(m[2]);
    const day = +(isMonthFirst ? m[2] : m[1]);
    const y = m[3] ? (+m[3] < 100 ? 2000 + +m[3] : +m[3]) : base.getFullYear();
    const d = new Date(y, mon, day);
    // If day has passed this year and no year specified, next year
    if (!m[3] && d < base) d.setFullYear(y + 1);
    if (!isNaN(d)) return d;
  }

  return null;
}

// HR-style presets
function spBuildDatePresets(today) {
  const out = [];
  out.push({ label: "Today", date: today });
  out.push({ label: "Tomorrow", date: spAddDays(today, 1) });
  const daysUntilFri = (5 - today.getDay() + 7) % 7 || 7;
  out.push({ label: "This Fri", date: spAddDays(today, daysUntilFri) });
  out.push({ label: "In 2 weeks", date: spAddDays(today, 14) });
  const eom = new Date(today.getFullYear(), today.getMonth() + 1, 0);
  out.push({ label: "End of month", date: eom });
  return out;
}

// ============================================================================
// <SliceDatePicker>
// ============================================================================
function SliceDatePicker({ value, onChange, label, required, error, minDate, placeholder = "Type or pick a date" }) {
  const [open, setOpen] = React.useState(false);
  const [text, setText] = React.useState("");
  const [focused, setFocused] = React.useState(false);
  const selected = spParseISO(value);
  const today = React.useMemo(() => {
    const t = new Date();
    t.setHours(0, 0, 0, 0);
    return t;
  }, []);
  const min = minDate ? (minDate instanceof Date ? minDate : spParseISO(minDate)) : null;
  const [cursor, setCursor] = React.useState(() => spStartOfMonth(selected || today));
  const [focusDate, setFocusDate] = React.useState(() => selected || today);
  const rootRef = React.useRef(null);
  const inputRef = React.useRef(null);

  // Keep cursor near focus/selection when opening
  React.useEffect(() => {
    if (open) {
      const anchor = selected || today;
      setCursor(spStartOfMonth(anchor));
      setFocusDate(anchor);
      setText(selected ? spPrettyDate(selected) : "");
    }
  }, [open]);

  // Close outside
  React.useEffect(() => {
    if (!open) return;
    const handler = (e) => {
      if (rootRef.current && !rootRef.current.contains(e.target)) setOpen(false);
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, [open]);

  const presets = React.useMemo(() => spBuildDatePresets(today), [today]);

  const grid = React.useMemo(() => {
    const first = spStartOfMonth(cursor);
    const offset = spWeekdayMon0(first);
    const start = spAddDays(first, -offset);
    return Array.from({ length: 42 }, (_, i) => spAddDays(start, i));
  }, [cursor]);

  const commit = (d) => {
    if (min && d < min) return;
    onChange(spFormatISO(d));
    setText(spPrettyDate(d));
    setOpen(false);
  };

  const onKeyDown = (e) => {
    if (!open) {
      if (e.key === "ArrowDown" || e.key === "Enter") { setOpen(true); e.preventDefault(); }
      return;
    }
    const k = e.key;
    if (k === "Escape") { setOpen(false); e.preventDefault(); return; }
    if (k === "Enter") {
      // First try parsing the textual input
      const parsed = spParseFuzzy(text, today);
      if (parsed) { commit(parsed); e.preventDefault(); return; }
      commit(focusDate);
      e.preventDefault();
      return;
    }
    let delta = 0;
    if (k === "ArrowLeft") delta = -1;
    else if (k === "ArrowRight") delta = 1;
    else if (k === "ArrowUp") delta = -7;
    else if (k === "ArrowDown") delta = 7;
    else if (k === "PageUp") delta = e.shiftKey ? -365 : -30;
    else if (k === "PageDown") delta = e.shiftKey ? 365 : 30;
    if (delta) {
      const next = spAddDays(focusDate, delta);
      setFocusDate(next);
      setCursor(spStartOfMonth(next));
      e.preventDefault();
    }
  };

  const parsePreview = spParseFuzzy(text, today);
  const showParsePreview = text && !spSameDay(parsePreview, selected) && parsePreview;

  const displayValue = open
    ? text
    : (selected ? spPrettyDate(selected) : "");

  const trigger = {
    display: "flex", alignItems: "center", gap: 10,
    width: "100%",
    padding: "11px 12px 11px 14px",
    background: "#FFFFFF",
    border: `2px solid ${error ? "#B92323" : (focused || open) ? "#211E1E" : "#211E1E"}`,
    borderRadius: 6,
    fontFamily: "'Archivo', sans-serif",
    fontSize: 14, fontWeight: 700,
    color: "#211E1E",
    cursor: "text",
    boxShadow: error && !open ? "2px 2px 0 #B92323" : (open || focused ? "2px 2px 0 #211E1E" : "none"),
    transition: "box-shadow 80ms ease, transform 80ms ease",
    transform: open || focused ? "translate(-1px, -1px)" : "none",
    textAlign: "left",
  };

  return (
    <div style={{ position: "relative" }} ref={rootRef} data-err={error && !open ? "1" : undefined}>
      {label && (
        <div style={{
          fontFamily: "'Archivo', sans-serif",
          fontSize: 11, fontWeight: 800, color: "#211E1E",
          letterSpacing: "0.04em", textTransform: "uppercase",
          marginBottom: 6,
          display: "flex", alignItems: "center", gap: 6,
        }}>
          <span>{label}{required && <span style={{ color: "#B92323", marginLeft: 4 }}>*</span>}</span>
          {error && !open && (
            <span style={{
              fontSize: 9.5, fontWeight: 900, letterSpacing: "0.08em", textTransform: "uppercase",
              padding: "1px 6px",
              background: "#B92323", color: "#FFFFFF",
              borderRadius: 2,
              animation: "shake .4s ease-in-out",
            }}>Required</span>
          )}
        </div>
      )}

      <div style={trigger} onClick={() => { setOpen(true); inputRef.current?.focus(); }}>
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#211E1E" strokeWidth="2.5" strokeLinecap="round" style={{ flexShrink: 0 }}>
          <rect x="3" y="5" width="18" height="16" rx="1.5"/>
          <path d="M3 10h18M8 3v4M16 3v4"/>
        </svg>
        <input
          ref={inputRef}
          type="text"
          value={displayValue}
          placeholder={placeholder}
          onFocus={() => { setFocused(true); setOpen(true); }}
          onBlur={() => setFocused(false)}
          onChange={(e) => { setText(e.target.value); setOpen(true); }}
          onKeyDown={onKeyDown}
          style={{
            flex: 1, minWidth: 0,
            border: "none", outline: "none", background: "transparent",
            fontFamily: "'Archivo', sans-serif",
            fontSize: 14, fontWeight: 700, color: "#211E1E",
            padding: 0,
          }}
        />
        {selected && !open && (
          <button type="button" onClick={(e) => { e.stopPropagation(); onChange(""); setText(""); }}
            style={spClearBtn} aria-label="Clear date">×</button>
        )}
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#211E1E" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"
          style={{ flexShrink: 0, transform: open ? "rotate(180deg)" : "none", transition: "transform 120ms" }}>
          <path d="M6 9l6 6 6-6"/>
        </svg>
      </div>

      {error && !open && (
        <div style={{ color: "#B92323", fontSize: 11.5, fontWeight: 700, marginTop: 4 }}>{error}</div>
      )}

      {open && (
        <div style={{
          position: "absolute", zIndex: 200,
          top: "calc(100% + 6px)", left: 0,
          width: 320,
          background: "#FFFFFF",
          border: "1px solid #211E1E",
          borderRadius: 8,
          boxShadow: "2px 2px 0 #211E1E",
          overflow: "hidden",
        }}>
          {/* Parse preview */}
          {showParsePreview && (
            <button type="button" onClick={() => commit(parsePreview)}
              style={{
                width: "100%",
                padding: "10px 14px",
                background: "#FDC831",
                border: "none",
                borderBottom: "1px solid #211E1E",
                fontFamily: "'Archivo', sans-serif",
                fontSize: 12, fontWeight: 800, color: "#211E1E",
                textAlign: "left",
                cursor: "pointer",
                display: "flex", alignItems: "center", gap: 8,
              }}>
              <span style={{
                padding: "2px 6px",
                background: "#211E1E", color: "#FDC831",
                borderRadius: 3,
                fontSize: 9, fontWeight: 900, letterSpacing: "0.08em",
              }}>↵ ENTER</span>
              <span>Use <u>{spPrettyDate(parsePreview)}</u></span>
            </button>
          )}

          {/* Presets row */}
          <div style={{
            display: "flex", flexWrap: "wrap", gap: 4,
            padding: "8px 10px",
            background: "#FFF9E6",
            borderBottom: "1px solid #211E1E",
          }}>
            {presets.filter(p => !min || p.date >= min).map(p => {
              const active = spSameDay(p.date, selected);
              return (
                <button key={p.label} type="button" onClick={() => commit(p.date)}
                  style={{
                    padding: "4px 8px",
                    background: active ? "#FDC831" : "#FFFFFF",
                    border: "1px solid #211E1E",
                    borderRadius: 3,
                    fontFamily: "'Archivo', sans-serif",
                    fontSize: 10.5, fontWeight: 800, letterSpacing: "0.02em",
                    color: "#211E1E",
                    cursor: "pointer",
                  }}>{p.label}</button>
              );
            })}
          </div>

          {/* Month nav */}
          <div style={{
            display: "flex", alignItems: "center", justifyContent: "space-between",
            padding: "8px 10px",
            borderBottom: "1px solid #211E1E",
          }}>
            <button type="button" onClick={() => setCursor(new Date(cursor.getFullYear(), cursor.getMonth() - 1, 1))}
              style={spNavBtn} aria-label="Previous month">‹</button>
            <button type="button" onClick={() => { setCursor(spStartOfMonth(today)); setFocusDate(today); }}
              style={{
                fontFamily: "'Archivo', sans-serif",
                fontSize: 13, fontWeight: 800, color: "#211E1E",
                background: "transparent", border: "none",
                cursor: "pointer", padding: "4px 8px",
                letterSpacing: "0.01em",
              }}>{spMonthLabel(cursor)}</button>
            <button type="button" onClick={() => setCursor(new Date(cursor.getFullYear(), cursor.getMonth() + 1, 1))}
              style={spNavBtn} aria-label="Next month">›</button>
          </div>

          {/* Weekday row — connected, no gaps */}
          <div style={{
            display: "grid", gridTemplateColumns: "repeat(7, 1fr)",
            padding: "6px 10px 0",
          }}>
            {["Mo", "Tu", "We", "Th", "Fr", "Sa", "Su"].map((d, i) => (
              <div key={d} style={{
                textAlign: "center",
                fontFamily: "'Archivo', sans-serif",
                fontSize: 9.5, fontWeight: 900, letterSpacing: "0.08em",
                color: i >= 5 ? "#B92323" : "#78684C",
                textTransform: "uppercase",
                padding: "4px 0",
              }}>{d}</div>
            ))}
          </div>

          {/* Day grid — dense, no gaps, 1px dividers via borders */}
          <div style={{
            display: "grid", gridTemplateColumns: "repeat(7, 1fr)",
            padding: "4px 10px 8px",
          }}>
            {grid.map((d, i) => {
              const inMonth = d.getMonth() === cursor.getMonth();
              const isSel = spSameDay(d, selected);
              const isToday = spSameDay(d, today);
              const isFocus = spSameDay(d, focusDate);
              const isWeekend = d.getDay() === 0 || d.getDay() === 6;
              const disabled = min && d < min;
              return (
                <button
                  key={i}
                  type="button"
                  disabled={disabled}
                  onClick={() => commit(d)}
                  onMouseEnter={() => setFocusDate(d)}
                  style={{
                    position: "relative",
                    height: 34,
                    display: "flex", alignItems: "center", justifyContent: "center",
                    background: isSel ? "#FDC831"
                             : isFocus && !disabled ? "#FFF2B8"
                             : "transparent",
                    border: "none",
                    borderRadius: 4,
                    fontFamily: "'Archivo', sans-serif",
                    fontSize: 13,
                    fontWeight: isSel ? 900 : (isToday ? 800 : 600),
                    color: disabled ? "rgba(33,30,30,0.2)"
                         : !inMonth ? "rgba(33,30,30,0.28)"
                         : isWeekend && !isSel ? "#78684C"
                         : "#211E1E",
                    cursor: disabled ? "not-allowed" : "pointer",
                    outline: isSel ? "2px solid #211E1E" : "none",
                    outlineOffset: -2,
                    transition: "background 60ms",
                  }}
                >
                  {d.getDate()}
                  {isToday && !isSel && (
                    <span style={{
                      position: "absolute", bottom: 4,
                      width: 14, height: 2,
                      background: "#FDC831",
                      borderRadius: 1,
                    }}/>
                  )}
                </button>
              );
            })}
          </div>

          {/* Keyboard hint */}
          <div style={{
            display: "flex", alignItems: "center", justifyContent: "space-between",
            padding: "6px 12px",
            background: "#211E1E", color: "#FDC831",
            fontFamily: "'Archivo', monospace",
            fontSize: 9.5, fontWeight: 700, letterSpacing: "0.06em",
          }}>
            <span>↑↓←→ NAV · ↵ PICK</span>
            <span>ESC CLOSE</span>
          </div>
        </div>
      )}
    </div>
  );
}

const spClearBtn = {
  width: 18, height: 18,
  display: "flex", alignItems: "center", justifyContent: "center",
  background: "#FFF2B8",
  border: "1px solid #211E1E",
  borderRadius: 3,
  fontFamily: "'Archivo', sans-serif",
  fontSize: 13, fontWeight: 900, lineHeight: 1, color: "#211E1E",
  cursor: "pointer",
  padding: 0,
  flexShrink: 0,
};

const spNavBtn = {
  width: 26, height: 26,
  display: "flex", alignItems: "center", justifyContent: "center",
  background: "#FDC831",
  border: "1px solid #211E1E",
  borderRadius: 4,
  fontFamily: "'Archivo', sans-serif",
  fontSize: 18, fontWeight: 900, lineHeight: 1, color: "#211E1E",
  cursor: "pointer",
  padding: 0,
};

// ============================================================================
// <SliceTimePicker>
// Segmented HH : MM with AM/PM toggle. Type to enter, scroll-wheel on focus
// to nudge, chips for common picks.
// ============================================================================
function SliceTimePicker({ value, onChange, label, required, error, placeholder = "—" }) {
  const [hh, mm] = React.useMemo(() => {
    if (!value || typeof value !== "string") return [null, null];
    const m = value.match(/^(\d{1,2}):(\d{2})$/);
    if (!m) return [null, null];
    return [+m[1], +m[2]];
  }, [value]);

  const setTime = (h, m) => {
    const nh = Math.max(0, Math.min(23, h == null ? (hh ?? 17) : h));
    const nm = Math.max(0, Math.min(59, m == null ? (mm ?? 0) : m));
    onChange(`${String(nh).padStart(2, "0")}:${String(nm).padStart(2, "0")}`);
  };

  const isPM = hh != null ? hh >= 12 : false;
  const display12 = hh == null ? null : (hh % 12 === 0 ? 12 : hh % 12);

  const hRef = React.useRef(null);
  const mRef = React.useRef(null);

  // Text buffer so user can freely type "5" -> "05" etc without jank
  const [hBuf, setHBuf] = React.useState("");
  const [mBuf, setMBuf] = React.useState("");

  React.useEffect(() => {
    setHBuf(display12 != null ? String(display12).padStart(2, "0") : "");
    setMBuf(mm != null ? String(mm).padStart(2, "0") : "");
  }, [value]);

  const commitHour = () => {
    const n = parseInt(hBuf, 10);
    if (isNaN(n)) { setHBuf(display12 != null ? String(display12).padStart(2, "0") : ""); return; }
    let h24;
    if (n === 0) h24 = 0;             // "0" → midnight (shows as 12 AM)
    else if (n === 12) h24 = isPM ? 12 : 0;
    else if (n === 24) h24 = 0;       // typing 24 wraps to midnight
    else if (n > 12 && n < 24) h24 = n; // treat as 24h (13-23) — overrides AM/PM
    else if (n > 24) h24 = 23;        // clamp anything wild
    else h24 = isPM ? n + 12 : n;     // 1-11
    setTime(h24, null);
  };
  const commitMin = () => {
    const n = parseInt(mBuf, 10);
    if (isNaN(n)) { setMBuf(mm != null ? String(mm).padStart(2, "0") : ""); return; }
    setTime(null, Math.max(0, Math.min(59, n)));
  };

  const bumpHour = (delta) => setTime(((hh ?? 17) + delta + 24) % 24, null);
  const bumpMin = (delta) => {
    const cur = mm ?? 0;
    const next = (cur + delta + 60) % 60;
    setTime(null, next);
  };

  const toggleMeridiem = () => {
    if (hh == null) { setTime(isPM ? 9 : 17, 0); return; }
    setTime((hh + 12) % 24, null);
  };

  const quickChips = [
    { label: "9am",  t: "09:00" },
    { label: "12pm", t: "12:00" },
    { label: "5pm",  t: "17:00" },
    { label: "6pm",  t: "18:00" },
    { label: "EOD",  t: "17:00" },
  ];

  const segStyle = {
    width: 42, height: 36,
    display: "flex", alignItems: "center", justifyContent: "center",
    background: "#FFFFFF",
    border: "none", outline: "none",
    fontFamily: "'Archivo', monospace",
    fontSize: 17, fontWeight: 800, color: "#211E1E",
    textAlign: "center",
    padding: 0,
  };

  return (
    <div>
      {label && (
        <div style={{
          fontFamily: "'Archivo', sans-serif",
          fontSize: 11, fontWeight: 800, color: "#211E1E",
          letterSpacing: "0.04em", textTransform: "uppercase",
          marginBottom: 6,
        }}>
          {label}{required && <span style={{ color: "#B92323", marginLeft: 4 }}>*</span>}
        </div>
      )}

      <div style={{ display: "flex", alignItems: "stretch", gap: 10, flexWrap: "wrap" }}>
        {/* Segmented time input */}
        <div style={{
          display: "flex", alignItems: "center",
          background: "#FFFFFF",
          border: `2px solid ${error ? "#B92323" : "#211E1E"}`,
          borderRadius: 6,
          overflow: "hidden",
          boxShadow: "none",
        }}>
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#211E1E" strokeWidth="2.5" strokeLinecap="round"
            style={{ margin: "0 6px 0 10px", flexShrink: 0 }}>
            <circle cx="12" cy="12" r="9"/>
            <path d="M12 7v5l3 2"/>
          </svg>

          <input
            ref={hRef}
            type="text"
            inputMode="numeric"
            value={hBuf}
            placeholder="--"
            onFocus={(e) => e.target.select()}
            onChange={(e) => {
              const v = e.target.value.replace(/\D/g, "").slice(0, 2);
              setHBuf(v);
              if (v.length === 2) { mRef.current?.focus(); mRef.current?.select(); }
            }}
            onBlur={commitHour}
            onKeyDown={(e) => {
              if (e.key === "ArrowUp") { bumpHour(1); e.preventDefault(); }
              else if (e.key === "ArrowDown") { bumpHour(-1); e.preventDefault(); }
              else if (e.key === "Enter") { commitHour(); e.preventDefault(); }
            }}
            onWheel={(e) => {
              if (document.activeElement !== e.currentTarget) return;
              bumpHour(e.deltaY < 0 ? 1 : -1);
            }}
            style={segStyle}
          />
          <span style={{
            fontFamily: "'Archivo', monospace",
            fontSize: 17, fontWeight: 900, color: "#211E1E",
            lineHeight: 1,
          }}>:</span>
          <input
            ref={mRef}
            type="text"
            inputMode="numeric"
            value={mBuf}
            placeholder="--"
            onFocus={(e) => e.target.select()}
            onChange={(e) => {
              const v = e.target.value.replace(/\D/g, "").slice(0, 2);
              setMBuf(v);
            }}
            onBlur={commitMin}
            onKeyDown={(e) => {
              if (e.key === "ArrowUp") { bumpMin(5); e.preventDefault(); }
              else if (e.key === "ArrowDown") { bumpMin(-5); e.preventDefault(); }
              else if (e.key === "Enter") { commitMin(); e.preventDefault(); }
            }}
            onWheel={(e) => {
              if (document.activeElement !== e.currentTarget) return;
              bumpMin(e.deltaY < 0 ? 5 : -5);
            }}
            style={segStyle}
          />
          <button type="button" onClick={toggleMeridiem}
            style={{
              height: 36, padding: "0 12px",
              background: "#211E1E", color: "#FDC831",
              border: "none", borderLeft: "1px solid #211E1E",
              fontFamily: "'Archivo', sans-serif",
              fontSize: 11.5, fontWeight: 900, letterSpacing: "0.1em",
              cursor: "pointer",
            }}>{isPM ? "PM" : "AM"}</button>
        </div>

        {/* Quick chips */}
        <div style={{ display: "flex", gap: 4, flexWrap: "wrap", alignItems: "center" }}>
          {quickChips.map(c => {
            const active = value === c.t;
            return (
              <button key={c.label} type="button" onClick={() => onChange(c.t)}
                style={{
                  padding: "6px 10px",
                  background: active ? "#FDC831" : "#FFFFFF",
                  border: "1px solid #211E1E",
                  borderRadius: 4,
                  fontFamily: "'Archivo', sans-serif",
                  fontSize: 11, fontWeight: 800, letterSpacing: "0.02em",
                  color: "#211E1E",
                  cursor: "pointer",
                  boxShadow: active ? "1px 1px 0 #211E1E" : "none",
                }}>{c.label}</button>
            );
          })}
        </div>
      </div>

      {error && (
        <div style={{ color: "#B92323", fontSize: 11.5, fontWeight: 700, marginTop: 4 }}>{error}</div>
      )}
    </div>
  );
}

// Expose
Object.assign(window, { SliceDatePicker, SliceTimePicker, spParseFuzzy, spPrettyDate });

// ─── it-checklist (863c4f7a) ──────────────────────────────────
// ---------- IT CHECKLIST MODULE ----------
// Lives between onboarding + offboarding. Provides:
//   - Item definitions (with stage mapping for auto-pipeline-advance)
//   - useITWorkLog() hook — ticks, per-item notes, running log, persisted to localStorage
//   - ITWorkPanel — the full interactive UI (checklist + inline notes + log)
//   - getItProgress() — pure helper for the IT Queue tab
//
// Item shape:
//   { id, label, desc, stage, autoFromHire?: (hire) => string[] }
//   - stage: bumps the hire/offboard's pipeline stage when ticked. Multiple items
//     can map to the same stage; the most-advanced ticked stage wins.
//   - autoFromHire: returns sub-bullets to render under the item (read-only).
//     Lets us show "App access provisioned" with the actual app names from
//     the hire's apps list, without baking app data into the checklist.

(function () {
  // ---------- ITEM DEFINITIONS ----------
  // Onboarding — the order matters. Top of list = earliest stage IT works on.
  const IT_ONBOARD_ITEMS = [
    {
      id: "sso",
      label: "OneLogin / SSO accounts created",
      desc: "Identity provider account, group membership, MFA seeded.",
      stage: "Accounts provisioning",
    },
    {
      id: "apps",
      label: "App access provisioned",
      desc: "Per the hire's app list — auto-derived below.",
      stage: "Accounts provisioning",
      autoFromHire: (hire) => {
        if (!hire?.apps) return [];
        const apps = (window.ONB_APPS || []).filter(a => hire.apps.has?.(a.id));
        return apps.map(a => a.name);
      },
    },
    {
      id: "hardware",
      label: "Hardware imaged & shipped",
      desc: "Laptop reset, peripherals packed, tracking number filed.",
      stage: "Hardware shipped",
      autoFromHire: (hire) => {
        const hw = hire?.hardware; if (!hw) return [];
        const out = [];
        const pick = (pool, id) => (pool || []).find(p => p.id === id);
        const lap = pick(window.ONB_HARDWARE?.laptops, hw.laptop);
        if (lap) out.push(lap.name);
        const mon = pick(window.ONB_HARDWARE?.monitors, hw.monitor);
        if (mon) out.push(mon.name);
        const kb = pick(window.ONB_HARDWARE?.keyboards, hw.keyboard);
        if (kb) out.push(kb.name);
        const ms = pick(window.ONB_HARDWARE?.mice, hw.mouse);
        if (ms) out.push(ms.name);
        (hw.extras || new Set()).forEach(id => {
          const x = pick(window.ONB_HARDWARE?.extras, id);
          if (x) out.push(x.name);
        });
        return out;
      },
    },
    {
      id: "welcome",
      label: "Welcome packet email sent",
      desc: "Day-1 instructions, login URLs, IT contact card.",
      stage: "Welcome packet",
    },
  ];

  // Offboarding — destructive operations. Order = most-urgent first.
  const IT_OFFBOARD_ITEMS = [
    {
      id: "disable",
      label: "Disable accounts",
      desc: "Suspend OneLogin, Slack, Email, calendar resources.",
      stage: "Access being revoked",
    },
    {
      id: "revoke_apps",
      label: "Revoke app access",
      desc: "Per the Slicer's app list — auto-derived below.",
      stage: "Access being revoked",
      autoFromHire: (hire) => {
        if (!hire?.apps) return [];
        const apps = (window.ONB_APPS || []).filter(a => hire.apps.has?.(a.id));
        return apps.map(a => a.name);
      },
    },
    {
      id: "wipe",
      label: "Wipe & collect laptop + peripherals",
      desc: "Remote wipe, return label sent, expected back within 7 days.",
      stage: "Hardware return scheduled",
      autoFromHire: (hire) => {
        const hw = hire?.hardware; if (!hw) return [];
        const pick = (pool, id) => (pool || []).find(p => p.id === id);
        const out = [];
        const lap = pick(window.ONB_HARDWARE?.laptops, hw.laptop);
        if (lap) out.push(lap.name);
        if (hw.monitor) out.push("Monitor");
        return out;
      },
    },
  ];

  // ---------- STORAGE ----------
  // localStorage key shape: it-work::onboard::p_nora  →  { ticks: { sso: { at, by } }, notes: { sso: "…" }, log: [{ at, by, text }] }
  const STORAGE_PREFIX = "it-work::";
  // For demo realism, the "current IT person" is hardcoded. In a real app this
  // would come from auth context.
  const CURRENT_IT_USER = (typeof window !== "undefined" && window.PORTAL_CURRENT_USER) || "IT";

  function storageKey(kind, id) {
    return STORAGE_PREFIX + kind + "::" + id;
  }

  function loadWork(kind, id) {
    if (!id) return { ticks: {}, notes: {}, log: [] };
    try {
      const raw = localStorage.getItem(storageKey(kind, id));
      if (!raw) return { ticks: {}, notes: {}, log: [] };
      const parsed = JSON.parse(raw);
      return {
        ticks: parsed.ticks || {},
        notes: parsed.notes || {},
        log:   parsed.log   || [],
      };
    } catch {
      return { ticks: {}, notes: {}, log: [] };
    }
  }

  function saveWork(kind, id, work) {
    if (!id) return;
    try {
      localStorage.setItem(storageKey(kind, id), JSON.stringify(work));
    } catch { /* quota or disabled — ignore */ }
  }

  // ---------- HOOK ----------
  // Returns the full work record + mutation helpers. Used by ITWorkPanel
  // and (read-only) by the IT Queue tab via getItProgress.
  function useITWorkLog(kind, id) {
    const [work, setWork] = React.useState(() => loadWork(kind, id));

    // Re-load if id changes (different hire opened in same session).
    React.useEffect(() => {
      setWork(loadWork(kind, id));
    }, [kind, id]);

    const persist = (next) => { setWork(next); saveWork(kind, id, next); };

    const toggle = (itemId) => {
      const ticks = { ...work.ticks };
      const log = [...work.log];
      if (ticks[itemId]) {
        delete ticks[itemId];
        log.push({ at: Date.now(), by: CURRENT_IT_USER, text: `Unticked "${itemId}"`, kind: "untick", item: itemId });
      } else {
        ticks[itemId] = { at: Date.now(), by: CURRENT_IT_USER };
        log.push({ at: Date.now(), by: CURRENT_IT_USER, text: `Marked "${itemId}" complete`, kind: "tick", item: itemId });
      }
      persist({ ...work, ticks, log });
    };

    const setItemNote = (itemId, text) => {
      const notes = { ...work.notes, [itemId]: text };
      persist({ ...work, notes });
    };

    // Add a free-form log entry (general note). Doesn't auto-create on every keystroke;
    // call this only when the user explicitly submits.
    const addLog = (text) => {
      if (!text || !text.trim()) return;
      const entry = { at: Date.now(), by: CURRENT_IT_USER, text: text.trim(), kind: "note" };
      persist({ ...work, log: [...work.log, entry] });
    };

    return { ...work, toggle, setItemNote, addLog };
  }

  // ---------- PURE HELPERS ----------
  // Stage progression order — most-advanced wins. Unknown stages ranked low.
  const STAGE_ORDER_ONBOARD = [
    "Request filed",
    "Hardware shipped",
    "Accounts provisioning",
    "Welcome packet",
    "Awaiting start date",
  ];
  const STAGE_ORDER_OFFBOARD = [
    "Hardware return scheduled",
    "Access being revoked",
    "Final security review",
  ];
  function stageRank(kind, stage) {
    const order = kind === "offboard" ? STAGE_ORDER_OFFBOARD : STAGE_ORDER_ONBOARD;
    const i = order.indexOf(stage);
    return i < 0 ? -1 : i;
  }

  // Compute IT progress for a hire/offboard — used by the IT Queue tab.
  // Returns { done, total, stage } where stage is the highest-rank stage
  // among ticked items (or the original stage if nothing ticked yet).
  function getItProgress(kind, id, originalStage) {
    const items = kind === "offboard" ? IT_OFFBOARD_ITEMS : IT_ONBOARD_ITEMS;
    const work = loadWork(kind, id);
    const ticked = items.filter(it => work.ticks[it.id]);
    let bestStage = originalStage || null;
    ticked.forEach(it => {
      if (stageRank(kind, it.stage) > stageRank(kind, bestStage)) bestStage = it.stage;
    });
    return {
      done: ticked.length,
      total: items.length,
      stage: bestStage,
      lastTouched: work.log.length ? work.log[work.log.length - 1].at : null,
      claimedBy: ticked.length ? (work.ticks[ticked[0].id]?.by || null) : null,
    };
  }

  // ---------- TIME HELPERS ----------
  function formatTimeAgo(ms) {
    const diff = Date.now() - ms;
    const m = Math.floor(diff / 60000);
    if (m < 1) return "just now";
    if (m < 60) return m + "m ago";
    const h = Math.floor(m / 60);
    if (h < 24) return h + "h ago";
    const d = Math.floor(h / 24);
    return d + "d ago";
  }

  function formatTime(ms) {
    const d = new Date(ms);
    return d.toLocaleString("en-US", { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" });
  }

  // ---------- INITIALS HELPER ----------
  function initials(name) {
    return name.split(" ").map(s => s[0]).join("").toUpperCase().slice(0, 2);
  }

  // ---------- UI: ITWorkPanel ----------
  // Drop-in for the detail modal. kind: "onboard" | "offboard". hire: the
  // hire/slicer record (for auto-derived sub-bullets). id: the work-log id
  // (e.g. "p_nora" for onboarding, "o_mira" for offboarding).
  function ITWorkPanel({ kind, hire, id, onStageChange }) {
    const items = kind === "offboard" ? IT_OFFBOARD_ITEMS : IT_ONBOARD_ITEMS;
    const work = useITWorkLog(kind, id);
    const [expanded, setExpanded] = React.useState(null); // item id with notes shown
    const [logDraft, setLogDraft] = React.useState("");

    // Notify parent when computed stage advances. Parent decides whether to
    // show the "auto-advance" indicator on the pipeline.
    React.useEffect(() => {
      if (!onStageChange) return;
      const ticked = items.filter(it => work.ticks[it.id]);
      let bestStage = null;
      ticked.forEach(it => {
        if (stageRank(kind, it.stage) > stageRank(kind, bestStage)) bestStage = it.stage;
      });
      if (bestStage) onStageChange(bestStage);
    }, [work.ticks]);

    const done = items.filter(it => work.ticks[it.id]).length;
    const claimedBy = done > 0 ? CURRENT_IT_USER : null;

    return (
      <div style={{
        padding: "14px 16px",
        background: "#FFF9E6",
        border: "1px solid #211E1E",
        borderRadius: 8,
        boxShadow: "2px 2px 0 #211E1E",
      }}>
        {/* Header */}
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 10 }}>
          <div style={{
            width: 28, height: 28, borderRadius: 4,
            background: "#211E1E", color: "#FDC831",
            display: "grid", placeItems: "center",
            fontFamily: "'Archivo', sans-serif", fontSize: 9, fontWeight: 900,
            letterSpacing: "0.04em",
          }}>IT</div>
          <div style={{ flex: 1 }}>
            <div style={{
              fontFamily: "'Archivo', sans-serif",
              fontSize: 12.5, fontWeight: 900,
              letterSpacing: "0.04em", textTransform: "uppercase",
              color: "#211E1E",
            }}>IT workspace</div>
            <div style={{ fontSize: 11, color: "#78684C", marginTop: 1, fontWeight: 600 }}>
              {done}/{items.length} complete
              {claimedBy && <> · claimed by <strong style={{ color: "#211E1E" }}>{claimedBy}</strong></>}
            </div>
          </div>
          {/* Progress bar — flips to "All done" pill at 100% */}
          {done === items.length ? (
            <div style={{
              display: "inline-flex", alignItems: "center", gap: 6,
              padding: "5px 10px",
              background: "#211E1E",
              color: "#FDC831",
              border: "1px solid #211E1E",
              borderRadius: 4,
              fontFamily: "'Archivo', sans-serif",
              fontSize: 10, fontWeight: 900,
              letterSpacing: "0.06em", textTransform: "uppercase",
            }}>
              <svg width="11" height="11" viewBox="0 0 24 24" fill="none"
                stroke="#FDC831" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round">
                <polyline points="20 6 9 17 4 12"/>
              </svg>
              All done
            </div>
          ) : (
            <div style={{
              width: 120, height: 8,
              background: "#FFFFFF",
              border: "1px solid #211E1E", borderRadius: 4,
              overflow: "hidden",
            }}>
              <div style={{
                width: `${(done / items.length) * 100}%`,
                height: "100%",
                background: "#211E1E",
                transition: "width .25s ease",
              }}/>
            </div>
          )}
        </div>

        {/* Checklist */}
        <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
          {items.map((item) => {
            const tick = work.ticks[item.id];
            const isExpanded = expanded === item.id;
            const subBullets = item.autoFromHire ? item.autoFromHire(hire) : [];
            const note = work.notes[item.id] || "";
            return (
              <div key={item.id} style={{
                background: tick ? "rgba(255,255,255,0.7)" : "#FFFFFF",
                border: `1.5px solid ${tick ? "rgba(33,30,30,0.4)" : "rgba(33,30,30,0.25)"}`,
                borderRadius: 6,
                overflow: "hidden",
                transition: "background .15s ease, border-color .15s ease",
              }}>
                {/* Row */}
                <div style={{
                  display: "grid",
                  gridTemplateColumns: "auto 1fr auto",
                  gap: 10, alignItems: tick ? "center" : "flex-start",
                  padding: tick ? "5px 11px" : "9px 11px",
                  transition: "padding .15s ease",
                }}>
                  {/* Checkbox */}
                  <button onClick={() => work.toggle(item.id)} style={{
                    width: tick ? 18 : 22, height: tick ? 18 : 22, borderRadius: 4,
                    background: tick ? "#211E1E" : "#FFFFFF",
                    border: "1px solid #211E1E",
                    display: "grid", placeItems: "center",
                    cursor: "pointer", flexShrink: 0,
                    marginTop: tick ? 0 : 1,
                    transition: "width .15s ease, height .15s ease",
                  }} title={tick ? "Untick" : "Mark complete"}>
                    {tick && (
                      <svg width="9" height="9" viewBox="0 0 24 24" fill="none"
                        stroke="#FDC831" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round">
                        <polyline points="20 6 9 17 4 12"/>
                      </svg>
                    )}
                  </button>
                  <div
                    onClick={() => work.toggle(item.id)}
                    style={{
                      minWidth: 0, display: "flex", flexDirection: "column", gap: tick ? 0 : 2,
                      cursor: "pointer", userSelect: "none",
                    }}
                    title={tick ? "Untick" : "Mark complete"}
                  >
                    <div style={{
                      display: "flex", alignItems: "baseline", gap: 8, flexWrap: "wrap",
                    }}>
                      <div style={{
                        fontFamily: "'Archivo', sans-serif",
                        fontSize: tick ? 12 : 13, fontWeight: tick ? 700 : 800,
                        color: tick ? "#78684C" : "#211E1E",
                        letterSpacing: "-0.005em",
                        textDecoration: tick ? "line-through" : "none",
                        textDecorationColor: "rgba(33,30,30,0.35)",
                        transition: "font-size .15s ease",
                      }}>{item.label}</div>
                      {/* Inline tick metadata when compact */}
                      {tick && (
                        <span style={{
                          fontFamily: "'Archivo', monospace",
                          fontSize: 10, fontWeight: 700,
                          color: "#78684C",
                        }}>✓ {tick.by} · {formatTimeAgo(tick.at)}</span>
                      )}
                    </div>
                    {/* Description + sub-bullets — only when not ticked */}
                    {!tick && (
                      <>
                        <div style={{
                          fontFamily: "'Archivo', sans-serif",
                          fontSize: 11.5, fontWeight: 600,
                          color: "#78684C",
                          lineHeight: 1.4,
                        }}>{item.desc}</div>
                        {subBullets.length > 0 && (
                          <div style={{
                            display: "flex", flexWrap: "wrap", gap: 4,
                            marginTop: 4,
                          }}>
                            {subBullets.slice(0, 8).map((b, i) => (
                              <span key={i} style={{
                                display: "inline-block",
                                padding: "2px 7px",
                                background: "#FFF9E6",
                                border: "1px solid rgba(33,30,30,0.25)",
                                borderRadius: 3,
                                fontFamily: "'Archivo', monospace",
                                fontSize: 10, fontWeight: 700,
                                color: "#4A3F2E",
                              }}>{b}</span>
                            ))}
                            {subBullets.length > 8 && (
                              <span style={{
                                fontFamily: "'Archivo', monospace",
                                fontSize: 10, fontWeight: 700,
                                color: "#78684C",
                                padding: "2px 4px",
                              }}>+{subBullets.length - 8} more</span>
                            )}
                          </div>
                        )}
                      </>
                    )}
                  </div>
                  {/* Note button */}
                  <button onClick={() => setExpanded(isExpanded ? null : item.id)} style={{
                    padding: "5px 9px",
                    background: note ? "#FDC831" : "#FFFFFF",
                    border: "1px solid #211E1E",
                    borderRadius: 3,
                    fontFamily: "'Archivo', sans-serif",
                    fontSize: 10, fontWeight: 800,
                    letterSpacing: "0.04em", textTransform: "uppercase",
                    color: "#211E1E",
                    cursor: "pointer",
                    flexShrink: 0,
                    height: 24,
                    display: "inline-flex", alignItems: "center", gap: 4,
                  }} title={note ? "Has note" : "Add note"}>
                    {note ? "Note" : "+ Note"}
                  </button>
                </div>
                {/* Notes editor — drops out below when expanded */}
                {isExpanded && (
                  <div style={{
                    padding: "0 11px 10px 41px",
                    borderTop: "1px dashed rgba(33,30,30,0.15)",
                    paddingTop: 8,
                    background: "#FFF9E6",
                  }}>
                    <textarea
                      value={note}
                      onChange={(e) => work.setItemNote(item.id, e.target.value)}
                      placeholder="Note for this step…"
                      rows={2}
                      style={{
                        width: "100%",
                        padding: "7px 9px",
                        background: "#FFFFFF",
                        border: "1px solid #211E1E",
                        borderRadius: 3,
                        fontFamily: "'Archivo', sans-serif",
                        fontSize: 12, fontWeight: 600,
                        color: "#211E1E", outline: "none",
                        resize: "vertical",
                        minHeight: 40,
                      }}
                    />
                  </div>
                )}
              </div>
            );
          })}
        </div>

        {/* Running log */}
        <div style={{ marginTop: 14 }}>
          <div style={{
            fontFamily: "'Archivo', sans-serif",
            fontSize: 10.5, fontWeight: 900,
            letterSpacing: "0.08em", textTransform: "uppercase",
            color: "#78684C",
            marginBottom: 6,
          }}>Activity log</div>
          <div style={{
            background: "#FFFFFF",
            border: "1px solid #211E1E",
            borderRadius: 6,
            maxHeight: 160, overflowY: "auto",
            padding: work.log.length ? "6px 10px" : "12px",
          }}>
            {work.log.length === 0 && (
              <div style={{ fontSize: 11.5, color: "#78684C", textAlign: "center", fontStyle: "italic" }}>
                No activity yet — tick an item or leave a note below.
              </div>
            )}
            {[...work.log].reverse().slice(0, 30).map((entry, i) => (
              <div key={i} style={{
                display: "flex", alignItems: "flex-start", gap: 8,
                padding: "5px 0",
                borderBottom: i < Math.min(work.log.length, 30) - 1 ? "1px dashed rgba(33,30,30,0.1)" : "none",
              }}>
                <div style={{
                  width: 22, height: 22, borderRadius: "50%",
                  background: "#211E1E", color: "#FDC831",
                  display: "grid", placeItems: "center",
                  fontFamily: "'Archivo', sans-serif", fontSize: 8.5, fontWeight: 900,
                  flexShrink: 0,
                }}>{initials(entry.by)}</div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{
                    fontFamily: "'Archivo', sans-serif", fontSize: 11.5, fontWeight: 700,
                    color: "#211E1E", lineHeight: 1.4,
                  }}>
                    <strong>{entry.by}</strong>{" "}
                    <span style={{ color: "#78684C", fontWeight: 600 }}>{entry.text}</span>
                  </div>
                  <div style={{
                    fontFamily: "'Archivo', monospace", fontSize: 9.5, fontWeight: 700,
                    color: "#78684C", marginTop: 1,
                  }}>{formatTime(entry.at)}</div>
                </div>
              </div>
            ))}
          </div>

          {/* Compose box */}
          <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
            <input
              type="text"
              value={logDraft}
              onChange={(e) => setLogDraft(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter" && logDraft.trim()) {
                  work.addLog(logDraft);
                  setLogDraft("");
                }
              }}
              placeholder="Add a note to the log… (Enter to send)"
              style={{
                flex: 1,
                padding: "8px 11px",
                background: "#FFFFFF",
                border: "1px solid #211E1E",
                borderRadius: 4,
                fontFamily: "'Archivo', sans-serif",
                fontSize: 12, fontWeight: 600,
                color: "#211E1E", outline: "none",
              }}
            />
            <button onClick={() => {
              if (logDraft.trim()) {
                work.addLog(logDraft);
                setLogDraft("");
              }
            }} style={{
              padding: "8px 14px",
              background: logDraft.trim() ? "#FDC831" : "rgba(253,200,49,0.4)",
              border: "1px solid #211E1E",
              borderRadius: 4,
              fontFamily: "'Archivo', sans-serif",
              fontSize: 11, fontWeight: 800,
              letterSpacing: "0.04em", textTransform: "uppercase",
              color: "#211E1E",
              cursor: logDraft.trim() ? "pointer" : "not-allowed",
            }}>Post</button>
          </div>
        </div>
      </div>
    );
  }

  // Expose to global scope
  Object.assign(window, {
    IT_ONBOARD_ITEMS,
    IT_OFFBOARD_ITEMS,
    useITWorkLog,
    getItProgress,
    ITWorkPanel,
    IT_CURRENT_USER: CURRENT_IT_USER,
  });
})();

// ─── components (dfe64fda) ──────────────────────────────────
// ------ Shared building blocks ------

// --- Shared notifications store -----------------------------------------------
// Personal notifications come ONLY from the signed-in user's own tickets
// (/api/tickets) — an IT reply or a status change on a ticket. System/service
// status incidents are deliberately excluded: users told us the bell should be
// about their tickets, and service status already has its own Status page.

const NOTIF_KEY = "portal2.notifications.v1";
const NOTIF_EVT = "portal2:notifications:change";

// Per-ticket "last seen update" so the bell can flag tickets the IT Team has
// touched (replied, changed status) since you last opened them. Keyed by ticket
// id → the updated_at we last saw. Opening a ticket records its current
// updated_at, which clears its notification.
const TICKET_SEEN_KEY = "portal2.ticketSeen.v1";
function loadTicketSeen() {
  try { const r = typeof localStorage !== 'undefined' && localStorage.getItem(TICKET_SEEN_KEY); return r ? JSON.parse(r) : {}; } catch { return {}; }
}
function markTicketSeen(id, updatedAt) {
  if (id == null || !updatedAt) return;
  try {
    const m = loadTicketSeen();
    if (m[String(id)] === updatedAt) return;
    m[String(id)] = updatedAt;
    localStorage.setItem(TICKET_SEEN_KEY, JSON.stringify(m));
    window.dispatchEvent(new Event(NOTIF_EVT));
  } catch {}
}

// ── Tab badges: "unseen" tickets / approvals ────────────────────────────────
// Which items the user has actually OPENED (the detail view), so the My-tickets
// and Approvals tabs can flag things with an update you haven't looked at yet.
// Deliberately separate from the bell's TICKET_SEEN_KEY (which seeds first
// sightings to stay quiet) — this store is never seeded, so an unopened item
// that has real activity still shows on the tab. Shape: { tickets:{}, approvals:{} }.
const TAB_SEEN_KEY = "portal2.tabSeen.v1";
function loadTabSeen() {
  try {
    const r = typeof localStorage !== 'undefined' && localStorage.getItem(TAB_SEEN_KEY);
    const j = r ? JSON.parse(r) : null;
    return { tickets: (j && j.tickets) || {}, approvals: (j && j.approvals) || {} };
  } catch { return { tickets: {}, approvals: {} }; }
}
function markTabSeen(kind, id, updatedAt) {
  if (id == null) return;
  try {
    const m = loadTabSeen();
    const v = updatedAt || '1';
    if (m[kind][String(id)] === v) return;
    m[kind][String(id)] = v;
    localStorage.setItem(TAB_SEEN_KEY, JSON.stringify(m));
    window.dispatchEvent(new Event(NOTIF_EVT));
  } catch {}
}
// Everything in a list, seen, in ONE write and ONE event. This is "Mark all as
// read" on My Tickets (IT-105119: "I don't want to go through all 53 tickets").
// Fifty-three markTabSeen() calls would fire fifty-three NOTIF_EVTs, and the
// tickets page answers each one with two fetches. Writes the bell's own store
// too, so the two "have I seen this?" answers agree the way they do when you
// close a ticket. Returns how many rows actually changed.
function markAllTabSeen(kind, items, getId, getUpdated) {
  try {
    const tab = loadTabSeen();
    const bell = loadTicketSeen();
    let changed = 0;
    for (const it of items || []) {
      const id = getId(it);
      if (id == null) continue;
      const v = getUpdated(it) || '1';
      if (tab[kind][String(id)] !== v) { tab[kind][String(id)] = v; changed++; }
      if (kind === 'tickets' && getUpdated(it)) bell[String(id)] = getUpdated(it);
    }
    if (!changed) return 0;
    localStorage.setItem(TAB_SEEN_KEY, JSON.stringify(tab));
    if (kind === 'tickets') localStorage.setItem(TICKET_SEEN_KEY, JSON.stringify(bell));
    window.dispatchEvent(new Event(NOTIF_EVT));
    return changed;
  } catch { return 0; }
}

// Count items whose latest update the user hasn't seen. An item is "unseen" if
// it was never opened, or it changed (updated_at) since you last opened it.
// `getCreated` (tickets only) suppresses items with no activity since creation —
// a request you filed that nobody's touched yet isn't "an update you haven't seen".
function countTabUnseen(kind, items, getId, getUpdated, getCreated) {
  const seen = loadTabSeen()[kind] || {};
  let n = 0;
  for (const it of items) {
    const id = getId(it);
    if (id == null) continue;
    const upd = getUpdated ? getUpdated(it) : null;
    if (getCreated) {
      const created = getCreated(it);
      if (created && upd && new Date(upd).getTime() <= new Date(created).getTime()) continue;
    }
    const prev = seen[String(id)];
    if (prev === undefined) { n++; continue; }
    if (upd && new Date(upd).getTime() > new Date(prev).getTime()) n++;
  }
  return n;
}

// Bucket a Date into the same coarse "Today / Yesterday / Earlier" groups the
// notification page already shows.
function notifGroup(d) {
  if (!(d instanceof Date) || Number.isNaN(d.getTime())) return "Earlier";
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const yest  = new Date(today.getTime() - 86400000);
  if (d >= today) return "Today";
  if (d >= yest)  return "Yesterday";
  return "Earlier";
}

// Render a Date as a compact label that matches the existing "12m / 1h / Mon"
// style used by the notification list.
function notifWhen(d) {
  if (!(d instanceof Date) || Number.isNaN(d.getTime())) return "";
  const sec = Math.max(0, Math.round((Date.now() - d.getTime()) / 1000));
  if (sec < 60) return `${sec}s`;
  const min = Math.floor(sec / 60);
  if (min < 60) return `${min}m`;
  const hr = Math.floor(min / 60);
  if (hr < 24) return `${hr}h`;
  // Yesterday → "Yesterday"; same week → weekday; older → "Mon DD"
  const day = Math.floor(hr / 24);
  if (day === 1) return "Yesterday";
  if (day < 7) return d.toLocaleDateString(undefined, { weekday: "short" });
  return d.toLocaleDateString(undefined, { month: "short", day: "numeric" });
}

function loadNotifPersist() {
  try {
    const raw = typeof localStorage !== "undefined" && localStorage.getItem(NOTIF_KEY);
    if (!raw) return { dismissed: [], read: [] };
    const j = JSON.parse(raw);
    return {
      dismissed: Array.isArray(j.dismissed) ? j.dismissed : [],
      read: Array.isArray(j.read) ? j.read : [],
    };
  } catch { return { dismissed: [], read: [] }; }
}

function saveNotifPersist(s) {
  try { localStorage.setItem(NOTIF_KEY, JSON.stringify(s)); } catch {}
}

function useNotifications() {
  const [persist, setPersist] = React.useState(loadNotifPersist);
  // One live source, polled every 60s: the signed-in user's tickets
  // (/api/tickets) — so an IT reply or status change on your ticket drops into
  // the bell without a refresh.
  const [ticketNotifs, setTicketNotifs] = React.useState([]);

  // Ticket activity → notifications. We compare each ticket's updated_at against
  // the last value we saw (loadTicketSeen); a newer one means IT touched it since
  // you last opened it. First sighting of a ticket is seeded (no notification),
  // so you only get pinged on real changes. Recomputes on NOTIF_EVT too, so
  // opening a ticket (which records it seen) clears its notification instantly.
  const ticketsRef = React.useRef([]);
  React.useEffect(() => {
    let cancelled = false;
    const recompute = () => {
      const seen = loadTicketSeen();
      const next = { ...seen };
      let seeded = false;
      const out = [];
      for (const t of ticketsRef.current) {
        const upd = t.updated_at || t.created_at;
        if (!upd) continue;
        const prev = seen[String(t.id)];
        if (prev === undefined) { next[String(t.id)] = upd; seeded = true; continue; }
        if (new Date(upd).getTime() > new Date(prev).getTime()) {
          const when = new Date(upd);
          out.push({
            id: `tkt-${t.id}-${upd}`,
            kind: 'ticket',
            ticketId: t.id,
            unread: true,
            when: notifWhen(when),
            group: notifGroup(when),
            title: `${t.ticket_number || 'Your ticket'} — new update`,
            ticketNumber: t.ticket_number || null,
            subject: t.subject || null,
            body: `“${t.subject || 'Ticket'}” was updated by the IT Team — tap to view.`,
            color: '#FDC831',
            _ts: when.getTime(),
          });
        }
      }
      if (seeded) { try { localStorage.setItem(TICKET_SEEN_KEY, JSON.stringify(next)); } catch {} }
      if (!cancelled) setTicketNotifs(out);
    };
    const load = async () => {
      try {
        const r = await fetch('/api/tickets', { credentials: 'include', cache: 'no-store' });
        if (!r.ok || cancelled) return;
        const j = await r.json();
        ticketsRef.current = j.tickets || [];
        recompute();
      } catch { /* leave previous in place */ }
    };
    load();
    const t = setInterval(load, 60000);
    window.addEventListener(NOTIF_EVT, recompute); // re-eval when a ticket is marked seen
    return () => { cancelled = true; clearInterval(t); window.removeEventListener(NOTIF_EVT, recompute); };
  }, []);

  const rawNotifs = React.useMemo(
    () => [...ticketNotifs].sort((a, b) => b._ts - a._ts),
    [ticketNotifs],
  );

  // Same-tab broadcast (custom event) + cross-tab broadcast (storage event) so
  // dismissing in the dropdown updates the page (and vice versa) without a
  // refresh.
  React.useEffect(() => {
    const refresh = () => setPersist(loadNotifPersist());
    const onStorage = (e) => { if (e.key === NOTIF_KEY) refresh(); };
    window.addEventListener(NOTIF_EVT, refresh);
    window.addEventListener("storage", onStorage);
    return () => {
      window.removeEventListener(NOTIF_EVT, refresh);
      window.removeEventListener("storage", onStorage);
    };
  }, []);

  const update = React.useCallback((next) => {
    setPersist(next);
    saveNotifPersist(next);
    try { window.dispatchEvent(new Event(NOTIF_EVT)); } catch {}
  }, []);

  const dismissed = React.useMemo(() => new Set(persist.dismissed), [persist.dismissed]);
  const read = React.useMemo(() => new Set(persist.read), [persist.read]);

  const items = React.useMemo(
    () => rawNotifs
      .filter((i) => !dismissed.has(i.id))
      .map((i) => ({ ...i, unread: i.unread && !read.has(i.id) })),
    [rawNotifs, dismissed, read],
  );
  const unreadCount = items.filter((i) => i.unread).length;

  const markRead = React.useCallback((id) => {
    update({ ...loadNotifPersist(), read: Array.from(new Set([...loadNotifPersist().read, id])) });
  }, [update]);

  const markAllRead = React.useCallback(() => {
    const cur = loadNotifPersist();
    const allIds = rawNotifs
      .filter((i) => !new Set(cur.dismissed).has(i.id))
      .map((i) => i.id);
    update({ ...cur, read: Array.from(new Set([...cur.read, ...allIds])) });
  }, [update, rawNotifs]);

  const dismiss = React.useCallback((id) => {
    const cur = loadNotifPersist();
    update({ ...cur, dismissed: Array.from(new Set([...cur.dismissed, id])) });
  }, [update]);

  return { items, unreadCount, markRead, markAllRead, dismiss };
}

function Nav({ onHome, onNavigate, active: activeProp, onOpenNotifications, onOpenTickets, onOpenApprovals }) {
  const [activeLocal, setActiveLocal] = React.useState("Help");
  const active = activeProp || activeLocal;
  // Onboarding + Offboarding are hidden for now — those features are still WIP.
  // To restore: add "Onboarding", "Offboarding" back into this list.
  // "My Tickets" jumps to the tickets page; Approvals also lives in the account
  // menu (UserMenu).
  const links = ["Help", "Knowledge", "Status", "My Tickets"];
  return (
    <nav style={{
      position: "sticky", top: 0, zIndex: 50,
      background: "#FFFFFF",
      borderBottom: "1px solid #211E1E",
      padding: "10px 28px",
      display: "flex", alignItems: "center", justifyContent: "space-between",
      gap: 24,
    }}>
      <button
        onClick={onHome}
        className="brand-btn"
        style={{
          background: "none", border: "none", padding: 0, cursor: "pointer",
          display: "flex", alignItems: "center", gap: 10,
        }}>
        <style>{`
          .brand-btn img { transition: transform .28s cubic-bezier(.22,.61,.36,1); }
          .brand-btn:hover img { transform: rotate(-14deg) scale(1.22) !important; }
          .brand-btn:active img { transform: rotate(-8deg) scale(1.05) !important; }
          .brand-btn span { transition: letter-spacing .2s var(--ease, cubic-bezier(.22,.61,.36,1)), color .2s; }
          .brand-btn:hover span { letter-spacing: 0.10em; }
        `}</style>
        <img src={withBase("/assets/slice-logo.png")} alt="Slice" width="32" height="32" style={{
          display: "block", transform: "rotate(-10deg)", transformOrigin: "center",
        }} />
        <span style={{
          display: "inline-flex", alignItems: "center",
          color: "#211E1E",
          fontFamily: "'Archivo', sans-serif",
          fontWeight: 900, fontSize: 16,
          letterSpacing: "0.06em", textTransform: "uppercase",
        }}>IT Hub</span>
      </button>

      <div style={{display: "flex", gap: 28, alignItems: "center"}}>
        {links.map((l) => (
          <a key={l} href="#" onClick={(e)=>{e.preventDefault(); setActiveLocal(l); onNavigate && onNavigate(l);}}
            onMouseEnter={(e)=>{
              e.currentTarget.style.transform = "scale(1.08)";
              e.currentTarget.style.color = active===l ? "#211E1E" : "rgba(33,30,30,0.85)";
              const u = e.currentTarget.querySelector("[data-underline]");
              if (u) {
                u.style.opacity = active===l ? "0.55" : "0.55";
                u.style.transform = "scaleX(1)";
              }
            }}
            onMouseLeave={(e)=>{
              e.currentTarget.style.transform = "scale(1)";
              e.currentTarget.style.color = active===l ? "#211E1E" : "rgba(33,30,30,0.68)";
              const u = e.currentTarget.querySelector("[data-underline]");
              if (u) {
                u.style.opacity = active===l ? "1" : "0";
                u.style.transform = active===l ? "scaleX(1)" : "scaleX(0)";
              }
            }}
            style={{
              color: active===l ? "#211E1E" : "rgba(33,30,30,0.68)",
              textDecoration: "none",
              fontSize: 14, fontWeight: 600,
              letterSpacing: "-0.005em",
              position: "relative", padding: "4px 0",
              display: "inline-block",
              transformOrigin: "center center",
              transition: "color .12s ease, transform .18s cubic-bezier(.34,1.56,.64,1)",
            }}>
            {l}
            <span data-underline style={{
              position: "absolute", left: "-2%", right: "-2%", bottom: -2,
              height: 6,
              backgroundImage: `url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 80 8' preserveAspectRatio='none'><path d='M2 4 Q 20 1, 40 4 T 78 4' fill='none' stroke='%23FDC831' stroke-width='4' stroke-linecap='round'/></svg>")`,
              backgroundRepeat: "no-repeat", backgroundSize: "100% 100%",
              pointerEvents: "none",
              opacity: active===l ? 1 : 0,
              transform: active===l ? "scaleX(1)" : "scaleX(0)",
              transformOrigin: "left center",
              transition: "opacity .18s ease, transform .22s cubic-bezier(.34,1.56,.64,1)",
            }}/>
          </a>
        ))}
      </div>

      <div style={{display: "flex", alignItems: "center", gap: 12}}>
        <NotificationsMenu onViewAll={onOpenNotifications} onOpenTickets={onOpenTickets} />
        <ItServicesButton />
        <UserMenu onOpenNotifications={onOpenNotifications} onOpenTickets={onOpenTickets} onOpenApprovals={onOpenApprovals} />
      </div>
    </nav>
  );
}

// --- Back-to-SliceDesk button -------------------------------------------------
// Sits between the Notifications bell and the user avatar. Same-tab nav (no
// target=_blank) so it works inside the Slice Mac App wrapper, which doesn't
// honor new-tab requests. Brand red + black border to match other Slice CTAs.
// Standalone only: embedded as a SliceDesk module the shell's own chrome is
// already around us, and the link would nav the iframe to SliceDesk-in-SliceDesk.
function ItServicesButton() {
  if (IS_EMBEDDED) return null;
  return (
    <a
      href="https://slicedesk.slice.services/"
      title="Back to SliceDesk"
      aria-label="Back to SliceDesk"
      className="back-to-slicedesk"
      style={{
        height: 28,
        padding: "0 9px",
        display: "inline-flex", alignItems: "center", gap: 6,
        background: "#B92323",
        color: "#FFFFFF",
        borderRadius: 4, border: "1px solid #211E1E",
        boxShadow: "1px 1px 0 #211E1E",
        cursor: "pointer", textDecoration: "none",
        fontFamily: "'Archivo', sans-serif",
        fontWeight: 600, fontSize: 12, letterSpacing: "0.01em",
        transition: "transform .15s ease, box-shadow .15s ease",
      }}
      onMouseEnter={(e) => {
        e.currentTarget.style.transform = "translate(-1px,-1px)";
        e.currentTarget.style.boxShadow = "2px 2px 0 #211E1E";
      }}
      onMouseLeave={(e) => {
        e.currentTarget.style.transform = "none";
        e.currentTarget.style.boxShadow = "1px 1px 0 #211E1E";
      }}
    >
      {/* Arrow slides left on hover via the .back-to-slicedesk:hover svg rule
          injected once below — keeps the React handlers free of arrow state. */}
      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor"
        strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"
        style={{ transition: "transform .18s ease" }}>
        <path d="M19 12H5"/>
        <path d="M12 19l-7-7 7-7"/>
      </svg>
      SliceDesk
    </a>
  );
}

// One-time stylesheet for the arrow nudge on hover. Inlined as a <style>
// because the rest of this file styles inline and we don't want to wire a
// CSS-in-JS dep just for one rule.
if (typeof document !== "undefined" && !document.getElementById("back-to-slicedesk-css")) {
  const s = document.createElement("style");
  s.id = "back-to-slicedesk-css";
  s.textContent = `.back-to-slicedesk:hover svg { transform: translateX(-2px); }`;
  document.head.appendChild(s);
}

// --- Notifications dropdown ---------------------------------------------------
// Bell button that opens a small feed of recent IT updates. Items have a type
// (status, ticket, access, security) and an "unread" dot; clicking marks all
// read. Matches the user menu's visual language — hard 5px shadow, cheese
// header, charcoal outlines.
// Shared behaviour for the nav's two popovers (notifications, account):
//   - opening springs out from the trigger's corner; closing plays a short
//     exit instead of vanishing (the panel stays mounted ~140ms to do it)
//   - click outside / Esc closes, and Esc hands focus back to the trigger
//   - ↑ ↓ Home End move between the menu's items; Tab keeps the order
function useNavPopover() {
  const [open, setOpen] = React.useState(false);
  const [closing, setClosing] = React.useState(false);
  const wrapRef = React.useRef(null);
  const triggerRef = React.useRef(null);
  const panelRef = React.useRef(null);
  const timer = React.useRef(null);
  const reduce = typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  const close = React.useCallback((refocus) => {
    if (!open || closing) return;
    setClosing(true);
    clearTimeout(timer.current);
    timer.current = setTimeout(() => { setOpen(false); setClosing(false); }, reduce ? 0 : 140);
    if (refocus && triggerRef.current) triggerRef.current.focus();
  }, [open, closing, reduce]);
  const toggle = () => { if (open && !closing) close(false); else { clearTimeout(timer.current); setClosing(false); setOpen(true); } };
  React.useEffect(() => () => clearTimeout(timer.current), []);

  React.useEffect(() => {
    if (!open || closing) return undefined;
    const items = () => [...(panelRef.current ? panelRef.current.querySelectorAll('[role="menuitem"]:not([disabled])') : [])];
    // Focus lands on the panel, not the first item — so a mouse user doesn't
    // see a stray focus ring, while arrows start from the top.
    if (panelRef.current) panelRef.current.focus({ preventScroll: true });
    const onDoc = (e) => { if (wrapRef.current && !wrapRef.current.contains(e.target)) close(false); };
    const onKey = (e) => {
      if (e.key === 'Escape') { e.preventDefault(); close(true); return; }
      if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(e.key)) return;
      const list = items(); if (!list.length) return;
      e.preventDefault();
      const i = list.indexOf(document.activeElement);
      const next = e.key === 'Home' ? 0 : e.key === 'End' ? list.length - 1
        : e.key === 'ArrowDown' ? (i + 1) % list.length : (i <= 0 ? list.length - 1 : i - 1);
      list[next].focus();
    };
    document.addEventListener('mousedown', onDoc);
    document.addEventListener('keydown', onKey);
    return () => { document.removeEventListener('mousedown', onDoc); document.removeEventListener('keydown', onKey); };
  }, [open, closing, close]);

  return { open, closing, toggle, close, wrapRef, triggerRef, panelRef };
}

const NotifKindIcon = ({ kind }) => (
  <span className={'notif-kind notif-kind-' + (kind || 'info')} aria-hidden="true">
    {kind === 'ticket' ? (
      <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.1" strokeLinecap="round" strokeLinejoin="round"><path d="M3 8.5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2V10a2 2 0 0 0 0 4v1.5a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V14a2 2 0 0 0 0-4V8.5Z"/><path d="M14 7v10" strokeDasharray="1.5 2.5"/></svg>
    ) : kind === 'approval' ? (
      <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M9 11l3 3L22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/></svg>
    ) : (
      <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.1" strokeLinecap="round" strokeLinejoin="round"><path d="M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9"/><path d="M10.3 21a1.94 1.94 0 0 0 3.4 0"/></svg>
    )}
  </span>
);

function NotificationsMenu({ onViewAll, onOpenTickets }) {
  const pop = useNavPopover();
  // Shared store — the dropdown shows the latest 6; read state is persisted
  // and in sync with the full Notifications page.
  const { items: allItems, unreadCount, markRead, markAllRead } = useNotifications();
  const items = allItems.slice(0, 6);

  // The bell swings once when a NEW unread arrives (not on every render,
  // and not on first load).
  const [ring, setRing] = React.useState(0);
  const prevUnread = React.useRef(unreadCount);
  React.useEffect(() => {
    if (unreadCount > prevUnread.current) setRing((n) => n + 1);
    prevUnread.current = unreadCount;
  }, [unreadCount]);

  // Group rows under Today / Yesterday / Earlier, in order.
  const groups = [];
  items.forEach((it) => {
    const g = it.group || 'Earlier';
    const last = groups[groups.length - 1];
    if (last && last.name === g) last.items.push(it); else groups.push({ name: g, items: [it] });
  });
  let rowIndex = 0;

  const openItem = (it) => {
    markRead(it.id);
    if (it.kind === 'ticket' && onOpenTickets) {
      pop.close(false);
      if (it.ticketId != null) { try { window.__PORTAL_OPEN_TICKET__ = it.ticketId; } catch {} }
      onOpenTickets();
    }
  };

  return (
    <div ref={pop.wrapRef} style={{ position: 'relative' }}>
      <button
        ref={pop.triggerRef}
        type="button"
        className={'nav-trigger nav-bell' + (pop.open && !pop.closing ? ' is-open' : '')}
        aria-label={`Notifications${unreadCount ? ` (${unreadCount} unread)` : ''}`}
        aria-haspopup="menu"
        aria-expanded={pop.open && !pop.closing}
        onClick={pop.toggle}
      >
        <svg key={ring} className={ring ? 'nav-bell-swing' : undefined} width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
          <path d="M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9"/>
          <path d="M10.3 21a1.94 1.94 0 0 0 3.4 0"/>
        </svg>
        {unreadCount > 0 && <span key={unreadCount} className="nav-bell-count" aria-hidden="true">{unreadCount > 9 ? '9+' : unreadCount}</span>}
      </button>

      {pop.open && (
        <div ref={pop.panelRef} tabIndex={-1} role="menu" aria-label="Notifications"
          className={'nav-pop notif-pop' + (pop.closing ? ' is-closing' : '')}>
          <div className="nav-pop-head">
            <div style={{ minWidth: 0 }}>
              <div className="nav-pop-title">Notifications</div>
              <div className="nav-pop-sub">{unreadCount > 0 ? `${unreadCount} unread` : 'You’re all caught up'}</div>
            </div>
            {unreadCount > 0 && (
              <button type="button" className="notif-markall" onClick={markAllRead}>
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><path d="M2.5 13l3.5 3.5L13 9.5M11 16.5l1.5 1.5L21 9.5"/></svg>
                Mark all read
              </button>
            )}
          </div>

          <div className="notif-list">
            {items.length === 0 ? (
              <div className="notif-empty">
                <span className="notif-empty-mark" aria-hidden="true">
                  <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#211E1E" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M20 6 9 17l-5-5"/></svg>
                </span>
                <div className="notif-empty-title">Nothing new</div>
                <div className="notif-empty-body">Replies and status changes on your tickets land here.</div>
              </div>
            ) : groups.map((g) => (
              <div key={g.name} role="group" aria-label={g.name}>
                <div className="notif-group">{g.name}</div>
                {g.items.map((it) => {
                  const i = rowIndex++;
                  return (
                    <button key={it.id} role="menuitem" type="button"
                      className={'notif-row nav-pop-item' + (it.unread ? ' is-unread' : '')}
                      style={{ '--i': i }}
                      onClick={() => openItem(it)}>
                      <NotifKindIcon kind={it.kind} />
                      <span className="notif-main">
                        <span className="notif-title">{it.subject || it.title}</span>
                        <span className="notif-body">
                          {it.ticketNumber ? <><span className="notif-num">{it.ticketNumber}</span> · </> : null}
                          {it.subject ? 'Updated by the IT Team' : it.body}
                        </span>
                      </span>
                      <span className="notif-side">
                        <span className="notif-when">{it.when}</span>
                        {it.unread ? <span className="notif-dot" aria-label="Unread" /> : <span className="notif-go" aria-hidden="true">→</span>}
                      </span>
                    </button>
                  );
                })}
              </div>
            ))}
          </div>

          <button type="button" role="menuitem" className="nav-pop-foot"
            onClick={() => { pop.close(false); onViewAll && onViewAll(); }}>
            View all notifications <span aria-hidden="true">→</span>
          </button>
        </div>
      )}
    </div>
  );
}

// --- User avatar + dropdown ---------------------------------------------------
// Avatar pill with initials, presence dot and caret; opens the account menu
// (notifications, tickets, approvals, admin, sign out) via useNavPopover.
function UserMenu({ onOpenNotifications, onOpenTickets, onOpenApprovals }) {
  const pop = useNavPopover();
  const { unreadCount } = useNotifications();
  const _userName = (typeof window !== 'undefined' && window.PORTAL_CURRENT_USER) || '';
  const _userEmail = (typeof window !== 'undefined' && window.PORTAL_CURRENT_EMAIL) || '';
  // The admin console is restricted to slicedesk super_admins (the server
  // enforces it on every admin route); only surface its entry point to them.
  const _isSuperAdmin = (typeof window !== 'undefined' && window.PORTAL_CURRENT_ROLE) === 'super_admin';
  const _initials = _userName.trim().split(/\s+/).slice(0, 2).map(function(w){return (w[0]||'').toUpperCase();}).join('') || '?';
  const _displayName = _userName || 'Loading…';

  const items = [
    { label: 'Notifications', hint: 'Updates & alerts', action: 'notifications', badge: unreadCount || null, icon: (
      <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9"/><path d="M10.3 21a1.94 1.94 0 0 0 3.4 0"/></svg>
    )},
    { label: 'My tickets', hint: 'Issues & requests you raised', action: 'tickets', icon: (
      <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M3 8.5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2V10a2 2 0 0 0 0 4v1.5a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V14a2 2 0 0 0 0-4V8.5Z"/><path d="M14 7v10" strokeDasharray="1.5 2.5"/></svg>
    )},
    { label: 'Approvals', hint: 'Requests awaiting your sign-off', action: 'approvals', icon: (
      <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M9 11l3 3L22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/></svg>
    )},
    ...(_isSuperAdmin ? [{ label: 'Admin', hint: 'Manage guides & content', action: 'admin', icon: (
      <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 2l3 7h7l-5.5 4.5L18 21l-6-4-6 4 1.5-7.5L2 9h7z"/></svg>
    )}] : []),
  ];

  const run = (action) => {
    pop.close(false);
    if (action === 'notifications' && onOpenNotifications) onOpenNotifications();
    else if (action === 'tickets' && onOpenTickets) onOpenTickets();
    else if (action === 'approvals' && onOpenApprovals) onOpenApprovals();
    else if (action === 'admin') window.location.href = withBase('/admin.html');
  };
  const isOpen = pop.open && !pop.closing;

  return (
    <div ref={pop.wrapRef} style={{ position: 'relative' }}>
      <button
        ref={pop.triggerRef}
        type="button"
        onClick={pop.toggle}
        aria-haspopup="menu"
        aria-expanded={isOpen}
        aria-label="Account menu"
        className={'nav-trigger nav-account' + (isOpen ? ' is-open' : '')}
      >
        <span className="nav-account-avatar">
          {_initials}
          <span className="nav-presence" aria-hidden="true" />
        </span>
        <svg className="nav-caret" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><polyline points="6 9 12 15 18 9"/></svg>
      </button>

      {pop.open && (
        <div ref={pop.panelRef} tabIndex={-1} role="menu" aria-label="Account"
          className={'nav-pop account-pop' + (pop.closing ? ' is-closing' : '')}>
          <div className="account-head">
            <div className="account-avatar">{_initials}<span className="nav-presence" aria-hidden="true" /></div>
            <div style={{ minWidth: 0, flex: 1 }}>
              <div className="account-name">{_displayName}</div>
              <div className="account-email" title={_userEmail}>{_userEmail}</div>
            </div>
          </div>

          <div className="account-items">
            {items.map((it, i) => (
              <button key={it.label} role="menuitem" type="button" className="account-item nav-pop-item"
                style={{ '--i': i }} onClick={() => run(it.action)}>
                <span className="account-icon">{it.icon}</span>
                <span style={{ flex: 1, minWidth: 0 }}>
                  <span className="account-label">{it.label}</span>
                  <span className="account-hint">{it.hint}</span>
                </span>
                {it.badge != null
                  ? <span className="account-badge">{it.badge > 9 ? '9+' : it.badge}</span>
                  : <span className="account-go" aria-hidden="true">→</span>}
              </button>
            ))}
          </div>

          <div className="account-sep" />
          <div style={{ padding: '6px' }}>
            <button role="menuitem" type="button" className="account-item account-signout nav-pop-item" style={{ '--i': items.length }}
              onClick={async () => { pop.close(false); try { await fetch('/auth/logout', { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' } }); } catch (e) {} window.location.href = '/login'; }}>
              <span className="account-icon">
                <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><polyline points="16 17 21 12 16 7"/><line x1="21" y1="12" x2="9" y2="12"/></svg>
              </span>
              <span className="account-label">Sign out</span>
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

function Footer() {
  const [beats, setBeats] = React.useState(0);
  // Track rapid clicks. Once the user has clicked 3+ times in quick succession,
  // we cycle through a playful palette on every subsequent click. After ~1.2s
  // of inactivity the streak resets so casual visitors never see the easter egg.
  const [streak, setStreak] = React.useState(0);
  const lastClickRef = React.useRef(0);
  const resetTimerRef = React.useRef(null);

  // Palette of pill backgrounds that read against black text + heart.
  // Order is hand-picked to feel like a celebration cycling through the brand.
  const PALETTE = [
    { bg: "#FFFFFF", heart: "#FDC831", spark: "#FDC831" }, // default Slice yellow heart
    { bg: "#FDC831", heart: "#FFFFFF", spark: "#211E1E" }, // mustard pop
    { bg: "#FFE5A8", heart: "#B92323", spark: "#B92323" }, // cream + cherry
    { bg: "#C7E8B8", heart: "#0A8A3E", spark: "#0A8A3E" }, // mint + leaf
    { bg: "#BFE0F5", heart: "#1E5FB2", spark: "#1E5FB2" }, // sky + ink
    { bg: "#F4C5DC", heart: "#9B2D6B", spark: "#9B2D6B" }, // bubblegum
    { bg: "#E0CFF5", heart: "#5B2A9B", spark: "#5B2A9B" }, // grape
    { bg: "#FFB89A", heart: "#B94A0F", spark: "#B94A0F" }, // peach + rust
  ];
  // Only cycle once they're hammering the button — otherwise stay on default.
  const styleIdx = streak >= 3 ? (streak - 2) % PALETTE.length : 0;
  const skin = PALETTE[styleIdx];

  const pulse = () => {
    const now = Date.now();
    const fast = now - lastClickRef.current < 900;
    lastClickRef.current = now;
    setStreak(s => fast ? s + 1 : 1);
    setBeats(b => b + 1);
    // Reset the streak after a beat of inactivity so the easter egg is rediscoverable.
    if (resetTimerRef.current) clearTimeout(resetTimerRef.current);
    resetTimerRef.current = setTimeout(() => setStreak(0), 2000);
  };

  return (
    <div style={{
      maxWidth: 1120,
      // marginTop: auto lets the flex parent (.page-scroll) push the footer
      // to the bottom of the viewport on short pages; paddingTop keeps the
      // footer separated from content on long pages.
      margin: "auto auto 0",
      padding: "80px 28px 24px",
      width: "100%", flexShrink: 0,
      display: "flex", justifyContent: "center",
    }}>
      <style>{`
        @keyframes heartBeat {
          0%, 100% { transform: scale(1); }
          20% { transform: scale(1.35); }
          40% { transform: scale(0.92); }
          60% { transform: scale(1.18); }
          80% { transform: scale(0.98); }
        }
        @keyframes sparkOut {
          0%   { opacity: 1; transform: translate(-50%, -50%) scale(0.2); }
          100% { opacity: 0; transform: translate(-50%, -50%) scale(2.4); }
        }
        @keyframes pillWiggle {
          0%, 100% { transform: rotate(0deg); }
          25% { transform: rotate(-2.5deg); }
          75% { transform: rotate(2.5deg); }
        }
      `}</style>
      <button
        type="button"
        onClick={pulse}
        aria-label="Say hi to the Slice IT team"
        style={{
          display: "inline-flex", alignItems: "center", gap: 7,
          padding: "7px 14px",
          background: skin.bg,
          border: "1px solid #000000",
          borderRadius: 999,
          boxShadow: "2.5px 2.5px 0 #000000",
          fontSize: 12, fontWeight: 600, color: "#000000",
          letterSpacing: "-0.005em",
          transition: "transform .2s var(--ease), box-shadow .2s var(--ease), background .25s ease",
          cursor: "pointer",
          fontFamily: "inherit",
          // Tiny wiggle once the streak is going so the user knows the button noticed.
          animation: streak >= 3 ? "pillWiggle .35s ease" : "none",
          animationDelay: "0s",
          // Restart the wiggle on each click — keying the button isn't an option,
          // so we use the beats counter as a render trigger and the animation
          // re-runs because skin.bg changes.
        }}
        onMouseEnter={(e)=>{e.currentTarget.style.transform="translate(-1.5px,-1.5px)";e.currentTarget.style.boxShadow="2px 2px 0 #000000";}}
        onMouseLeave={(e)=>{e.currentTarget.style.transform="none";e.currentTarget.style.boxShadow="2.5px 2.5px 0 #000000";}}
      >
        <span>Built by the</span>
        <span style={{
          fontFamily: "'Archivo', sans-serif", fontWeight: 700, fontSize: 13,
          letterSpacing: "-0.015em", textTransform: "uppercase",
        }}>Slice IT Team</span>
        <span style={{
          position: "relative",
          width: 15, height: 14,
          display: "inline-grid", placeItems: "center",
        }}>
          {beats > 0 && (
            <span key={beats} style={{
              position: "absolute",
              top: "50%", left: "50%",
              width: 22, height: 22,
              borderRadius: "50%",
              border: `2px solid ${skin.spark}`,
              transform: "translate(-50%, -50%)",
              animation: "sparkOut .55s ease-out forwards",
              pointerEvents: "none",
            }}/>
          )}
          <svg
            key={`h-${beats}`}
            width="13" height="12" viewBox="0 0 24 22"
            fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"
            style={{
              display: "block",
              animation: beats > 0 ? "heartBeat .7s ease both" : "none",
              transformOrigin: "center",
              transition: "fill .25s ease",
            }}
          >
            <path d="M12 20.5s-8.5-5-8.5-11.2A4.8 4.8 0 0 1 12 5.3a4.8 4.8 0 0 1 8.5 4c0 6.2-8.5 11.2-8.5 11.2Z"
              fill={skin.heart} stroke="#000000" strokeWidth="2.2" strokeLinejoin="round" strokeLinecap="round" />
          </svg>
        </span>
      </button>
    </div>
  );
}

// Premium-looking card
function Card({ children, style, onClick, interactive }) {
  return (
    <div
      onClick={onClick}
      className={`surface ${interactive ? "surface-interactive" : ""}`}
      style={{
        borderRadius: 16,
        ...style,
      }}
    >
      {children}
    </div>
  );
}

// Status pill
function Pill({ tone = "neutral", children, small }) {
  const toneClass = tone === "green" ? "tone-green" : tone === "amber" ? "tone-amber" : tone === "red" ? "tone-red" : tone === "accent" ? "tone-accent" : "";
  return (
    <span className={`pill-flat ${toneClass}`} style={small ? { padding: "2px 8px", fontSize: 10.5 } : undefined}>
      {children}
    </span>
  );
}

// Suggestion chip (quick prompts under the search bar)
function Chip({ icon, label, onClick }) {
  const Icon = window[icon];
  return (
    <button onClick={onClick} className="chip-flat">
      <Icon size={14} stroke={2.5} style={{color: "#000000"}} />
      {label}
    </button>
  );
}

// Radio card — used inside the question flow
function ChoiceCard({ selected, title, hint, onSelect, index, total }) {
  return (
    <button
      onClick={onSelect}
      onMouseEnter={(e) => {
        if (selected) return;
        e.currentTarget.style.transform = "translate(-2px, -2px)";
        e.currentTarget.style.boxShadow = "3px 3px 0 #211E1E";
        e.currentTarget.style.background = "#FFF9E6";
      }}
      onMouseLeave={(e) => {
        if (selected) return;
        e.currentTarget.style.transform = "none";
        e.currentTarget.style.boxShadow = "2px 2px 0 #211E1E";
        e.currentTarget.style.background = "#FFFFFF";
      }}
      onMouseDown={(e) => {
        e.currentTarget.style.transform = "translate(1px, 1px)";
        e.currentTarget.style.boxShadow = selected ? "2px 2px 0 #211E1E" : "1px 1px 0 #211E1E";
      }}
      onMouseUp={(e) => {
        if (selected) {
          e.currentTarget.style.transform = "none";
          e.currentTarget.style.boxShadow = "3px 3px 0 #211E1E";
        } else {
          e.currentTarget.style.transform = "translate(-2px, -2px)";
          e.currentTarget.style.boxShadow = "3px 3px 0 #211E1E";
        }
      }}
      style={{
        textAlign: "left",
        display: "flex", alignItems: "flex-start", gap: 14,
        padding: "16px 18px",
        width: "100%",
        background: selected ? "#FDC831" : "#FFFFFF",
        border: "1px solid #211E1E",
        borderRadius: 14,
        cursor: "pointer",
        transition: "transform .15s var(--ease), box-shadow .15s var(--ease), background .15s",
        boxShadow: selected ? "3px 3px 0 #211E1E" : "2px 2px 0 #211E1E",
        transform: "translateZ(0)",
        animation: `fadeUp .45s var(--ease) both`,
        animationDelay: `${(index||0) * 50}ms`,
      }}
    >
      <div style={{
        width: 22, height: 22, borderRadius: "50%",
        border: "1px solid #211E1E",
        background: selected ? "#211E1E" : "#FFFFFF",
        display: "grid", placeItems: "center",
        transition: "transform .2s var(--ease), box-shadow .2s var(--ease), background-color .2s var(--ease), color .2s var(--ease), border-color .2s var(--ease), opacity .2s var(--ease)",
        marginTop: 1, flexShrink: 0,
      }}>
        {selected && <IconCheck size={12} stroke={3} style={{color: "#FDC831"}} />}
      </div>
      <div style={{flex: 1}}>
        <div style={{fontSize: 14.5, fontWeight: 700, color: "#211E1E", letterSpacing: "-0.012em"}}>{title}</div>
        {hint && <div style={{fontSize: 12.5, color: "#4A3F2E", marginTop: 3}}>{hint}</div>}
      </div>
    </button>
  );
}

// Multi-select chip
function MultiChip({ selected, title, onSelect, index }) {
  return (
    <button
      onClick={onSelect}
      style={{
        display: "inline-flex", alignItems: "center", gap: 8,
        padding: "10px 16px",
        background: selected ? "#DA3327" : "#FFFFFF",
        color: selected ? "#FFFFFF" : "#211E1E",
        border: `2px solid ${selected ? "#DA3327" : "#211E1E"}`,
        borderRadius: 4,
        fontSize: 13, fontWeight: 700,
        letterSpacing: "-0.005em",
        cursor: "pointer",
        boxShadow: selected ? "2px 2px 0 #211E1E" : "2px 2px 0 #211E1E",
        transition: "transform .18s var(--ease), box-shadow .18s var(--ease), background .18s",
        animation: `fadeUp .45s var(--ease) both`,
        animationDelay: `${(index||0) * 40}ms`,
        fontFamily: "'Archivo', sans-serif",
      }}
      onMouseEnter={(e) => {
        if (selected) return;
        e.currentTarget.style.transform = "translate(-2px,-2px)";
        e.currentTarget.style.boxShadow = "3px 3px 0 #211E1E";
        e.currentTarget.style.background = "#FFF9E6";
      }}
      onMouseLeave={(e) => {
        if (selected) return;
        e.currentTarget.style.transform = "none";
        e.currentTarget.style.boxShadow = "2px 2px 0 #211E1E";
        e.currentTarget.style.background = "#FFFFFF";
      }}
      onMouseDown={(e) => {
        e.currentTarget.style.transform = "translate(1px,1px)";
        e.currentTarget.style.boxShadow = "1px 1px 0 #211E1E";
      }}
      onMouseUp={(e) => {
        e.currentTarget.style.transform = "translate(-2px,-2px)";
        e.currentTarget.style.boxShadow = "3px 3px 0 #211E1E";
      }}
    >
      <span style={{
        width: 16, height: 16, borderRadius: 4,
        border: `2px solid ${selected ? "#FFFFFF" : "#211E1E"}`,
        display: "grid", placeItems: "center",
        background: selected ? "transparent" : "#FFFFFF",
        transition: "transform .2s var(--ease), box-shadow .2s var(--ease), background-color .2s var(--ease), color .2s var(--ease), border-color .2s var(--ease), opacity .2s var(--ease)",
      }}>
        {selected && <IconCheck size={10} stroke={3.5} style={{color: "#FFFFFF"}} />}
      </span>
      {title}
    </button>
  );
}

// Progress dots
function Progress({ current, total }) {
  return (
    <div style={{display:"flex", gap: 6, alignItems:"center"}}>
      {Array.from({length: total}).map((_, i) => (
        <div key={i} style={{
          width: i === current ? 28 : 10, height: 10, borderRadius: 999,
          background: i <= current ? "#211E1E" : "#FFFFFF",
          border: "1px solid #211E1E",
          transition: "width .4s var(--ease), transform .4s var(--ease), box-shadow .4s var(--ease), background-color .4s var(--ease), color .4s var(--ease), border-color .4s var(--ease), opacity .4s var(--ease)",
        }}/>
      ))}
    </div>
  );
}

// Typing dots
function TypingDots() {
  return (
    <div style={{display:"inline-flex", gap: 4, alignItems:"center", padding: "4px 2px"}}>
      {[0,1,2].map(i => (
        <span key={i} style={{
          width: 6, height: 6, borderRadius: "50%", background: "var(--ink-4)",
          animation: `typing 1.2s ${i * 0.15}s infinite var(--ease)`,
        }}/>
      ))}
    </div>
  );
}

// Pizzeria-flavoured loading patter — cycles through a sequence of messages
// while we wait for an LLM/network call so the wait doesn't feel like dead
// time. Each message fades up; the last one sticks once we run out.
const PATIENCE_MESSAGES = [
  "Kneading the dough — picking the right slice for you…",
  "Reading the menu of guides…",
  "Pulling the freshest answers from the oven…",
  "Sprinkling the right toppings…",
  "Boxing it up — almost there…",
];

// Practical Slice-IT tips that cycle on loading screens. Edit / extend
// freely; order doesn't matter — the picker shuffles on each loading
// screen so back-to-back loads don't repeat.
const IT_TIPS = [
  "Restart your device once a week — most weird issues just go away after a fresh reboot.",
  "**GlobalProtect** is our VPN. If anything internal won't load, connect to GlobalProtect first.",
  "**OneLogin** is the SSO. Most app login issues are actually OneLogin issues — try resetting that first.",
  "After changing your OneLogin password, your **Mac keychain** may need a refresh — open Keychain Access and unlock with your new password.",
  "Quick questions go in **Slack** — Slice's company-wide chat. Anything that needs tracking goes to [Support](https://it.slicelife.com).",
  "Email + docs run on **Gmail** and **Google Workspace** — Drive, Docs, Sheets, Calendar all live there. We don't use Outlook.",
  "**1Password** is where shared team passwords live. Never paste credentials into Slack or a Google Doc — share via 1Password instead.",
  "Slice's AI tools are **Claude** (the chat assistant you're using) and **Claude Code** (the CLI for engineering work).",
  "**Jabra USB** headsets are plug-and-play. If yours isn't working, try a different USB port before troubleshooting drivers.",
  "Press **⌘ + Space** (Mac) or **Win + S** (Windows) to find apps quickly — faster than hunting through Applications.",
  "The **CCP** (Contact Control Panel) lives inside **Salesforce** — open Salesforce first, then look for the phone widget.",
  "**Mac password ≠ OneLogin password.** Mac login uses your local password set at provisioning by **Jamf**.",
  "**Windows login = OneLogin password.** Intune-enrolled machines use the same credentials as Slice apps.",
  "Update macOS / Windows when you see the prompt — **Jamf** and **Intune** push security patches automatically.",
  "Two-factor codes expire in 30 seconds — if yours keep failing, your phone's clock may be out of sync.",
  "Back up important docs to **Google Drive**, not your desktop — Jamf/Intune can re-image a machine without warning.",
  "Locked out of your laptop? File a **Support** ticket from your phone at [it.slicelife.com](https://it.slicelife.com) — the IT Team can verify you another way.",
];

// Renders a single tip card with a soft auto-rotation. We pick a random
// starting offset on mount so two consecutive loading screens don't feel
// repetitive. Tips render through the existing markdown inline pipeline
// so **bold** + [text](url) work.
function TipCard({ tips = IT_TIPS, intervalMs = 7000, style }) {
  const [start] = React.useState(() => Math.floor(Math.random() * tips.length));
  const [step, setStep] = React.useState(0);
  React.useEffect(() => {
    const t = setInterval(() => setStep((s) => s + 1), intervalMs);
    return () => clearInterval(t);
  }, [intervalMs, tips.length]);
  const tip = tips[(start + step) % tips.length];

  // Reuse renderMarkdown for inline formatting — wrap the tip in a single
  // paragraph so bold + links work, then unwrap to flatten.
  const formatted = renderMarkdown(tip);

  return (
    <div
      style={{
        margin: "16px 0 0",
        padding: "14px 18px",
        background: "#FFF9E6",
        border: "1px solid #211E1E",
        borderRadius: 12,
        boxShadow: "2px 2px 0 #211E1E",
        display: "flex",
        gap: 12,
        alignItems: "flex-start",
        ...style,
      }}
    >
      <div
        aria-hidden
        style={{
          flexShrink: 0,
          width: 28, height: 28, borderRadius: 8,
          background: "#FDC831",
          border: "1px solid #211E1E",
          display: "grid", placeItems: "center",
          fontSize: 14,
        }}
      >💡</div>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{
          fontFamily: "'Archivo', sans-serif",
          fontSize: 10.5, fontWeight: 900, letterSpacing: "0.08em",
          textTransform: "uppercase", color: "#78684C",
          marginBottom: 4,
        }}>Tip</div>
        <div
          key={step}
          style={{
            fontSize: 13.5, lineHeight: 1.5, color: "#211E1E",
            animation: "fadeUp .4s var(--ease) both",
          }}
        >
          {formatted}
        </div>
      </div>
    </div>
  );
}
function LoadingPatter({ messages = PATIENCE_MESSAGES, intervalMs = 1500, style }) {
  const [i, setI] = React.useState(0);
  React.useEffect(() => {
    if (i >= messages.length - 1) return;
    const t = setTimeout(() => setI((x) => Math.min(messages.length - 1, x + 1)), intervalMs);
    return () => clearTimeout(t);
  }, [i, messages.length, intervalMs]);
  return (
    <span
      key={i}
      style={{
        fontSize: 12.5, color: "#78684C", fontWeight: 500,
        display: "inline-block",
        animation: "fadeUp .35s var(--ease) both",
        ...style,
      }}
    >
      {messages[i]}
    </span>
  );
}

// Injected once; keyframes for these components
function GlobalKeyframes() {
  return (
    <style>{`
      @keyframes fadeUp { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }
      @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
      @keyframes typing { 0%,60%,100% { transform: translateY(0); opacity: .35; } 30% { transform: translateY(-4px); opacity: 1; } }
      @keyframes pulse { 0%,100% { transform: scale(1); opacity: .7; } 50% { transform: scale(1.5); opacity: 0; } }
      @keyframes shimmer { 0% { background-position: -200% 0; } 100% { background-position: 200% 0; } }
      @keyframes slideInRight { from { transform: translateX(100%); } to { transform: translateX(0); } }
      @keyframes navSquiggle {
        0%, 100% { transform: scaleX(1) translateY(0) rotate(0deg); }
        25% { transform: scaleX(1) translateY(-1px) rotate(-0.8deg); }
        50% { transform: scaleX(1) translateY(0) rotate(0deg); }
        75% { transform: scaleX(1) translateY(1px) rotate(0.8deg); }
      }
      @keyframes pizzaPulse {
        0%, 100% { transform: scale(1) rotate(0deg); box-shadow: 0 0 0 0 rgba(253,200,49,0); }
        50%      { transform: scale(1.06) rotate(-3deg); box-shadow: 0 0 0 4px rgba(253,200,49,0.35); }
      }
    `}</style>
  );
}

Object.assign(window, {
  Nav, Footer, Card, Pill, Chip, ChoiceCard, MultiChip, Progress, TypingDots, GlobalKeyframes
});

// ---------- NOTIFICATIONS PAGE ----------
// Full notifications view linked from the bell-dropdown's "View all" footer.
// Same yellow + cream module pattern as Profile / Knowledge / Status.
function NotificationsPage({ onBack }) {
  // Pulled from the shared store so dismissals + reads survive a refresh and
  // stay in sync with the bell-dropdown.
  const { items, unreadCount, markRead, markAllRead, dismiss } = useNotifications();
  const [filter, setFilter] = React.useState("all"); // all | unread | ticket | status | access | security
  const KIND_META = {
    ticket:   { label: "Ticket",    color: "#FDC831" },
    status:   { label: "Status",    color: "#D4F4D4" },
    access:   { label: "Access",    color: "#E4DBFF" },
    security: { label: "Security",  color: "#FFD4D0" },
    digest:   { label: "Digest",    color: "#C4E3FF" },
  };
  const filtered = React.useMemo(() => {
    if (filter === "all") return items;
    if (filter === "unread") return items.filter(i => i.unread);
    return items.filter(i => i.kind === filter);
  }, [items, filter]);
  const grouped = React.useMemo(() => {
    const out = new Map();
    for (const it of filtered) {
      if (!out.has(it.group)) out.set(it.group, []);
      out.get(it.group).push(it);
    }
    return out;
  }, [filtered]);

  const filterTabs = [
    { id: "all",    label: "All",    count: items.length },
    { id: "unread", label: "Unread", count: unreadCount },
  ];

  return (
    <div className="page" style={{ minHeight: "100vh", background: "#FDC831" }}>
      {/* Hero strip */}
      <div style={{
        background: "#F7F4EF",
        borderBottom: "1px solid #211E1E",
        padding: "20px 32px",
      }}>
        <div style={{ maxWidth: 1120, margin: "0 auto", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, flexWrap: "wrap" }}>
          <button onClick={onBack} className="kb-back-btn">
            <svg className="kb-back-arrow" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M19 12H5" /><path d="m11 18-6-6 6-6" /></svg>
            Back to IT Hub
          </button>
          <button
            type="button"
            onClick={markAllRead}
            disabled={unreadCount === 0}
            style={{
              padding: "8px 14px",
              background: unreadCount ? "#FFFFFF" : "#F7F4EF",
              border: "1px solid #211E1E", borderRadius: 999,
              boxShadow: unreadCount ? "1px 1px 0 #211E1E" : "none",
              fontFamily: "'Archivo', sans-serif",
              fontWeight: 700, fontSize: 12,
              letterSpacing: "0.04em", textTransform: "uppercase",
              color: "#211E1E",
              cursor: unreadCount === 0 ? "default" : "pointer",
              opacity: unreadCount === 0 ? 0.5 : 1,
            }}>
            {unreadCount > 0 ? `Mark ${unreadCount} read` : "All caught up"}
          </button>
        </div>
      </div>

      {/* Body */}
      <div style={{ maxWidth: 1120, boxSizing: "content-box", margin: "0 auto", padding: "32px 32px 80px" }}>
        {/* Page title */}
        <h1 style={{
          fontFamily: "'Archivo', sans-serif",
          fontSize: 40, fontWeight: 900, letterSpacing: "-0.025em", lineHeight: 1.02,
          margin: "0 0 22px", color: "#211E1E",
        }}>Notifications</h1>

        {/* Filter pill tabs */}
        <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginBottom: 24 }}>
          {filterTabs.map((tab) => {
            const on = filter === tab.id;
            return (
              <button key={tab.id}
                className={"kb-popular-chip" + (on ? " is-active" : "")}
                onClick={() => setFilter(tab.id)}>
                {tab.label}{tab.count != null ? ` · ${tab.count}` : ""}
              </button>
            );
          })}
        </div>

        {/* Grouped notification list */}
        {filtered.length === 0 ? (
          <div style={{
            padding: "48px 24px", textAlign: "center",
            background: "#FFFFFF", border: "1px dashed #211E1E", borderRadius: 14,
          }}>
            <div style={{ fontFamily: "'Archivo', sans-serif", fontSize: 18, fontWeight: 800, color: "#211E1E", marginBottom: 6 }}>You're all caught up</div>
            <div style={{ fontSize: 13.5, color: "#78684C" }}>No notifications match this filter right now.</div>
          </div>
        ) : (
          [...grouped.entries()].map(([group, list]) => (
            <div key={group} style={{ marginBottom: 28 }}>
              <div className="eyebrow" style={{
                fontSize: 11, fontWeight: 900, letterSpacing: "0.08em",
                textTransform: "uppercase", color: "#4A3F2E",
                marginBottom: 10,
              }}>{group}</div>
              <div style={{
                background: "#FFFFFF",
                border: "1px solid #211E1E", borderRadius: 14,
                boxShadow: "2px 2px 0 #211E1E",
                overflow: "hidden",
              }}>
                {list.map((it, i) => (
                  <div key={it.id}
                    onClick={() => markRead(it.id)}
                    className="notif-row"
                    style={{
                      display: "flex", alignItems: "flex-start", gap: 14,
                      padding: "16px 18px",
                      borderBottom: i === list.length - 1 ? "none" : "1.5px solid #E7E1D4",
                      cursor: "pointer",
                      background: it.unread ? "#FFFAE0" : "transparent",
                      position: "relative",
                    }}>
                    {it.unread && (
                      <span aria-hidden="true" style={{
                        position: "absolute", left: 6, top: "50%",
                        transform: "translateY(-50%)",
                        width: 7, height: 7, borderRadius: "50%",
                        background: "#E8534E",
                      }}/>
                    )}
                    {/* Type tile */}
                    <div className="notif-icon" style={{
                      width: 40, height: 40, flexShrink: 0,
                      background: KIND_META[it.kind]?.color || "#FDC831",
                      border: "1px solid #211E1E", borderRadius: 8,
                      display: "grid", placeItems: "center",
                      color: "#211E1E",
                    }}>
                      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
                        <path d="M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9"/>
                        <path d="M10.3 21a1.94 1.94 0 0 0 3.4 0"/>
                      </svg>
                    </div>
                    {/* Body */}
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", gap: 12, marginBottom: 3 }}>
                        <div style={{
                          fontFamily: "'Archivo', sans-serif",
                          fontSize: 14, fontWeight: 800, color: "#211E1E",
                          letterSpacing: "-0.005em",
                        }}>{it.title}</div>
                        <div style={{ fontSize: 11, color: "#8A7A4E", fontWeight: 600, fontFamily: "Archivo, sans-serif", flexShrink: 0 }}>{it.when}</div>
                      </div>
                      <div style={{ fontSize: 13, color: "#5A4B28", lineHeight: 1.5 }}>{it.body}</div>
                      <div style={{ marginTop: 8, display: "inline-flex", alignItems: "center", gap: 6 }}>
                        <span style={{
                          fontFamily: "'Archivo', sans-serif",
                          fontSize: 9.5, fontWeight: 800,
                          letterSpacing: "0.06em", textTransform: "uppercase",
                          color: "#4A3F2E",
                          padding: "2px 7px",
                          background: "#FFF9E6",
                          border: "1px solid #211E1E",
                          borderRadius: 3,
                        }}>{KIND_META[it.kind]?.label || it.kind}</span>
                      </div>
                    </div>
                    {/* Dismiss button */}
                    <button
                      type="button"
                      onClick={(e) => { e.stopPropagation(); dismiss(it.id); }}
                      aria-label="Dismiss notification"
                      style={{
                        flexShrink: 0,
                        width: 26, height: 26,
                        background: "transparent",
                        border: "1px solid transparent",
                        borderRadius: 999,
                        display: "grid", placeItems: "center",
                        cursor: "pointer", color: "#78684C",
                        fontFamily: "inherit",
                        transition: "background .12s ease, border-color .12s ease, color .12s ease",
                      }}
                      onMouseEnter={(e) => { e.currentTarget.style.background = "#FFFFFF"; e.currentTarget.style.borderColor = "#211E1E"; e.currentTarget.style.color = "#211E1E"; }}
                      onMouseLeave={(e) => { e.currentTarget.style.background = "transparent"; e.currentTarget.style.borderColor = "transparent"; e.currentTarget.style.color = "#78684C"; }}
                    >
                      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.8" strokeLinecap="round"><path d="M6 6l12 12M18 6l-12 12"/></svg>
                    </button>
                  </div>
                ))}
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

// ─── tweaks-panel (ecc64c82) ──────────────────────────────────

// tweaks-panel.jsx
// Reusable Tweaks shell + form-control helpers.
//
// Owns the host protocol (listens for __activate_edit_mode / __deactivate_edit_mode,
// posts __edit_mode_available / __edit_mode_set_keys / __edit_mode_dismissed) so
