function scoreMatch(item, q) {
  const hay = (item.title + " " + item.category + " " + item.keywords + " " + item.body).toLowerCase();
  if (!hay.includes(q)) return 0;
  let s = 0;
  if (item.title.toLowerCase().includes(q)) s += 10;
  if (item.category.toLowerCase().includes(q)) s += 4;
  if (item.keywords.toLowerCase().includes(q)) s += 3;
  if (item.body.toLowerCase().includes(q)) s += 1;
  return s;
}

function KnowledgePage({ onBack, onOpenGuide }) {
  const [query, setQuery] = React.useState("");
  const [activeCat, setActiveCat] = React.useState(null); // category id or null
  const [sort, setSort] = React.useState("relevance"); // 'relevance' | 'recent'
  const [suggestOpen, setSuggestOpen] = React.useState(false);
  const [suggestSent, setSuggestSent] = React.useState(false);
  const inputRef = React.useRef(null);
  const resultsRef = React.useRef(null);

  const [dbGuides, setDbGuides] = React.useState([]);
  React.useEffect(() => {
    fetch('/api/guides')
      .then((r) => r.ok ? r.json() : Promise.reject(new Error(`HTTP ${r.status}`)))
      .then(setDbGuides)
      .catch(() => setDbGuides([]));
  }, []);

  // Adapt DB rows to the shape the existing search/render code expects
  const liveIndex = React.useMemo(() => dbGuides.map((g) => ({
    id: g.id,
    title: g.title,
    category: (g.category || 'General').replace(/\b\w/g, (c) => c.toUpperCase()),
    keywords: ((g.tags || []).join(' ') + ' ' + (g.source_type || '')).trim(),
    body: '',
    updated: Math.max(0, Math.floor((Date.now() - new Date(g.updated_at).getTime()) / 86400000)),
    source_type: g.source_type,
    helpful_count: g.helpful_count ?? 0,
  })), [dbGuides]);

  const liveFeatured = React.useMemo(() => liveIndex.slice(0, 3), [liveIndex]);
  const livePopular  = React.useMemo(
    () => [...liveIndex].sort((a, b) => b.helpful_count - a.helpful_count).slice(0, 6),
    [liveIndex],
  );
  const liveRecent   = React.useMemo(
    () => [...liveIndex].sort((a, b) => a.updated - b.updated).slice(0, 6).map((g) => ({
      ...g,
      when: g.updated === 0 ? 'Today' : g.updated === 1 ? 'Yesterday'
        : g.updated < 7 ? `${g.updated}d ago`
        : g.updated < 30 ? `${Math.round(g.updated / 7)}w ago`
        : `${Math.round(g.updated / 30)}mo ago`,
    })),
    [liveIndex],
  );

  const liveCats = React.useMemo(() => {
    const seen = new Map();
    for (const g of liveIndex) {
      const cur = seen.get(g.category);
      if (cur) cur.count += 1;
      else seen.set(g.category, { id: g.category, label: g.category, count: 1 });
    }
    return [...seen.values()];
  }, [liveIndex]);

  const q = query.trim().toLowerCase();
  const searching = q.length > 0 || !!activeCat;

  const results = React.useMemo(() => {
    let list = liveIndex;
    // A search spans ALL guides — the category filter is only for browsing, so a
    // query ignores it. (Filtering by category first meant searching inside a
    // category found nothing.)
    if (q) {
      list = list
        .map((it) => ({ it, score: scoreMatch(it, q) }))
        .filter((r) => r.score > 0)
        .sort((a, b) => b.score - a.score)
        .map((r) => r.it);
    } else if (activeCat) {
      list = list.filter((it) => it.category === activeCat);
    }
    if (sort === "recent") list = [...list].sort((a, b) => a.updated - b.updated);
    return list;
  }, [liveIndex, q, activeCat, sort]);

  // Typing a search clears any active category, so we never leave a category
  // chip selected while showing global, cross-category results.
  React.useEffect(() => { if (q) setActiveCat(null); }, [q]);

  const activeCatLabel = activeCat ? (liveCats.find((c) => c.id === activeCat)?.label) : null;

  const handleOpen = (item) => {
    if (onOpenGuide) onOpenGuide({ id: item.id, ...item });
  };

  const clearAll = () => { setQuery(""); setActiveCat(null); inputRef.current?.focus(); };
  const onSubmit = (e) => { e.preventDefault(); resultsRef.current?.scrollIntoView({ behavior: "smooth", block: "start" }); };

  // Mini-search: collapses the hero search into a fixed pill below the nav once
  // the user scrolls past the hero. Same width as the big input (880) — same
  // pattern Landing uses, so the experience is consistent across the
  // self-service module. We listen on the actual scroll container (.page-scroll)
  // because html/body have overflow:hidden in this app.
  // rAF-throttled + hysteresis: prevents jitter at the boundary.
  const [collapsed, setCollapsed] = React.useState(false);
  React.useEffect(() => {
    const target = document.querySelector('.page-scroll') || window;
    let rafId = 0;
    let lastCollapsed = false;
    const tick = () => {
      rafId = 0;
      const top = target === window ? window.scrollY : target.scrollTop;
      const next = lastCollapsed ? top > 260 : top > 360;
      if (next !== lastCollapsed) {
        lastCollapsed = next;
        setCollapsed(next);
      }
    };
    const onScroll = () => {
      if (rafId) return;
      rafId = requestAnimationFrame(tick);
    };
    target.addEventListener('scroll', onScroll, { passive: true });
    return () => {
      target.removeEventListener('scroll', onScroll);
      if (rafId) cancelAnimationFrame(rafId);
    };
  }, []);

  return (
    <div className="page" data-hero-collapsed={collapsed ? "true" : "false"} style={{ background: "#FDC831" }}>

      {/* Mini search — portaled to body so position:fixed isn't trapped by an
          ancestor transform (animations on .page create one). */}
      {ReactDOM.createPortal(
        <div className="mini-search" data-show={collapsed ? "true" : "false"} aria-hidden={!collapsed}>
          <div className="mini-search-shell">
            <span className="mini-search-icon">
              <IconSearch size={15} stroke={2} />
            </span>
            <input
              type="text"
              placeholder='Search "VPN", "password", "laptop"…'
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); resultsRef.current?.scrollIntoView({ behavior: "smooth", block: "start" }); }
              }}
              tabIndex={collapsed ? 0 : -1} />
            <button
              className="mini-search-btn"
              onClick={() => resultsRef.current?.scrollIntoView({ behavior: "smooth", block: "start" })}
              tabIndex={collapsed ? 0 : -1}>
              Search
              <IconArrow size={13} stroke={2} />
            </button>
          </div>
        </div>,
        document.body
      )}

      {/* Hero */}
      <div style={{
        background: "#F7F4EF",
        borderBottom: "1px solid #211E1E",
        padding: "44px 32px 32px",
      }}>
        <div style={{ maxWidth: 1120, margin: "0 auto" }}>
          <button onClick={onBack} className="kb-back-btn" style={{ marginBottom: 22 }}>
            <svg className="kb-back-arrow" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M19 12H5" /><path d="m11 18-6-6 6-6" /></svg>Back
          </button>
          <h1 style={{
            fontFamily: "'Archivo', sans-serif",
            fontSize: 40, fontWeight: 900,
            margin: 0, letterSpacing: "-0.025em",
            color: "#211E1E", lineHeight: 1.02,
            maxWidth: 720,
            textTransform: "none",
          }}>
            Answers before you <span className="annotate-underline">file a ticket</span>.
          </h1>
          <div style={{ height: 22 }} />

          {/* Search bar */}
          <form onSubmit={onSubmit} className="kb-search-form" style={{
            background: "#FFFFFF",
            border: "1px solid #211E1E",
            borderRadius: 14,
            boxShadow: "3px 3px 0 #211E1E",
            padding: "8px 8px 8px 20px",
            display: "flex", alignItems: "center", gap: 14,
            maxWidth: 1120,
            transition: "transform .18s cubic-bezier(.2,.8,.2,1), box-shadow .18s cubic-bezier(.2,.8,.2,1)",
            transformOrigin: "left center",
            willChange: "transform",
          }}>
            <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#211E1E" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
              <circle cx="11" cy="11" r="8"/><path d="m21 21-4.3-4.3"/>
            </svg>
            <input ref={inputRef} value={query} onChange={(e) => setQuery(e.target.value)}
              placeholder='Search for "VPN", "password", "laptop"…'
              style={{
                flex: 1, border: "none", outline: "none",
                background: "transparent",
                fontFamily: "'Archivo', sans-serif",
                fontSize: 17, fontWeight: 500, color: "#211E1E",
                padding: "12px 0",
                letterSpacing: "-0.005em",
              }}/>
            {query && (
              <button type="button" onClick={() => setQuery("")} aria-label="Clear search" style={{
                width: 28, height: 28, padding: 0, cursor: "pointer",
                background: "#F7F4EF", border: "1px solid #211E1E", borderRadius: "50%",
                display: "grid", placeItems: "center", color: "#211E1E",
                marginRight: 4,
              }}>
                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.8" strokeLinecap="round"><path d="M6 6l12 12M18 6l-12 12"/></svg>
              </button>
            )}
            <button type="submit" className="btn btn-primary btn-go-search" style={{ padding: "12px 20px" }}>
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><circle cx="11" cy="11" r="7" /><path d="m20 20-3.5-3.5" /></svg>
              Search
            </button>
          </form>
          <style>{`
            .kb-search-form:hover {
              transform: translate(-2px, -2px);
              box-shadow: 4px 4px 0 #211E1E;
            }
            .kb-search-form:focus-within {
              transform: translate(-3px, -3px);
              box-shadow: 5px 5px 0 #211E1E;
              border-color: #211E1E;
            }
            .kb-search-form input::placeholder {
              transition: opacity .18s ease, transform .18s ease;
            }
            .kb-search-form:focus-within input::placeholder {
              opacity: 0.45;
            }
          `}</style>

          {/* Popular chips (now with active state) */}
          <div style={{ marginTop: 18, display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
            <span style={{ fontSize: 12, color: "#78684C", fontWeight: 600 }}>Popular:</span>
            {["password reset", "VPN", "new laptop", "Slack", "phishing"].map((p) => {
              const isActive = query === p;
              return (
                <button key={p}
                  className={"kb-popular-chip" + (isActive ? " is-active" : "")}
                  onClick={() => { setQuery(p); setActiveCat(null); }}>
                  {p}
                </button>
              );
            })}
          </div>
        </div>
      </div>

      {/* Body */}
      <div ref={resultsRef} style={{ maxWidth: 1120, boxSizing: "content-box", margin: "0 auto", padding: "44px 32px 120px" }}>
        {searching && (
          <SearchResults
            query={q}
            categoryLabel={activeCatLabel}
            categoryId={activeCat}
            onClearCategory={() => setActiveCat(null)}
            results={results}
            sort={sort}
            onChangeSort={setSort}
            onClear={clearAll}
            onOpenItem={handleOpen}
            onSuggest={() => setSuggestOpen(true)}
          />
        )}
        {!searching && (
        <React.Fragment>
        {/* Categories */}
        <SectionTitle kicker="Browse by topic" title="Pick a category" />
        <div style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))",
          gap: 14,
          marginBottom: 56,
        }}>
          {liveCats.map((c) => {
            return (
              <button key={c.id} className="kb-cat-card" onClick={() => { setActiveCat(c.id); setTimeout(() => resultsRef.current?.scrollIntoView({ behavior: "smooth", block: "start" }), 50); }}>
                <div className="kb-cat-card-inner">
                  <div className="kb-cat-icon">
                    {c.label.charAt(0)}
                  </div>
                  <div style={{ fontSize: 14.5, fontWeight: 800, marginBottom: 4, letterSpacing: "-0.005em" }}>
                    {c.label}
                  </div>
                  <div style={{ fontSize: 11.5, fontWeight: 600, opacity: 0.7 }}>{c.count} articles</div>
                </div>
              </button>
            );
          })}
        </div>

        {/* Featured */}
        <SectionTitle kicker="Editor's picks" title="Start here" />
        <div style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(260px, 1fr))",
          gap: 18,
          marginBottom: 56,
        }}>
          {liveFeatured.map((g) => (
            <FeaturedGuideCard key={g.id} guide={g} onClick={() => onOpenGuide && onOpenGuide({ id: g.id, ...g })} />
          ))}
        </div>

        {/* Two-col: Popular + Recent — unified row treatment */}
        <div style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(320px, 1fr))",
          gap: 28,
        }}>
          <div>
            <SectionTitle kicker="Most viewed" title="Popular articles" />
            <ArticleList items={livePopular.map(p => ({ ...p, meta: p.category }))} onOpen={handleOpen} markerTone="dot" />
          </div>

          <div>
            <SectionTitle kicker="Fresh off the press" title="Recently updated" />
            <ArticleList items={liveRecent.map(r => ({ ...r, meta: `${r.when} · ${r.category}` }))} onOpen={handleOpen} markerTone="dot" />

            {/* Suggest an article — lighter, cream-on-charcoal-outline, not full charcoal */}
            <div style={{
              marginTop: 18,
              background: "#FFF9E6", color: "#211E1E",
              border: "1px solid #211E1E", borderRadius: 10,
              boxShadow: "2px 2px 0 #211E1E",
              padding: "18px 20px",
            }}>
              <div style={{ fontFamily: "Archivo, sans-serif", fontSize: 10.5, fontWeight: 900, letterSpacing: "0.08em", textTransform: "uppercase", color: "#8A6A14", marginBottom: 8 }}>
                Nothing matches?
              </div>
              <div style={{ fontSize: 14, fontWeight: 600, lineHeight: 1.5, marginBottom: 12, color: "#211E1E" }}>
                Tell us what you searched for. If it's missing, we'll write it.
              </div>
              <button onClick={() => setSuggestOpen(true)} className="btn btn-primary" style={{ padding: "8px 14px" }}>Suggest an article →</button>
            </div>
          </div>
        </div>
        </React.Fragment>
        )}
      </div>

      {suggestOpen && <SuggestModal
        seedQuery={query}
        onClose={() => { setSuggestOpen(false); setSuggestSent(false); }}
        sent={suggestSent}
        onSubmit={() => setSuggestSent(true)}
      />}
    </div>
  );
}

function SearchResults({ query, categoryLabel, categoryId, onClearCategory, results, sort, onChangeSort, onClear, onOpenItem, onSuggest }) {
  const hasBoth = query && categoryLabel;
  return (
    <div>
      <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", marginBottom: 18, gap: 16, flexWrap: "wrap" }}>
        <div>
          <div style={{ fontFamily: "Archivo, sans-serif", fontWeight: 900, fontSize: 11, letterSpacing: "0.08em", textTransform: "uppercase", color: "#4A3F2E", marginBottom: 4 }}>
            {results.length} result{results.length === 1 ? "" : "s"}{hasBoth ? " · filtered" : ""}
          </div>
          <h2 style={{
            fontFamily: "'Archivo', sans-serif",
            fontSize: 26, fontWeight: 800, margin: 0,
            color: "#211E1E", letterSpacing: "-0.02em",
          }}>
            {query ? `“${query}”` : categoryLabel}
          </h2>
          {hasBoth && (
            <div style={{ marginTop: 8, display: "flex", alignItems: "center", gap: 8, fontSize: 12, color: "#4A3F2E" }}>
              in
              <span style={{
                display: "inline-flex", alignItems: "center", gap: 6,
                background: "#FDC831", border: "1px solid #211E1E", borderRadius: 999,
                padding: "3px 10px 3px 12px", fontWeight: 700, fontSize: 12,
                fontFamily: "Archivo, sans-serif",
              }}>
                {categoryLabel}
                <button onClick={onClearCategory} aria-label="Remove filter" style={{
                  width: 16, height: 16, padding: 0,
                  background: "#211E1E", color: "#FDC831",
                  border: "none", borderRadius: "50%",
                  display: "grid", placeItems: "center", cursor: "pointer",
                }}>
                  <svg width="8" height="8" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round"><path d="M6 6l12 12M18 6l-12 12"/></svg>
                </button>
              </span>
            </div>
          )}
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          {/* Sort */}
          <div style={{ display: "inline-flex", border: "1px solid #211E1E", borderRadius: 8, overflow: "hidden", background: "#FFFFFF" }}>
            {[
              { v: "relevance", label: "Best match" },
              { v: "recent", label: "Recently updated" },
            ].map((opt, i) => (
              <button key={opt.v} onClick={() => onChangeSort(opt.v)} style={{
                padding: "7px 12px",
                background: sort === opt.v ? "#211E1E" : "#FFFFFF",
                color: sort === opt.v ? "#FDC831" : "#211E1E",
                border: "none",
                borderLeft: i === 0 ? "none" : "1.5px solid #211E1E",
                fontFamily: "Archivo, sans-serif", fontSize: 11.5, fontWeight: 700,
                cursor: "pointer", letterSpacing: "0.01em",
              }}>{opt.label}</button>
            ))}
          </div>
          <button onClick={onClear} className="btn btn-outline" style={{ padding: "8px 14px" }}>Clear</button>
        </div>
      </div>

      {results.length === 0 ? (
        <div style={{
          background: "#FFFFFF", border: "1px dashed #211E1E", borderRadius: 14,
          padding: "44px 32px",
          textAlign: "center",
        }}>
          {/* Typographic mark instead of emoji */}
          <div style={{
            width: 64, height: 64, margin: "0 auto 14px",
            background: "#FDC831", border: "1px solid #211E1E", borderRadius: "50%",
            boxShadow: "2px 2px 0 #211E1E",
            display: "grid", placeItems: "center",
            fontFamily: "'Archivo', sans-serif", fontSize: 36, fontWeight: 900, color: "#211E1E",
            lineHeight: 1,
          }}>?</div>
          <div style={{ fontFamily: "'Archivo', sans-serif", fontSize: 20, fontWeight: 800, color: "#211E1E", marginBottom: 6 }}>
            Nothing matched{query ? ` “${query}”` : ""}.
          </div>
          <div style={{ fontSize: 14, color: "#4A3F2E", marginBottom: 18 }}>
            Try a broader term, or suggest we write a guide for this.
          </div>
          <button onClick={onSuggest} className="btn btn-primary" style={{ padding: "10px 18px" }}>Suggest an article →</button>
        </div>
      ) : (
        <div style={{
          background: "#FFFFFF",
          border: "1px solid #211E1E", borderRadius: 14,
          boxShadow: "2px 2px 0 #211E1E",
          overflow: "hidden",
        }}>
          {results.map((r, i) => (
            <div key={r.id} onClick={() => onOpenItem(r)} style={{
              display: "flex", alignItems: "center", gap: 16,
              padding: "18px 22px",
              borderBottom: i === results.length - 1 ? "none" : "1.5px solid #E7E1D4",
              cursor: "pointer",
              transition: "background .12s",
            }}
            onMouseEnter={(e) => { e.currentTarget.style.background = "#FFFDF5"; }}
            onMouseLeave={(e) => { e.currentTarget.style.background = "transparent"; }}>
              <CategoryDot category={r.category} />
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 15, fontWeight: 800, color: "#211E1E", marginBottom: 3, letterSpacing: "-0.005em" }}>
                  <HighlightMatch text={r.title} query={query} />
                </div>
                <div style={{ fontSize: 12.5, color: "#4A3F2E", marginBottom: 4, lineHeight: 1.4 }}>
                  <HighlightMatch text={r.body} query={query} />
                </div>
                <div style={{ fontSize: 10.5, color: "#78684C", fontWeight: 700, fontFamily: "Archivo, sans-serif", letterSpacing: "0.04em", textTransform: "uppercase" }}>
                  {r.category}
                </div>
              </div>
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#211E1E" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                <polyline points="9 18 15 12 9 6"/>
              </svg>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// Small icon-dot used as row marker — replaces numeric 1..6 ranks.
function CategoryDot({ category }) {
  const catId = CAT_LABEL_TO_ID[category];
  const catMeta = KB_CATEGORIES.find(c => c.id === catId);
  const Icon = catMeta ? window[catMeta.icon] : null;
  const initial = (category || '?').trim().charAt(0).toUpperCase();
  return (
    <div className="kb-row-icon">
      {Icon ? <Icon size={16} stroke={2.2} /> : <span style={{ fontFamily: "Archivo, sans-serif", fontSize: 15, fontWeight: 900 }}>{initial}</span>}
    </div>
  );
}

// Unified article list used by Popular + Recent
function ArticleList({ items, onOpen }) {
  return (
    <div style={{
      background: "#FFFFFF",
      border: "1px solid #211E1E", borderRadius: 14,
      boxShadow: "2px 2px 0 #211E1E",
      overflow: "hidden",
    }}>
      {items.map((p, i) => (
        <div key={p.id} className="kb-row" onClick={() => onOpen && onOpen(p)}
          style={{ borderBottom: i === items.length - 1 ? "none" : "1.5px solid #E7E1D4" }}>
          <CategoryDot category={p.category} />
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ fontSize: 14, fontWeight: 700, color: "#211E1E", marginBottom: 2, letterSpacing: "-0.005em" }}>
              {p.title}
            </div>
            <div style={{ fontSize: 11.5, color: "#78684C", fontWeight: 600 }}>
              {p.meta}
            </div>
          </div>
          <svg className="kb-row-caret" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#211E1E" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <polyline points="9 18 15 12 9 6"/>
          </svg>
        </div>
      ))}
    </div>
  );
}

function HighlightMatch({ text, query }) {
  if (!query) return text;
  const idx = text.toLowerCase().indexOf(query.toLowerCase());
  if (idx < 0) return text;
  return (
    <React.Fragment>
      {text.slice(0, idx)}
      <mark style={{
        background: "#FDC831", color: "#211E1E",
        padding: "0 3px", borderRadius: 2,
        border: "1px solid #211E1E",
        boxShadow: "1px 1px 0 #211E1E",
      }}>
        {text.slice(idx, idx + query.length)}
      </mark>
      {text.slice(idx + query.length)}
    </React.Fragment>
  );
}

function SectionTitle({ kicker, title, right }) {
  return (
    <div style={{ display: "flex", alignItems: "flex-end", justifyContent: "space-between", marginBottom: 18, gap: 16, flexWrap: "wrap" }}>
      <div>
        <div style={{ fontFamily: "Archivo, sans-serif", fontWeight: 900, fontSize: 11, letterSpacing: "0.08em", textTransform: "uppercase", color: "#4A3F2E", marginBottom: 4 }}>
          {kicker}
        </div>
        <h2 style={{
          fontFamily: "'Archivo', sans-serif",
          fontSize: 22, fontWeight: 800, margin: 0,
          color: "#211E1E", letterSpacing: "-0.015em",
          lineHeight: 1.15,
        }}>{title}</h2>
      </div>
      {right}
    </div>
  );
}

function FeaturedGuideCard({ guide, onClick }) {
  return (
    <div onClick={onClick} style={{
      background: "#FFFFFF",
      border: "1px solid #211E1E", borderRadius: 14,
      boxShadow: "2px 2px 0 #211E1E",
      padding: "22px 22px 20px",
      cursor: "pointer",
      transition: "transform .18s var(--ease), box-shadow .18s var(--ease)",
      display: "flex", flexDirection: "column", gap: 14,
      minHeight: 220,
    }}
    onMouseEnter={(e) => { e.currentTarget.style.transform = "translate(-3px,-3px)"; e.currentTarget.style.boxShadow = "4px 4px 0 #211E1E"; }}
    onMouseLeave={(e) => { e.currentTarget.style.transform = "none"; e.currentTarget.style.boxShadow = "2px 2px 0 #211E1E"; }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
        <span style={{
          fontFamily: "Archivo, sans-serif", fontSize: 10, fontWeight: 900,
          letterSpacing: "0.04em", textTransform: "uppercase",
          background: "#FDC831", color: "#211E1E",
          border: "1px solid #211E1E", borderRadius: 3,
          padding: "2px 8px",
        }}>{guide.category}</span>
      </div>
      <h3 style={{
        fontFamily: "'Archivo', sans-serif",
        fontSize: 18, fontWeight: 800,
        margin: 0, letterSpacing: "-0.015em",
        color: "#211E1E", lineHeight: 1.25,
      }}>{guide.title}</h3>
      <p style={{ fontSize: 13.5, color: "#4A3F2E", margin: 0, lineHeight: 1.5, flex: 1 }}>
        {guide.body}
      </p>
      <div style={{
        display: "flex", alignItems: "center", justifyContent: "flex-end",
        paddingTop: 12, borderTop: "1px solid #E7E1D4",
        fontSize: 12, fontWeight: 800, color: "#211E1E",
      }}>
        Read →
      </div>
    </div>
  );
}

// Suggest-an-article modal — portal-mounted like other confirmations
function SuggestModal({ seedQuery, onClose, sent, onSubmit }) {
  const [searched, setSearched] = React.useState(seedQuery || "");
  const [what, setWhat] = React.useState("");
  const valid = searched.trim() && what.trim();
  const submit = (e) => { e.preventDefault(); if (!valid) return; onSubmit(); };

  return ReactDOM.createPortal(
    <div className="overlay-in" onClick={onClose} style={{
      position: "fixed", inset: 0, zIndex: 2147483600,
      background: "rgba(33,30,30,0.55)",
      backdropFilter: "blur(4px)", WebkitBackdropFilter: "blur(4px)",
      display: "grid", placeItems: "center", padding: 24,
    }}>
      <div className="overlay-panel-in" onClick={(e) => e.stopPropagation()} style={{
        width: "min(540px, 100%)",
        background: "#F7F4EF",
        border: "1px solid #211E1E", borderRadius: 16,
        boxShadow: "5px 5px 0 #211E1E",
        padding: 28,
      }}>
        {!sent ? (
          <form onSubmit={submit}>
            <div style={{ fontFamily: "Archivo, sans-serif", fontWeight: 900, fontSize: 11, letterSpacing: "0.08em", textTransform: "uppercase", color: "#4A3F2E", marginBottom: 6 }}>
              Help us write the missing guide
            </div>
            <h2 style={{ fontFamily: "'Archivo', sans-serif", fontSize: 22, fontWeight: 800, margin: "0 0 18px", color: "#211E1E", letterSpacing: "-0.015em" }}>
              Suggest an article
            </h2>
            <label style={{ display: "block", fontSize: 12, fontWeight: 700, color: "#4A3F2E", marginBottom: 6, fontFamily: "Archivo, sans-serif", letterSpacing: "0.02em", textTransform: "uppercase" }}>What were you searching for?</label>
            <input value={searched} onChange={(e) => setSearched(e.target.value)} placeholder='e.g. "VPN on personal Mac"' style={inputStyle}/>
            <label style={{ display: "block", fontSize: 12, fontWeight: 700, color: "#4A3F2E", margin: "14px 0 6px", fontFamily: "Archivo, sans-serif", letterSpacing: "0.02em", textTransform: "uppercase" }}>What problem are you trying to solve?</label>
            <textarea value={what} onChange={(e) => setWhat(e.target.value)} rows={4} placeholder="Describe what you needed the article to cover…" style={{ ...inputStyle, resize: "vertical", minHeight: 88, fontFamily: "'Archivo', sans-serif" }}/>
            <div style={{ display: "flex", gap: 10, justifyContent: "flex-end", marginTop: 20 }}>
              <button type="button" onClick={onClose} className="btn btn-outline" style={{ padding: "10px 16px" }}>Cancel</button>
              <button type="submit" disabled={!valid} className="btn btn-primary" style={{ padding: "10px 18px", opacity: valid ? 1 : 0.5, cursor: valid ? "pointer" : "not-allowed" }}>Send to IT →</button>
            </div>
          </form>
        ) : (
          <div style={{ textAlign: "center", padding: "12px 8px" }}>
            <div style={{
              width: 72, height: 72, margin: "0 auto 16px",
              background: "#0A8A3E", border: "1px solid #211E1E", borderRadius: "50%",
              boxShadow: "2px 2px 0 #211E1E",
              display: "grid", placeItems: "center",
              color: "#FFFFFF", fontSize: 36, fontWeight: 900,
            }}>✓</div>
            <h2 style={{ fontFamily: "'Archivo', sans-serif", fontSize: 22, fontWeight: 800, margin: "0 0 8px", color: "#211E1E" }}>
              Thanks — we'll get on it.
            </h2>
            <p style={{ fontSize: 14, color: "#4A3F2E", margin: "0 0 22px" }}>
              You'll hear back when the guide is published (usually within a week).
            </p>
            <button onClick={onClose} className="btn btn-primary" style={{ padding: "10px 18px" }}>Close</button>
          </div>
        )}
      </div>
    </div>,
    document.body
  );
}

const inputStyle = {
  width: "100%", boxSizing: "border-box",
  padding: "10px 14px",
  fontFamily: "'Archivo', sans-serif", fontSize: 14, fontWeight: 500,
  color: "#211E1E",
  background: "#FFFFFF",
  border: "1px solid #211E1E", borderRadius: 8,
  outline: "none",
};

// ====================================================================
//  STATUS
// ====================================================================
//
// Backed by /api/status — the server monitors each service (polling a status
// API / RSS feed / probe / page, or receiving vendor webhooks) and exposes the
// current state per service. The page polls this endpoint every 30s so an open
// tab reflects state changes without a manual refresh.

// Map a service to its icon URL. Default to Google's S2 favicon service
// (no API key, broad coverage). Admin can override via icon_url.
function serviceIconUrl(s, size = 64) {
  if (s.icon_url) return s.icon_url;
  const domain = s.domain || `${(s.name || "").toLowerCase().replace(/\s+/g, "")}.com`;
  return `https://www.google.com/s2/favicons?domain=${encodeURIComponent(domain)}&sz=${size}`;
}

const SOURCE_LABELS = {
  manual:     { label: "Manual",        tone: "#4A3F2E", bg: "#F7F4EF" },
  probe:      { label: "Health probe",  tone: "#0A8A3E", bg: "#E8F5EC" },
  statuspage: { label: "Vendor status", tone: "#1E5FB2", bg: "#E5EFFA" },
  rss:        { label: "Incident feed", tone: "#8A5A14", bg: "#FBF1DD" },
  page:       { label: "Page scan",     tone: "#4A3F2E", bg: "#F7F4EF" },
  webhook:    { label: "Live webhook",  tone: "#6D3FB0", bg: "#F0E8FA" },
};

// Icon (emoji) per reference-link kind, shown on the link chips.
const LINK_KIND_ICON = { status: "🟢", rss: "📡", help: "❓", docs: "📄", twitter: "𝕏", other: "🔗" };

// Severity / state palettes for incident pills.
const SEVERITY_TONE = {
  minor:    { bg: "#FFE8A3", ink: "#8A6A14", label: "Minor" },
  major:    { bg: "#FFD4D0", ink: "#8A1E17", label: "Major" },
  critical: { bg: "#FFD4D0", ink: "#8A1E17", label: "Critical" },
};
const INCIDENT_STATE_TONE = {
  investigating: { bg: "#FFE8A3", ink: "#8A6A14", label: "Investigating" },
  identified:    { bg: "#FFD4D0", ink: "#8A1E17", label: "Identified" },
  monitoring:    { bg: "#FFE8A3", ink: "#8A6A14", label: "Monitoring" },
  resolved:      { bg: "#D4F4D4", ink: "#0A8A3E", label: "Resolved" },
};
const UPDATE_LABEL_TONE = {
  identified: "#DA3327",
  monitoring: "#8A6A14",
  fixed:      "#0A8A3E",
  resolved:   "#0A8A3E",
  update:     "#211E1E",
};

function relativeTime(input) {
  if (!input) return "—";
  const d = input instanceof Date ? input : new Date(input);
  if (Number.isNaN(d.getTime())) return "—";
  const sec = Math.max(0, Math.round((Date.now() - d.getTime()) / 1000));
  if (sec < 5) return "just now";
  if (sec < 60) return `${sec}s ago`;
  const min = Math.floor(sec / 60);
  if (min < 60) return `${min}m ago`;
  const hr = Math.floor(min / 60);
  if (hr < 24) return `${hr}h ago`;
  const day = Math.floor(hr / 24);
  if (day < 7) return `${day}d ago`;
  return d.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
}

function clockHM(input) {
  if (!input) return "";
  const d = input instanceof Date ? input : new Date(input);
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit', hour12: false });
}

function StatusPage({ onBack }) {
  // Live data from /api/status. Initial render shows a skeleton; we re-fetch
  // every 30s so the page reflects poller updates without a manual refresh.
  const [payload, setPayload] = React.useState(null);
  const [lastCheck, setLastCheck] = React.useState(null);
  const [loadError, setLoadError] = React.useState(null);

  React.useEffect(() => {
    let cancelled = false;
    const load = async () => {
      try {
        const r = await fetch('/api/status', { credentials: 'include', cache: 'no-store' });
        if (!r.ok) throw new Error(`HTTP ${r.status}`);
        const j = await r.json();
        if (cancelled) return;
        setPayload(j);
        setLastCheck(new Date());
        setLoadError(null);
      } catch (e) {
        if (!cancelled) setLoadError(e.message);
      }
    };
    load();
    const t = setInterval(load, 30000);
    return () => { cancelled = true; clearInterval(t); };
  }, []);

  // Force a re-render every second so the "last checked" label ticks.
  const [, setNow] = React.useState(0);
  React.useEffect(() => {
    const t = setInterval(() => setNow((n) => n + 1), 1000);
    return () => clearInterval(t);
  }, []);

  const groups = payload?.groups || [];
  const allServices = React.useMemo(() => groups.flatMap((g) => g.services || []), [groups]);
  const incidents = payload?.incidents || [];
  const openIncidentList = incidents.filter((i) => i.state !== 'resolved');
  // Keep a resolved incident visible as "recently resolved" for one hour after
  // it's fixed, then it drops off the public page. The 1s clock tick below
  // re-renders, so it disappears on its own ~1h later with no refetch. The timer
  // starts at resolution — an incident that's still open never auto-hides.
  const RESOLVED_GRACE_MS = 60 * 60 * 1000;
  const recentlyResolved = incidents.filter(
    (i) => i.state === 'resolved' && i.resolved_at && (Date.now() - new Date(i.resolved_at).getTime()) <= RESOLVED_GRACE_MS,
  );

  const operationalCount = allServices.filter((s) => s.state === 'operational').length;
  const degraded = allServices.filter((s) => s.state === 'degraded');
  const down = allServices.filter((s) => s.state === 'down');
  const overallTone = down.length ? 'red' : degraded.length ? 'amber' : 'green';
  const toneAccent = overallTone === 'green' ? '#0A8A3E' : overallTone === 'amber' ? '#B8860B' : '#DA3327';

  const [expandedSvc, setExpandedSvc] = React.useState(null);
  const [filter, setFilter] = React.useState('all'); // all | issues | operational
  const [query, setQuery] = React.useState('');

  // Total services — drives the "All" filter-chip count.
  const totalServices = allServices.length;

  const agoSec = lastCheck ? Math.max(0, Math.round((Date.now() - lastCheck.getTime()) / 1000)) : null;
  const agoLabel = agoSec == null ? 'syncing…'
    : agoSec < 5 ? 'just now'
    : agoSec < 60 ? `${agoSec}s ago`
    : `${Math.floor(agoSec / 60)}m ago`;

  // Filter + search applied to grouped layout. Hide services that don't match
  // and drop any group that ends up empty so the table doesn't show stale headers.
  const q = query.trim().toLowerCase();
  const matches = (s) => {
    if (filter === 'issues' && s.state === 'operational') return false;
    if (filter === 'operational' && s.state !== 'operational') return false;
    if (!q) return true;
    return (
      (s.name || '').toLowerCase().includes(q) ||
      (s.vendor || '').toLowerCase().includes(q) ||
      (s.domain || '').toLowerCase().includes(q)
    );
  };
  const filteredGroups = groups
    .map((g) => ({ ...g, services: (g.services || []).filter(matches) }))
    .filter((g) => g.services.length > 0);
  const noMatches = filteredGroups.length === 0 && payload != null;

  return (
    <div className="page" style={{
      background: "#FDC831",
      display: "flex", flexDirection: "column",
    }}>
      {/* Overall banner — cream bg always; tone expressed through icon + accent only */}
      <div style={{
        background: "#F7F4EF",
        borderBottom: "1px solid #211E1E",
        padding: "44px 32px 44px",
      }}>
        <div style={{ maxWidth: 1120, margin: "0 auto" }}>
          <button onClick={onBack} className="kb-back-btn" style={{ marginBottom: 22 }}>
            <svg className="kb-back-arrow" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M19 12H5" /><path d="m11 18-6-6 6-6" /></svg>Back
          </button>
          <div style={{ display: "grid", gridTemplateColumns: "auto 1fr", gap: 24, alignItems: "center" }}>
          <div style={{
            width: 88, height: 88,
            background: toneAccent,
            border: "1px solid #211E1E", borderRadius: 18,
            boxShadow: "2px 2px 0 #211E1E",
            display: "grid", placeItems: "center",
            color: "#FFFFFF",
            fontFamily: "Archivo, sans-serif", fontWeight: 900,
            fontSize: 38, lineHeight: 1,
            flexShrink: 0,
          }}>
            {overallTone === "green" ? "✓" : overallTone === "amber" ? "!" : "×"}
          </div>
          <div style={{ minWidth: 0 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}>
              <span style={{
                display: "inline-flex", alignItems: "center", gap: 6,
                fontFamily: "Archivo, sans-serif", fontWeight: 900, fontSize: 10, letterSpacing: "0.12em", textTransform: "uppercase", color: "#211E1E",
              }}>
                <span style={{ width: 8, height: 8, borderRadius: "50%", background: toneAccent, animation: "livePulse 1.8s ease-in-out infinite" }}/>
                Live
              </span>
            </div>
            <h1 style={{
              fontFamily: "'Archivo', sans-serif",
              fontSize: 44, fontWeight: 900,
              margin: 0, letterSpacing: "-0.03em",
              color: "#211E1E", lineHeight: 1,
              textTransform: "none",
            }}>
              {overallTone === "green" && "What's up?"}
              {overallTone === "amber" && `${degraded.length} thing${degraded.length > 1 ? "s" : ""} acting up.`}
              {overallTone === "red" && `${down.length} thing${down.length > 1 ? "s" : ""} down.`}
            </h1>
            <div style={{ fontSize: 14, color: "#4A3F2E", marginTop: 10, fontWeight: 600, display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap" }}>
              <span>Last checked <b style={{ color: "#211E1E" }}>{agoLabel}</b></span>
              <span style={{ opacity: 0.5 }}>·</span>
              <span>Auto-refreshes every 30 seconds</span>
              {loadError && (
                <>
                  <span style={{ opacity: 0.5 }}>·</span>
                  <span style={{ color: "#DA3327" }}>Sync error: {loadError}</span>
                </>
              )}
            </div>
          </div>
          </div>
        </div>
      </div>

      {/* Body */}
      <div style={{
        maxWidth: 1120, boxSizing: "content-box", margin: "0 auto", padding: "48px 32px 64px",
        width: "100%",
        flex: "1 0 auto", display: "flex", flexDirection: "column",
      }}>
        {/* Active incidents */}
        {openIncidentList.length > 0 && (
          <React.Fragment>
            <SectionTitle kicker="Active right now" title="Open incidents" />
            <div style={{ display: "flex", flexDirection: "column", gap: 14, marginBottom: 48 }}>
              {openIncidentList.map((inc) => (
                <IncidentCard key={inc.id} incident={inc} open />
              ))}
            </div>
          </React.Fragment>
        )}

        {/* Recently resolved — shown for one hour after the fix, then auto-hidden */}
        {recentlyResolved.length > 0 && (
          <React.Fragment>
            <SectionTitle kicker="Just fixed" title="Recently resolved" />
            <div style={{ display: "flex", flexDirection: "column", gap: 14, marginBottom: 48 }}>
              {recentlyResolved.map((inc) => (
                <IncidentCard key={inc.id} incident={inc} />
              ))}
            </div>
          </React.Fragment>
        )}

        {/* Services — top-level axis, grouped tables */}
        <SectionTitle
          kicker="All services"
          title="Service status"
          right={<StatusLegend />}
        />

        {/* Search + filter bar */}
        <div style={{
          display: "flex", flexWrap: "wrap", gap: 10, alignItems: "center",
          marginBottom: 14,
        }}>
          <div style={{
            position: "relative",
            flex: "1 1 280px", minWidth: 220,
          }}>
            <span style={{
              position: "absolute", left: 14, top: "50%", transform: "translateY(-50%)",
              color: "#78684C", display: "inline-flex",
            }}>
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg>
            </span>
            <input
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search services, vendors, domains…"
              style={{
                width: "100%", boxSizing: "border-box",
                padding: "11px 14px 11px 38px",
                fontFamily: "'Archivo', sans-serif", fontSize: 13.5, fontWeight: 600,
                color: "#211E1E", background: "#FFFFFF",
                border: "1px solid #211E1E", borderRadius: 10,
                boxShadow: "1px 1px 0 #211E1E", outline: "none",
              }}
            />
          </div>
          <FilterChip active={filter === "all"} onClick={() => setFilter("all")}>
            All <span style={pillCountStyle(filter === "all")}>{totalServices}</span>
          </FilterChip>
          <FilterChip active={filter === "issues"} onClick={() => setFilter("issues")}>
            Issues <span style={pillCountStyle(filter === "issues")}>{degraded.length + down.length}</span>
          </FilterChip>
          <FilterChip active={filter === "operational"} onClick={() => setFilter("operational")}>
            Operational <span style={pillCountStyle(filter === "operational")}>{operationalCount}</span>
          </FilterChip>
        </div>

        {/* Service list */}
        <div style={{
          background: "#FFFFFF",
          border: "1px solid #211E1E", borderRadius: 14,
          boxShadow: "2px 2px 0 #211E1E",
          overflow: "hidden",
          marginBottom: 48,
        }}>
          {/* Column header */}
          <div style={{
            display: "grid",
            gridTemplateColumns: "44px 1.4fr 1fr 40px",
            gap: 16,
            padding: "12px 22px",
            background: "#F7F4EF", borderBottom: "1px solid #211E1E",
            fontFamily: "Archivo, sans-serif", fontSize: 10.5, fontWeight: 900,
            letterSpacing: "0.08em", textTransform: "uppercase", color: "#4A3F2E",
          }}>
            <div/>
            <div>Service</div>
            <div>Status</div>
            <div/>
          </div>

          {!payload ? (
            <div style={{
              padding: "32px 22px",
              textAlign: "center",
              color: "#4A3F2E", fontSize: 13.5, fontWeight: 600,
            }}>Syncing services from the platform…</div>
          ) : noMatches ? (
            <div style={{
              padding: "32px 22px",
              textAlign: "center",
              color: "#4A3F2E", fontSize: 14, fontWeight: 600,
            }}>
              <div style={{ fontFamily: "Archivo, sans-serif", fontSize: 16, fontWeight: 900, color: "#211E1E", marginBottom: 6 }}>
                Nothing matches that.
              </div>
              <div>Try a different search or clear the filter.</div>
              <button
                onClick={() => { setQuery(""); setFilter("all"); }}
                className="btn btn-outline"
                style={{ marginTop: 14, padding: "8px 16px" }}
              >Clear filters</button>
            </div>
          ) : filteredGroups.flatMap((g) => g.services).map((s, i, arr) => (
            <ServiceRow
              key={s.id}
              service={s}
              isLast={i === arr.length - 1}
              expanded={expandedSvc === s.id}
              onToggle={() => setExpandedSvc(expandedSvc === s.id ? null : s.id)}
            />
          ))}
        </div>

      </div>

      <style>{`
        @keyframes livePulse {
          0%, 100% { transform: scale(1); opacity: 1; }
          50% { transform: scale(1.6); opacity: 0.3; }
        }
      `}</style>
    </div>
  );
}

function FilterChip({ active, onClick, children }) {
  return (
    <button
      onClick={onClick}
      style={{
        padding: "9px 14px",
        background: active ? "#211E1E" : "#FFFFFF",
        color: active ? "#FDC831" : "#211E1E",
        border: "1px solid #211E1E", borderRadius: 999,
        boxShadow: active ? "none" : "1px 1px 0 #211E1E",
        fontFamily: "'Archivo', sans-serif", fontSize: 12.5, fontWeight: 800,
        letterSpacing: "0.02em",
        cursor: "pointer",
        transition: "transform .12s var(--ease), box-shadow .12s var(--ease), background .12s, color .12s",
        display: "inline-flex", alignItems: "center", gap: 8,
      }}
      onMouseEnter={(e) => {
        if (active) return;
        e.currentTarget.style.transform = "translate(-1px,-1px)";
        e.currentTarget.style.boxShadow = "2px 2px 0 #211E1E";
      }}
      onMouseLeave={(e) => {
        if (active) return;
        e.currentTarget.style.transform = "none";
        e.currentTarget.style.boxShadow = "1px 1px 0 #211E1E";
      }}
    >{children}</button>
  );
}

function pillCountStyle(active) {
  return {
    fontSize: 11, fontWeight: 900,
    padding: "1px 7px", borderRadius: 999,
    background: active ? "#FDC831" : "#F7F4EF",
    color: active ? "#211E1E" : "#4A3F2E",
    border: "1px solid currentColor",
    letterSpacing: "0",
  };
}

function StatusLegend() {
  const items = [
    { color: "#0A8A3E", label: "Up" },
    { color: "#FDC831", label: "Degraded" },
    { color: "#DA3327", label: "Down" },
  ];
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 14, fontSize: 11.5, color: "#4A3F2E", fontWeight: 600 }}>
      {items.map(it => (
        <span key={it.label} style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>
          <span style={{ width: 10, height: 10, background: it.color, border: "1px solid #211E1E", borderRadius: 2 }}/>
          {it.label}
        </span>
      ))}
    </div>
  );
}

function ServiceRow({ service, isLast, expanded, onToggle }) {
  const [iconBroken, setIconBroken] = React.useState(false);
  const stateTone = service.state === "operational" ? { bg: "#D4F4D4", ink: "#0A8A3E", label: "Operational" }
    : service.state === "degraded" ? { bg: "#FFE8A3", ink: "#8A6A14", label: "Degraded" }
    : { bg: "#FFD4D0", ink: "#8A1E17", label: "Down" };

  const responseMs = service.response_ms;

  const initials = (service.name || "?")
    .split(/\s+/).filter(Boolean).slice(0, 2)
    .map((w) => w[0]).join("").toUpperCase();
  const sourceMeta = SOURCE_LABELS[service.source] || SOURCE_LABELS.manual;

  return (
    <React.Fragment>
      <div
        onMouseEnter={(e) => { e.currentTarget.style.background = "#FFFDF5"; }}
        onMouseLeave={(e) => { e.currentTarget.style.background = "transparent"; }}
        style={{
          display: "grid",
          gridTemplateColumns: "44px 1.4fr 1fr 40px",
          gap: 16, alignItems: "center",
          padding: "18px 22px",
          borderBottom: isLast && !expanded ? "none" : "1.5px solid #E7E1D4",
          transition: "background .12s",
          cursor: "pointer",
        }}
        onClick={onToggle}
      >
        {/* App icon */}
        <div style={{
          width: 36, height: 36,
          border: "1px solid #211E1E", borderRadius: 8,
          background: "#FFFFFF",
          display: "grid", placeItems: "center",
          overflow: "hidden",
          boxShadow: "1.5px 1.5px 0 #211E1E",
          flexShrink: 0,
        }}>
          {iconBroken ? (
            <span style={{
              fontFamily: "Archivo, sans-serif", fontSize: 11, fontWeight: 900,
              letterSpacing: "-0.01em", color: "#211E1E",
            }}>{initials}</span>
          ) : (
            <img
              src={serviceIconUrl(service)}
              alt=""
              width="22" height="22"
              loading="lazy"
              onError={() => setIconBroken(true)}
              style={{ display: "block", width: 22, height: 22, objectFit: "contain" }}
            />
          )}
        </div>
        <div style={{ minWidth: 0 }}>
          <div style={{ fontSize: 15, fontWeight: 700, color: "#211E1E", letterSpacing: "-0.005em" }}>{service.name}</div>
        </div>
        <div>
          <span style={{
            display: "inline-flex", alignItems: "center", gap: 6,
            padding: "4px 10px",
            background: stateTone.bg, color: stateTone.ink,
            border: `1.5px solid ${stateTone.ink}`,
            borderRadius: 3,
            fontFamily: "Archivo, sans-serif",
            fontSize: 10.5, fontWeight: 800,
            letterSpacing: "0.04em", textTransform: "uppercase",
          }}>
            <span style={{ width: 6, height: 6, borderRadius: "50%", background: stateTone.ink }}/>
            {stateTone.label}
          </span>
          <div style={{ fontSize: 11, color: "#78684C", marginTop: 4, fontWeight: 600 }}>
            Response: <b style={{ color: "#211E1E" }}>{responseMs != null ? `${responseMs}ms` : "—"}</b>
          </div>
          {service.state_note && service.state !== 'operational' && (
            <div style={{ fontSize: 11, color: "#8A1E17", marginTop: 4, fontWeight: 600, lineHeight: 1.4 }}>
              {service.state_note}
            </div>
          )}
        </div>
        <div style={{
          width: 28, height: 28,
          background: "#FDC831", border: "1px solid #211E1E", borderRadius: 4,
          display: "grid", placeItems: "center",
          transform: expanded ? "rotate(180deg)" : "none",
          transition: "transform .2s var(--ease)",
          justifySelf: "end",
        }}>
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#211E1E" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <polyline points="6 9 12 15 18 9"/>
          </svg>
        </div>
      </div>
      {expanded && (
        <div style={{
          padding: "18px 22px 20px",
          background: "#FFFDF5",
          borderBottom: isLast ? "none" : "1.5px solid #E7E1D4",
        }}>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(160px, 1fr))", gap: 14, marginBottom: 12 }}>
            <MiniStat label="Last response" value={responseMs != null ? `${responseMs}ms` : "—"} />
            <MiniStat label="Last checked"
              value={service.last_checked_at ? relativeTime(service.last_checked_at) : "—"} />
            <MiniStat label="Source" value={sourceMeta.label} />
          </div>
          {Array.isArray(service.links) && service.links.length > 0 && (
            <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginBottom: 12 }}>
              {service.links.map((l, i) => (
                <a key={i} href={l.url} target="_blank" rel="noreferrer noopener"
                  onClick={(e) => e.stopPropagation()}
                  style={{
                    display: "inline-flex", alignItems: "center", gap: 6,
                    padding: "5px 11px",
                    background: "#FFFFFF", border: "1px solid #211E1E", borderRadius: 999,
                    boxShadow: "1px 1px 0 #211E1E",
                    fontSize: 12, fontWeight: 700, color: "#211E1E", textDecoration: "none",
                  }}
                  onMouseEnter={(e) => { e.currentTarget.style.transform = "translate(-1px,-1px)"; e.currentTarget.style.boxShadow = "2px 2px 0 #211E1E"; }}
                  onMouseLeave={(e) => { e.currentTarget.style.transform = "none"; e.currentTarget.style.boxShadow = "1px 1px 0 #211E1E"; }}
                >
                  <span>{LINK_KIND_ICON[l.kind] || "🔗"}</span>
                  {l.label || l.url}
                  <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" style={{ opacity: 0.55 }}><path d="M7 17 17 7M9 7h8v8"/></svg>
                </a>
              ))}
            </div>
          )}
          <div style={{ fontSize: 12.5, color: "#4A3F2E", lineHeight: 1.5 }}>
            {(() => {
              const b = <b style={{ color: "#211E1E" }}>{service.name}</b>;
              if (service.source === 'manual')     return <>{b} is set manually by the IT Team. Status changes when an admin updates it.</>;
              if (service.source === 'webhook')    return <>{b} updates in real time — the vendor's status page pushes incident and component changes straight to us via webhook, so this reflects their status the moment it changes.</>;
              if (service.source === 'statuspage') return <>{b} is polled every 60 seconds from the vendor's public status API. We mark it <b>degraded</b> on a minor incident, and <b>down</b> for major or critical incidents.</>;
              if (service.source === 'rss')        return <>{b} is tracked from the vendor's incident feed (RSS/Atom), checked every 60 seconds — the newest entry's latest update drives the state.</>;
              if (service.source === 'page')       return <>{b}'s status page is scanned every 60 seconds for outage wording. A best-effort signal — check the vendor's page for detail.</>;
              return <>{b} is health-probed every 60 seconds. We mark it <b>degraded</b> when responses exceed 2500ms or return 4xx, and <b>down</b> on 5xx or connection failure.</>;
            })()}
            {service.last_error && (
              <div style={{ marginTop: 8, padding: "8px 10px", background: "#FFE8E5", border: "1px solid #DA3327", borderRadius: 6, color: "#7A1A14", fontFamily: "ui-monospace, Menlo, monospace", fontSize: 11.5 }}>
                Last error: {service.last_error}
              </div>
            )}
          </div>
        </div>
      )}
    </React.Fragment>
  );
}

function MiniStat({ label, value }) {
  return (
    <div style={{
      background: "#FFFFFF", border: "1px solid #211E1E", borderRadius: 8,
      padding: "10px 12px",
    }}>
      <div style={{ fontFamily: "Archivo, sans-serif", fontSize: 10, fontWeight: 900, letterSpacing: "0.06em", textTransform: "uppercase", color: "#78684C", marginBottom: 4 }}>{label}</div>
      <div style={{ fontFamily: "Archivo, sans-serif", fontSize: 18, fontWeight: 900, color: "#211E1E", lineHeight: 1 }}>{value}</div>
    </div>
  );
}

function IncidentCard({ incident, open }) {
  const [expanded, setExpanded] = React.useState(!!open);
  const sevTone = SEVERITY_TONE[incident.severity] || SEVERITY_TONE.minor;
  const stateTone = INCIDENT_STATE_TONE[incident.state] || INCIDENT_STATE_TONE.investigating;
  const idLabel = `INC-${String(incident.id).padStart(4, '0')}`;
  const startedRel = relativeTime(incident.started_at);
  // Compute "Resolved in Xm" from started_at → resolved_at when present.
  const resolvedDuration = (() => {
    if (!incident.resolved_at || !incident.started_at) return null;
    const ms = new Date(incident.resolved_at).getTime() - new Date(incident.started_at).getTime();
    if (!Number.isFinite(ms) || ms <= 0) return null;
    const min = Math.round(ms / 60000);
    if (min < 60) return `Resolved in ${min} min`;
    const hr = Math.round(min / 60);
    return `Resolved in ${hr}h`;
  })();

  return (
    <div style={{
      background: "#FFFFFF",
      border: "1px solid #211E1E", borderRadius: 12,
      boxShadow: "2px 2px 0 #211E1E",
      overflow: "hidden",
      transition: "transform .15s var(--ease), box-shadow .15s var(--ease)",
    }}
    onMouseEnter={(e) => { e.currentTarget.style.transform = "translate(-2px,-2px)"; e.currentTarget.style.boxShadow = "3px 3px 0 #FDC831, 5px 5px 0 0 #211E1E"; }}
    onMouseLeave={(e) => { e.currentTarget.style.transform = "none"; e.currentTarget.style.boxShadow = "2px 2px 0 #211E1E"; }}
    >
      <div onClick={() => setExpanded(!expanded)} style={{
        padding: "18px 22px",
        display: "flex", alignItems: "center", justifyContent: "space-between", gap: 14,
        cursor: "pointer",
      }}>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8, flexWrap: "wrap" }}>
            <span style={{
              fontFamily: "ui-monospace, Menlo, monospace",
              fontSize: 11, fontWeight: 700,
              background: "#F7F4EF", border: "1px solid #211E1E",
              borderRadius: 3, padding: "2px 7px", color: "#211E1E",
            }}>{idLabel}</span>
            <span style={{
              background: sevTone.bg, color: sevTone.ink,
              border: `1.5px solid ${sevTone.ink}`, borderRadius: 3,
              fontFamily: "Archivo, sans-serif", fontSize: 10, fontWeight: 800,
              padding: "2px 7px", letterSpacing: "0.04em", textTransform: "uppercase",
            }}>{sevTone.label}</span>
            <span style={{
              background: stateTone.bg, color: stateTone.ink,
              border: `1.5px solid ${stateTone.ink}`, borderRadius: 3,
              fontFamily: "Archivo, sans-serif", fontSize: 10, fontWeight: 800,
              padding: "2px 7px", letterSpacing: "0.04em", textTransform: "uppercase",
            }}>{stateTone.label}</span>
            {incident.auto_created && (
              <span title="Opened automatically by monitoring" style={{
                display: "inline-flex", alignItems: "center", gap: 4,
                background: "#211E1E", color: "#FDC831",
                borderRadius: 3, padding: "2px 7px",
                fontFamily: "Archivo, sans-serif", fontSize: 10, fontWeight: 800,
                letterSpacing: "0.04em", textTransform: "uppercase",
              }}>
                <svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M13 2 3 14h7l-1 8 10-12h-7z"/></svg>
                Auto
              </span>
            )}
            <span style={{ fontSize: 11, color: "#78684C", fontWeight: 600 }}>· Started {startedRel}</span>
          </div>
          <div style={{ fontSize: 15, fontWeight: 700, color: "#211E1E", letterSpacing: "-0.005em" }}>
            {incident.service_name ? `${incident.service_name} — ${incident.title}` : incident.title}
          </div>
          {resolvedDuration && (
            <div style={{ fontSize: 11.5, color: "#0A8A3E", fontWeight: 700, marginTop: 4 }}>
              ✓ {resolvedDuration}
            </div>
          )}
        </div>
        <div style={{
          width: 30, height: 30,
          background: "#FDC831", border: "1px solid #211E1E", borderRadius: 4,
          display: "grid", placeItems: "center",
          transform: expanded ? "rotate(180deg)" : "none",
          transition: "transform .2s var(--ease)",
          flexShrink: 0,
        }}>
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#211E1E" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <polyline points="6 9 12 15 18 9"/>
          </svg>
        </div>
      </div>

      {expanded && (
        <div style={{ padding: "0 22px 22px", borderTop: "1px solid #E7E1D4", marginTop: 4, paddingTop: 18 }}>
          <div style={{ fontFamily: "Archivo, sans-serif", fontSize: 10.5, fontWeight: 900, letterSpacing: "0.08em", textTransform: "uppercase", color: "#4A3F2E", marginBottom: 12 }}>
            Timeline
          </div>
          {(!incident.updates || incident.updates.length === 0) ? (
            <div style={{ fontSize: 13, color: "#78684C", fontStyle: "italic" }}>
              No updates yet — the IT Team will post one as soon as they have more info.
            </div>
          ) : (
            <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
              {incident.updates.map((u) => {
                const tone = UPDATE_LABEL_TONE[(u.label || '').toLowerCase()] || UPDATE_LABEL_TONE.update;
                return (
                  <div key={u.id} style={{ display: "flex", gap: 14, alignItems: "flex-start" }}>
                    <div style={{
                      width: 56,
                      fontFamily: "ui-monospace, Menlo, monospace",
                      fontSize: 12, fontWeight: 700, color: "#211E1E",
                      flexShrink: 0, paddingTop: 2,
                    }}>{clockHM(u.created_at)}</div>
                    <div style={{ flex: 1 }}>
                      <div style={{
                        fontFamily: "Archivo, sans-serif", fontSize: 10, fontWeight: 800,
                        letterSpacing: "0.04em", textTransform: "uppercase",
                        color: tone, marginBottom: 3,
                      }}>{u.label}</div>
                      <div style={{ fontSize: 13.5, color: "#211E1E", lineHeight: 1.5 }}>{u.body}</div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// Expose to window for app.jsx
Object.assign(window, { KnowledgePage, StatusPage });

// ─── misc (dd0d1053) ──────────────────────────────────
// ============================================================================
// ONBOARDING QUEUE
// ----------------------------------------------------------------------------
// Two clearly-separated sections:
//
//   1. AWAITING APPROVAL — manager hasn't responded (or has returned). These
//      are the actionable items that require HR's attention right now: nudge
//      the manager, fill on their behalf, or fix what they returned.
//
//   2. IN PREP — manager has approved; IT is now provisioning hardware,
//      accounts, and accounts. Tabular, dense, scannable.
//
// Pulled apart on purpose. Mixing them was creating "is this on me or on the
// manager?" confusion. Visual treatment is intentionally calm — no priority
// rails, no color-coded banners. Urgency is conveyed through typography
// (countdown chip turns black on <7d) and inline overdue badges only.
// ============================================================================

const OQ_STAGES = [
  "Request filed", "Hardware shipped", "Accounts provisioning",
  "Welcome packet", "Awaiting start date",
];

function oqTimeAgo(ts) {
  const diff = Date.now() - ts;
  const m = Math.floor(diff / 60000);
  if (m < 60) return `${Math.max(1, m)}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  const d = Math.floor(h / 24);
  return `${d}d ago`;
}

function oqInitials(first, last) {
  return ((first?.[0] || "?") + (last?.[0] || "")).toUpperCase();
}

// Days until start (ceil; today = 0). null if no startDate.
function daysToStart(startDate) {
  if (!startDate) return null;
  return Math.ceil((new Date(startDate) - new Date()) / 86400000);
}

// ── SECTION HEADER ─────────────────────────────────────────────────────────
// Aligns with the table edges (no inset padding). Title left, count + meta
// on the right.
function QueueSectionHeader({ title, kicker, count, action }) {
  return (
    <div style={{
      display: "flex", alignItems: "baseline", justifyContent: "space-between",
      gap: 12, marginBottom: 12,
    }}>
      <div style={{ display: "flex", alignItems: "baseline", gap: 12, flexWrap: "wrap" }}>
        <h2 style={{
          fontFamily: "'Archivo', sans-serif",
          fontSize: 20, fontWeight: 800, letterSpacing: "-0.02em",
          margin: 0, color: "#211E1E",
        }}>{title}</h2>
        <span style={{
          fontFamily: "'Archivo', monospace",
          fontSize: 11, fontWeight: 800,
          padding: "2px 8px",
          background: "#211E1E", color: "#FDC831",
          borderRadius: 3,
        }}>{count}</span>
        {kicker && (
          <span style={{
            fontFamily: "'Archivo', sans-serif",
            fontSize: 11, fontWeight: 700,
            color: "#78684C",
            letterSpacing: "0.02em",
          }}>{kicker}</span>
        )}
      </div>
      {action}
    </div>
  );
}

// ── AWAITING APPROVAL — top section ────────────────────────────────────────
// Card-style rows because each one carries enough context (manager name,
// return note, multiple hires) that a single table row would be cramped.
function AwaitingApprovalSection({ approvals, onOpenApproval, onNudge }) {
  const rows = React.useMemo(() => {
    return approvals
      .filter(r => r.status === "pending" || r.status === "returned")
      .map(req => {
        const primary = req.hires[0] || {};
        const overdue = (Date.now() - req.sentAt) > 1000 * 60 * 60 * 48;
        const returned = req.status === "returned";
        return {
          req, primary, overdue, returned,
          daysUntilStart: daysToStart(primary.startDate),
          sortKey: returned ? 0 : (overdue ? 1 : 2),
          age: Date.now() - req.sentAt,
        };
      })
      .sort((a, b) => {
        if (a.sortKey !== b.sortKey) return a.sortKey - b.sortKey;
        return b.age - a.age; // older first within bucket
      });
  }, [approvals]);

  return (
    <section data-screen-label="Awaiting Approval" style={{ marginBottom: 36 }}>
      <QueueSectionHeader
        title="Awaiting manager approval"
        kicker={rows.length === 0 ? "All caught up" : "Needs a manager's response"}
        count={rows.length}
      />
      {rows.length === 0 ? (
        <div style={{
          padding: "20px 18px",
          background: "#FFFFFF",
          border: "1px dashed rgba(33,30,30,0.2)", borderRadius: 8,
          fontFamily: "'Archivo', sans-serif",
          fontSize: 12.5, fontWeight: 600, color: "#78684C",
        }}>
          No requests waiting on managers right now.
        </div>
      ) : (
        <div style={{ display: "grid", gap: 10 }}>
          {rows.map(r => (
            <ApprovalCard key={r.req.id} row={r}
              onOpen={() => onOpenApproval(r.req.id)}
              onNudge={() => onNudge(r.req.id)} />
          ))}
        </div>
      )}
    </section>
  );
}

function ApprovalCard({ row, onOpen, onNudge }) {
  const { req, primary, overdue, returned, daysUntilStart } = row;
  const ONB_LOCATIONS = window.ONB_LOCATIONS || [];
  const loc = ONB_LOCATIONS.find(l => l.id === primary.location);
  const nudged = !!req.nudgedAt;
  const totalHires = req.hires.length;
  const isBatch = totalHires > 1;
  const extraCount = totalHires - 1;
  // Show up to 3 stacked avatars; if more, the 3rd becomes a "+N" marker.
  const stackHires = req.hires.slice(0, Math.min(3, totalHires));
  const overflowCount = totalHires - stackHires.length;

  return (
    <div role="button" tabIndex={0} onClick={onOpen} className="onb-row-hover"
      onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onOpen(); } }}
      onMouseEnter={(e) => {
        e.currentTarget.style.transform = "translate(-1px,-1px)";
        e.currentTarget.style.boxShadow = "2px 2px 0 #FDC831";
      }}
      onMouseLeave={(e) => {
        e.currentTarget.style.transform = "none";
        e.currentTarget.style.boxShadow = "2px 2px 0 #211E1E";
      }}
      style={{
        display: "grid",
        gridTemplateColumns: "auto 1fr auto",
        gap: 12, alignItems: "center",
        padding: "10px 12px",
        background: "#FFFFFF",
        border: "1px solid #211E1E", borderRadius: 6,
        boxShadow: "2px 2px 0 #211E1E",
        cursor: "pointer", textAlign: "left",
        fontFamily: "'Archivo', sans-serif",
        transition: "transform .12s ease, box-shadow .12s ease",
      }}>
      {/* Avatar(s) — single circle for solo hires, stacked for batches */}
      {isBatch ? (
        <div style={{
          display: "flex", alignItems: "center",
          flexShrink: 0,
          // Total visual width compensates for negative margins on stacked items.
          paddingRight: 4,
        }}>
          {stackHires.map((h, i) => {
            const isLast = i === stackHires.length - 1;
            const showOverflow = isLast && overflowCount > 0;
            return (
              <div key={i} className="onb-row-avatar" style={{
                width: 30, height: 30, borderRadius: "50%",
                background: showOverflow ? "#211E1E" : "#FDC831",
                color: showOverflow ? "#FDC831" : "#211E1E",
                display: "grid", placeItems: "center",
                border: "1px solid #211E1E",
                fontSize: showOverflow ? 10 : 11,
                fontWeight: 900,
                marginLeft: i === 0 ? 0 : -10,
                position: "relative", zIndex: stackHires.length - i,
                fontFamily: "'Archivo', sans-serif",
              }}>
                {showOverflow ? `+${overflowCount}` : oqInitials(h.firstName, h.lastName)}
              </div>
            );
          })}
        </div>
      ) : (
        <div className="onb-row-avatar" style={{
          width: 30, height: 30, borderRadius: "50%",
          background: "#FDC831", color: "#211E1E",
          display: "grid", placeItems: "center",
          border: "1px solid #211E1E",
          fontSize: 11, fontWeight: 900,
          flexShrink: 0,
        }}>{oqInitials(primary.firstName, primary.lastName)}</div>
      )}

      <div style={{ minWidth: 0 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 7, flexWrap: "wrap" }}>
          <span style={{ fontWeight: 800, fontSize: 13, color: "#211E1E", letterSpacing: "-0.005em" }}>
            {primary.firstName} {primary.lastName}
            {isBatch && (
              <span style={{ color: "#78684C", fontWeight: 700 }}>
                {" + "}{extraCount} other{extraCount > 1 ? "s" : ""}
              </span>
            )}
          </span>
          {loc && window.CountryFlag && <window.CountryFlag country={loc.country} size={12} />}
          {isBatch && (
            <span style={{
              padding: "2px 7px",
              background: "#211E1E", color: "#FDC831",
              border: "1px solid #211E1E", borderRadius: 3,
              fontFamily: "'Archivo', sans-serif",
              fontSize: 9, fontWeight: 800,
              letterSpacing: "0.08em", textTransform: "uppercase",
              display: "inline-flex", alignItems: "center", gap: 4,
            }}>
              <svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                <circle cx="9" cy="8" r="3.5"/><circle cx="17" cy="9" r="2.5"/>
                <path d="M3 19a6 6 0 0 1 12 0"/><path d="M15 19a4 4 0 0 1 7 0"/>
              </svg>
              Batch · {totalHires} hires
            </span>
          )}
          {returned && (
            <span style={{
              padding: "1px 6px",
              background: "#B92323", color: "#FFFFFF",
              border: "1px solid #211E1E", borderRadius: 3,
              fontSize: 9, fontWeight: 800,
              letterSpacing: "0.06em", textTransform: "uppercase",
            }}>Returned</span>
          )}
          {overdue && !returned && (
            <span style={{
              padding: "1px 6px",
              background: "#FFFFFF", color: "#B92323",
              border: "1px solid #B92323", borderRadius: 3,
              fontSize: 9, fontWeight: 800,
              letterSpacing: "0.06em", textTransform: "uppercase",
            }}>Overdue</span>
          )}
        </div>
        <div style={{
          fontSize: 11, color: "#78684C", fontWeight: 600, marginTop: 2,
          whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis",
        }}>
          <span style={{ color: "#211E1E", fontWeight: 700 }}>
            {isBatch
              ? req.hires.map(h => h.title).filter((t, i, a) => a.indexOf(t) === i).slice(0, 2).join(" · ")
              : primary.title}
          </span>
          {" · sent to "}<span style={{ color: "#211E1E", fontWeight: 700 }}>{req.manager}</span>
          {" · "}{oqTimeAgo(req.sentAt)}
        </div>
        {returned && req.returnNote && (
          <div style={{
            marginTop: 5,
            padding: "5px 8px",
            background: "#FFE8E8",
            border: "1px solid rgba(185,35,35,0.3)", borderRadius: 3,
            fontSize: 11, fontWeight: 600, color: "#7A1818",
            fontStyle: "italic",
          }}>
            “{req.returnNote}”
          </div>
        )}
      </div>

      <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
        <CountdownChip days={daysUntilStart} compact />
        <button onClick={(e) => { e.stopPropagation(); onNudge(); }}
          disabled={nudged || returned}
          title={nudged ? `Nudged ${oqTimeAgo(req.nudgedAt)}` : "Ping the manager in Slack"}
          style={{
            padding: "6px 10px",
            background: nudged ? "#FFFFFF" : "#211E1E",
            color: nudged ? "#78684C" : "#FDC831",
            border: "1px solid #211E1E", borderRadius: 3,
            fontFamily: "'Archivo', sans-serif",
            fontSize: 10, fontWeight: 800,
            letterSpacing: "0.04em", textTransform: "uppercase",
            cursor: nudged || returned ? "default" : "pointer",
            opacity: returned ? 0.4 : 1,
            whiteSpace: "nowrap",
          }}>
          {nudged ? "Nudged ✓" : "Nudge"}
        </button>
      </div>
    </div>
  );
}

// ── COUNTDOWN CHIP — used in both sections ─────────────────────────────────
function CountdownChip({ days }) {
  if (days === null || days === undefined) {
    return <OQChip muted>—</OQChip>;
  }
  const urgent = days <= 7;
  return (
    <div style={{
      padding: "5px 10px",
      background: urgent ? "#211E1E" : "#FFF9E6",
      color: urgent ? "#FDC831" : "#211E1E",
      border: "1px solid #211E1E", borderRadius: 4,
      fontFamily: "'Archivo', sans-serif",
      textAlign: "center", minWidth: 64,
    }}>
      <div style={{ fontSize: 15, fontWeight: 800, letterSpacing: "-0.02em", lineHeight: 1 }}>
        {days > 0 ? days : days === 0 ? "Today" : "—"}
      </div>
      {days > 0 && (
        <div style={{
          fontSize: 8.5, fontWeight: 800,
          letterSpacing: "0.08em", textTransform: "uppercase",
          marginTop: 1, opacity: 0.85,
        }}>{days === 1 ? "Day" : "Days"}</div>
      )}
    </div>
  );
}
function OQChip({ children, muted }) {
  return <span style={{
    padding: "3px 8px",
    background: muted ? "transparent" : "#FFF9E6",
    color: muted ? "#78684C" : "#211E1E",
    border: muted ? "1.5px dashed rgba(33,30,30,0.2)" : "1.5px solid #211E1E",
    borderRadius: 3,
    fontFamily: "'Archivo', monospace",
    fontSize: 11, fontWeight: 800,
  }}>{children}</span>;
}

// ── IN PREP — bottom table ─────────────────────────────────────────────────
// Sortable, dense, no fluff. Each row is one approved hire.
function InPrepTable({ inProgress, onOpen, onSort, sortBy, sortDir }) {
  const ONB_LOCATIONS = window.ONB_LOCATIONS || [];
  const cols = [
    { id: "name",    label: "Hire",          flex: "1.6fr", align: "left",   sortable: true  },
    { id: "role",    label: "Role",          flex: "1.5fr", align: "left",   sortable: false },
    { id: "manager", label: "Manager",       flex: "1.2fr", align: "left",   sortable: true  },
    { id: "status",  label: "Status",        flex: "150px", align: "left",   sortable: false },
    { id: "start",   label: "Starts",        flex: "100px", align: "right",  sortable: true  },
  ];
  const gridTemplate = cols.map(c => c.flex).join(" ");

  const sorted = React.useMemo(() => {
    const rows = inProgress.map(p => {
      const days = daysToStart(p.startDate);
      return { hire: p, days };
    });
    rows.sort((a, b) => {
      const dir = sortDir === "asc" ? 1 : -1;
      if (sortBy === "name") return dir * `${a.hire.firstName} ${a.hire.lastName}`.localeCompare(`${b.hire.firstName} ${b.hire.lastName}`);
      if (sortBy === "manager") return dir * (a.hire.manager || "").localeCompare(b.hire.manager || "");
      // start
      const ad = a.days ?? Infinity, bd = b.days ?? Infinity;
      return dir * (ad - bd);
    });
    return rows;
  }, [inProgress, sortBy, sortDir]);

  return (
    <div style={{
      background: "#FFFFFF",
      border: "1px solid #211E1E", borderRadius: 8,
      boxShadow: "2px 2px 0 #211E1E",
      overflow: "hidden",
    }}>
      {/* Header row */}
      <div role="row" style={{
        display: "grid",
        gridTemplateColumns: gridTemplate,
        gap: 16, alignItems: "center",
        padding: "10px 18px",
        background: "#FFF9E6",
        borderBottom: "1px solid #211E1E",
        fontFamily: "'Archivo', sans-serif",
        fontSize: 9.5, fontWeight: 900,
        letterSpacing: "0.1em", textTransform: "uppercase",
        color: "#78684C",
      }}>
        {cols.map(c => (
          <div key={c.id} role="columnheader"
            onClick={c.sortable ? () => onSort(c.id) : undefined}
            style={{
              textAlign: c.align,
              cursor: c.sortable ? "pointer" : "default",
              userSelect: "none",
              display: "flex",
              alignItems: "center",
              justifyContent: c.align === "right" ? "flex-end" : c.align === "center" ? "center" : "flex-start",
              gap: 4,
              color: sortBy === c.id ? "#211E1E" : "#78684C",
            }}>
            {c.label}
            {c.sortable && sortBy === c.id && (
              <span style={{ fontSize: 8, opacity: 0.9 }}>{sortDir === "asc" ? "▲" : "▼"}</span>
            )}
          </div>
        ))}
      </div>

      {/* Body */}
      {sorted.length === 0 ? (
        <div style={{
          padding: "32px 18px",
          textAlign: "center",
          fontFamily: "'Archivo', sans-serif",
          fontSize: 12.5, fontWeight: 600, color: "#78684C",
        }}>
          No hires currently in IT prep.
        </div>
      ) : sorted.map((r, idx) => {
        const { hire, days } = r;
        const loc = ONB_LOCATIONS.find(l => l.id === hire.location);
        return (
          <div role="row" key={hire.id} tabIndex={0}
            onClick={() => onOpen(hire)}
            onKeyDown={(e) => { if (e.key === "Enter") { e.preventDefault(); onOpen(hire); } }}
            onMouseEnter={(e) => { e.currentTarget.style.background = "#FFF9E6"; }}
            onMouseLeave={(e) => { e.currentTarget.style.background = idx % 2 ? "#FFFDF7" : "#FFFFFF"; }}
            style={{
              display: "grid",
              gridTemplateColumns: gridTemplate,
              gap: 16, alignItems: "center",
              padding: "12px 18px",
              background: idx % 2 ? "#FFFDF7" : "#FFFFFF",
              borderBottom: idx === sorted.length - 1 ? "none" : "1px solid rgba(33,30,30,0.08)",
              cursor: "pointer",
              fontFamily: "'Archivo', sans-serif",
              transition: "background .1s ease",
            }}>
            {/* Hire (avatar + name + flag) */}
            <div style={{ display: "flex", alignItems: "center", gap: 10, minWidth: 0 }}>
              <div className="onb-row-avatar" style={{
                width: 30, height: 30, borderRadius: "50%",
                background: "#FDC831", color: "#211E1E",
                display: "grid", placeItems: "center",
                border: "1px solid #211E1E",
                fontSize: 11, fontWeight: 900,
                flexShrink: 0,
                position: "relative",
                zIndex: 1,
                transition: "transform .15s cubic-bezier(.34,1.56,.64,1), box-shadow .15s ease",
              }}>{oqInitials(hire.firstName, hire.lastName)}</div>
              <div style={{ minWidth: 0 }}>
                <div style={{
                  display: "flex", alignItems: "center", gap: 6,
                  fontWeight: 800, fontSize: 13, color: "#211E1E",
                  whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis",
                }}>
                  <span style={{ overflow: "hidden", textOverflow: "ellipsis" }}>
                    {hire.firstName} {hire.lastName}
                  </span>
                  {loc && window.CountryFlag && <window.CountryFlag country={loc.country} size={12} />}
                </div>
              </div>
            </div>

            {/* Role */}
            <div style={{
              fontSize: 12, color: "#4A3F2E", fontWeight: 600,
              whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis",
            }}>
              {hire.title}
              <div style={{ fontSize: 10.5, color: "#78684C", marginTop: 1 }}>
                {hire.topDept || hire.department}
              </div>
            </div>

            {/* Manager */}
            <div style={{
              fontSize: 12, color: "#4A3F2E", fontWeight: 600,
              whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis",
            }}>
              {hire.manager || "—"}
            </div>

            {/* Status — once HR files the request it's a ticket on IT's side.
                One simple checkmark + label; the new ticketing system owns
                the actual work state. */}
            <div style={{ display: "flex", alignItems: "center", gap: 8, minWidth: 0 }}>
              <div style={{
                width: 22, height: 22, flexShrink: 0,
                borderRadius: "50%",
                background: "#0A8A3E", color: "#FFFFFF",
                border: "1px solid #211E1E",
                display: "grid", placeItems: "center",
                boxShadow: "1px 1px 0 #211E1E",
              }}>
                <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3.2" strokeLinecap="round" strokeLinejoin="round">
                  <polyline points="20 6 9 17 4 12"/>
                </svg>
              </div>
              <span style={{
                fontFamily: "'Archivo', sans-serif",
                fontSize: 11.5, fontWeight: 800, color: "#211E1E",
                letterSpacing: "-0.005em",
                whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis",
              }}>Sent to IT</span>
            </div>

            {/* Start countdown */}
            <div style={{ display: "flex", justifyContent: "flex-end" }}>
              <CountdownChip days={days} />
            </div>
          </div>
        );
      })}
    </div>
  );
}

// ── MAIN ───────────────────────────────────────────────────────────────────
function UnifiedOnboardingQueue({
  approvals = [],
  inProgress = [],
  onOpenApproval,
  onOpenHire,
  onNudge,
}) {
  const [sortBy, setSortBy] = React.useState("start");
  const [sortDir, setSortDir] = React.useState("asc");
  const handleSort = (col) => {
    if (col === sortBy) {
      setSortDir(d => d === "asc" ? "desc" : "asc");
    } else {
      setSortBy(col);
      setSortDir(col === "start" ? "asc" : "asc");
    }
  };

  return (
    <>
      <AwaitingApprovalSection
        approvals={approvals}
        onOpenApproval={onOpenApproval}
        onNudge={onNudge}
      />

      <section data-screen-label="In Prep">
        <QueueSectionHeader
          title="In prep"
          kicker={inProgress.length === 0 ? "Nothing in prep" : "Manager approved · IT provisioning"}
          count={inProgress.length}
        />
        <InPrepTable
          inProgress={inProgress}
          onOpen={onOpenHire}
          onSort={handleSort}
          sortBy={sortBy}
          sortDir={sortDir}
        />
      </section>
    </>
  );
}

Object.assign(window, {
  UnifiedOnboardingQueue,
});

// ─── misc (c0c64165) ──────────────────────────────────
// ====================================================================
//  Slice IT Hub — Screenshot AI helper
//  "Drop a screenshot of what you're seeing, AI tells you what to do."
//  Used both standalone (from landing) and inline within Guided Mode.
// ====================================================================

// (hooks already destructured at top of file)

// --------------------------------------------------------------------
//  Real screenshot analysis — POSTs the image to /api/help/screenshot,
//  which routes it through Claude vision with the live KB title list as
//  grounding so suggestions point at real guides instead of inventing them.
//  Returns the server's already-validated payload (or throws so the UI can
//  surface the failure cleanly).
// --------------------------------------------------------------------
async function analyzeScreenshot({ dataUrl, note = "" }) {
  if (!dataUrl) throw new Error('Missing screenshot data URL');
  const r = await fetch('/api/help/screenshot', {
    method: 'POST',
    credentials: 'include',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ imageDataUrl: dataUrl, note }),
  });
  if (!r.ok) {
    let detail = `HTTP ${r.status}`;
    try { const j = await r.json(); detail = j.error || j.detail || detail; } catch {}
    throw new Error(detail);
  }
  return r.json();
}

// --------------------------------------------------------------------
//  ScreenshotHelper — modal with three states: empty → analyzing → result
// --------------------------------------------------------------------
function ScreenshotHelper({ onClose, onOpenGuide, onFileTicket, initialNote = "", initialFile = null }) {
  const [phase, setPhase] = useState("empty"); // 'empty' | 'analyzing' | 'result'
  const [file, setFile] = useState(initialFile); // { name, dataUrl }
  const [note, setNote] = useState(initialNote);
  const [dragOver, setDragOver] = useState(false);
  const [pasted, setPasted] = useState(false);
  const [result, setResult] = useState(null);
  const [progress, setProgress] = useState(0);
  const fileInputRef = useRef(null);
  // When the parent opened the modal with a file already attached (the
  // hero-input flow), kick analysis off immediately instead of forcing the
  // user through the empty drop zone first. The flag stays low so subsequent
  // file replacements via the in-modal picker still go through the manual
  // "Analyze" button.
  const autoStartedRef = useRef(false);

  // Esc to close
  useEffect(() => {
    const onKey = (e) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  // Listen for paste anywhere in the modal
  useEffect(() => {
    const onPaste = (e) => {
      const items = e.clipboardData?.items;
      if (!items) return;
      for (const item of items) {
        if (item.type.startsWith("image/")) {
          const blob = item.getAsFile();
          handleFile(blob, "pasted-screenshot.png");
          setPasted(true);
          setTimeout(() => setPasted(false), 1500);
          break;
        }
      }
    };
    window.addEventListener("paste", onPaste);
    return () => window.removeEventListener("paste", onPaste);
  }, []);

  const handleFile = useCallback((blob, fallbackName) => {
    if (!blob) return;
    if (!blob.type.startsWith("image/")) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      setFile({ name: blob.name || fallbackName || "screenshot.png", dataUrl: e.target.result });
    };
    reader.readAsDataURL(blob);
  }, []);

  const onDrop = (e) => {
    e.preventDefault();
    setDragOver(false);
    const f = e.dataTransfer.files?.[0];
    if (f) handleFile(f);
  };

  const onPick = (e) => {
    const f = e.target.files?.[0];
    if (f) handleFile(f);
  };

  const removeFile = () => { setFile(null); setResult(null); setPhase("empty"); };

  const [error, setError] = useState(null);

  const runAnalysis = async () => {
    if (!file) return;
    setPhase("analyzing");
    setProgress(0);
    setError(null);
    // Soft progress bar while the vision call is in flight — capped at 92%
    // until the response actually arrives.
    let p = 0;
    const tick = setInterval(() => {
      p += 6 + Math.random() * 10;
      setProgress(Math.min(p, 92));
    }, 220);
    try {
      const r = await analyzeScreenshot({ dataUrl: file.dataUrl, note });
      clearInterval(tick);
      setProgress(100);
      setResult(r);
      setPhase("result");
    } catch (err) {
      clearInterval(tick);
      setProgress(0);
      setError(err.message || 'Analysis failed');
      setPhase("empty");
    }
  };

  const openGuide = (g) => {
    if (!g || !onOpenGuide) return;
    onOpenGuide({ id: g.id, title: g.title, category: g.category });
    onClose();
  };
  const openSuggestedGuide = () => {
    const first = result?.guide_suggestions?.[0];
    if (first) openGuide(first);
  };

  // Auto-start analysis when the modal mounts with a pre-attached file (the
  // hero-input "paperclip in chat" flow). Guarded so we run it exactly once.
  useEffect(() => {
    if (autoStartedRef.current) return;
    if (initialFile && file && phase === "empty") {
      autoStartedRef.current = true;
      runAnalysis();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div
      onClick={onClose}
      style={{
        position: "fixed", inset: 0, zIndex: 110,
        background: "rgba(33,30,30,0.45)", backdropFilter: "blur(6px)",
        animation: "ssIn .25s var(--ease) both",
        display: "flex", alignItems: "flex-start", justifyContent: "center",
        padding: "60px 24px 40px",
        overflowY: "auto",
      }}
    >
      <style>{`
        @keyframes ssIn { from { opacity: 0; } to { opacity: 1; } }
        @keyframes ssPanelIn { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: none; } }
        @keyframes scanLine {
          0% { transform: translateY(-4%); opacity: 0; }
          15% { opacity: 1; }
          85% { opacity: 1; }
          100% { transform: translateY(104%); opacity: 0; }
        }
        @keyframes pulseBox {
          0%, 100% { box-shadow: 0 0 0 0 rgba(253,200,49,0.6); }
          50% { box-shadow: 0 0 0 8px rgba(253,200,49,0); }
        }
        .ss-action-btn { transition: transform .15s, box-shadow .15s; }
        .ss-action-btn:hover { transform: translate(-2px,-2px); box-shadow: 3px 3px 0 #211E1E; }
        .ss-action-btn:active { transform: translate(1px,1px); box-shadow: 1px 1px 0 #211E1E; }
      `}</style>

      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          width: "min(720px, 100%)",
          background: "#FFF9E6",
          border: "1px solid #211E1E",
          borderRadius: 14,
          boxShadow: "4px 4px 0 #211E1E",
          padding: 0,
          animation: "ssPanelIn .35s var(--ease) both",
          overflow: "hidden",
        }}
      >
        {/* Header */}
        <div style={{
          padding: "20px 28px",
          borderBottom: "1px solid #211E1E",
          background: "#FDC831",
          display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12,
        }}>
          <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
            <div style={{
              width: 36, height: 36, borderRadius: 8,
              background: "#211E1E", color: "#FDC831",
              border: "1px solid #211E1E",
              display: "grid", placeItems: "center",
              fontFamily: "Archivo, sans-serif",
              fontSize: 18, fontWeight: 900,
            }}>📷</div>
            <div>
              <div style={{
                fontFamily: "Archivo, sans-serif",
                fontSize: 10.5, fontWeight: 900,
                letterSpacing: "0.08em", textTransform: "uppercase",
                color: "#4A3F2E",
              }}>Show, don't type</div>
              <div style={{
                fontFamily: "Archivo, sans-serif",
                fontSize: 19, fontWeight: 800, color: "#211E1E",
                letterSpacing: "-0.018em",
              }}>
                Add a screenshot — we'll take a look
              </div>
            </div>
          </div>
          <button onClick={onClose} aria-label="Close" style={{
            width: 32, height: 32,
            background: "#FFFFFF",
            border: "1px solid #211E1E", borderRadius: 4,
            boxShadow: "1px 1px 0 #211E1E",
            display: "grid", placeItems: "center",
            color: "#211E1E", cursor: "pointer",
            fontFamily: "Archivo, sans-serif",
            fontSize: 16, fontWeight: 900,
          }}>×</button>
        </div>

        <div style={{ padding: "26px 28px 28px" }}>
          {phase === "empty" && (
            <>
              {/* Drop zone */}
              <label
                htmlFor="ss-file-input"
                onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
                onDragLeave={() => setDragOver(false)}
                onDrop={onDrop}
                style={{
                  display: "block",
                  background: dragOver ? "#FDC831" : "#FFFFFF",
                  border: `2.5px dashed ${dragOver ? "#211E1E" : "rgba(33,30,30,0.4)"}`,
                  borderRadius: 12,
                  padding: file ? "0" : "44px 24px",
                  textAlign: "center",
                  cursor: "pointer",
                  transition: "background .2s, border-color .2s",
                  position: "relative",
                  overflow: "hidden",
                  animation: pasted ? "pulseBox .9s ease" : "none",
                }}
              >
                {file ? (
                  <div style={{ position: "relative" }}>
                    <img
                      src={file.dataUrl}
                      alt="screenshot preview"
                      style={{
                        width: "100%",
                        maxHeight: 320,
                        objectFit: "contain",
                        background: "#211E1E",
                        display: "block",
                      }}
                    />
                    <button
                      onClick={(e) => { e.preventDefault(); e.stopPropagation(); removeFile(); }}
                      style={{
                        position: "absolute", top: 10, right: 10,
                        padding: "6px 10px",
                        background: "#FFFFFF",
                        border: "1px solid #211E1E", borderRadius: 4,
                        boxShadow: "1px 1px 0 #211E1E",
                        fontFamily: "Archivo, sans-serif",
                        fontSize: 11, fontWeight: 800,
                        letterSpacing: "0.04em", textTransform: "uppercase",
                        color: "#211E1E", cursor: "pointer",
                      }}
                    >
                      Remove
                    </button>
                    <div style={{
                      position: "absolute", bottom: 0, left: 0, right: 0,
                      padding: "8px 12px",
                      background: "rgba(33,30,30,0.9)",
                      color: "#FDC831",
                      fontFamily: "ui-monospace, SF Mono, Menlo, monospace",
                      fontSize: 11.5,
                      textAlign: "left",
                    }}>
                      {file.name}
                    </div>
                  </div>
                ) : (
                  <>
                    <div style={{
                      width: 56, height: 56, borderRadius: 12,
                      background: dragOver ? "#211E1E" : "#FDC831",
                      color: dragOver ? "#FDC831" : "#211E1E",
                      border: "1px solid #211E1E",
                      display: "grid", placeItems: "center",
                      margin: "0 auto 14px",
                      fontFamily: "Archivo, sans-serif",
                      fontSize: 28, fontWeight: 900,
                      transition: "background .2s, color .2s",
                    }}>↑</div>
                    <div style={{
                      fontFamily: "Archivo, sans-serif",
                      fontSize: 17, fontWeight: 800, color: "#211E1E",
                      marginBottom: 6, letterSpacing: "-0.012em",
                    }}>
                      {dragOver ? "Drop it!" : "Drag a screenshot here"}
                    </div>
                    <div style={{ fontSize: 13, color: "#4A3F2E", lineHeight: 1.5 }}>
                      or <span style={{ textDecoration: "underline", fontWeight: 700 }}>browse files</span>
                      {" · "}
                      paste with <kbd style={kbd}>⌘V</kbd> / <kbd style={kbd}>Ctrl V</kbd>
                    </div>
                  </>
                )}
                <input
                  id="ss-file-input"
                  ref={fileInputRef}
                  type="file"
                  accept="image/*"
                  onChange={onPick}
                  style={{ display: "none" }}
                />
              </label>

              {/* Optional note */}
              <div style={{ marginTop: 18 }}>
                <label style={{
                  display: "block",
                  fontFamily: "Archivo, sans-serif",
                  fontSize: 10.5, fontWeight: 800,
                  letterSpacing: "0.06em", textTransform: "uppercase",
                  color: "#4A3F2E", marginBottom: 6,
                }}>
                  Optional note <span style={{ fontWeight: 600, color: "#78684C" }}>· what's going wrong?</span>
                </label>
                <textarea
                  value={note}
                  onChange={(e) => setNote(e.target.value)}
                  rows={2}
                  placeholder="e.g. Slack won't sign in, this is what I see"
                  style={{
                    width: "100%",
                    background: "#FFFFFF",
                    border: "1px solid #211E1E",
                    borderRadius: 8,
                    padding: "10px 12px",
                    fontFamily: "inherit",
                    fontSize: 14,
                    color: "#211E1E",
                    resize: "vertical",
                    outline: "none",
                  }}
                />
              </div>

              {/* Privacy note + CTA */}
              <div style={{
                marginTop: 18,
                display: "flex", justifyContent: "space-between", alignItems: "center", gap: 12,
                flexWrap: "wrap",
              }}>
                <div style={{ fontSize: 11.5, color: "#4A3F2E", lineHeight: 1.45, maxWidth: 360 }}>
                  <strong style={{ color: "#211E1E" }}>Private.</strong> Your screenshot stays in this session — it isn't stored unless you file a ticket.
                </div>
                <button
                  onClick={runAnalysis}
                  disabled={!file}
                  className="ss-action-btn"
                  style={{
                    padding: "12px 22px",
                    background: file ? "#211E1E" : "#E0DCCF",
                    color: file ? "#FDC831" : "#78684C",
                    border: `2px solid ${file ? "#211E1E" : "#C9C2B0"}`,
                    borderRadius: 4,
                    boxShadow: file ? "2px 2px 0 #FDC831" : "none",
                    fontFamily: "Archivo, sans-serif",
                    fontWeight: 800, fontSize: 13,
                    letterSpacing: "0.04em", textTransform: "uppercase",
                    cursor: file ? "pointer" : "not-allowed",
                    display: "inline-flex", alignItems: "center", gap: 8,
                  }}
                >
                  Take a look <span style={{ fontSize: 14 }}>→</span>
                </button>
              </div>
            </>
          )}

          {phase === "analyzing" && (
            <AnalyzingView file={file} progress={progress} />
          )}

          {phase === "result" && result && (
            <ResultView
              file={file}
              result={result}
              onOpenGuide={openSuggestedGuide}
              onOpenSpecificGuide={openGuide}
              onFileTicket={() => {
                onFileTicket?.({
                  team: "IT Team",
                  source: "Screenshot diagnosis: " + result.diagnosis,
                });
                onClose();
              }}
              onRetry={() => { setPhase("empty"); setResult(null); setError(null); }}
            />
          )}

          {/* Error banner — surfaced when the vision call fails so the user
              isn't left staring at a stalled progress bar. Stays on the empty
              phase so they can retry or remove the file. */}
          {error && phase === "empty" && (
            <div style={{
              marginTop: 14,
              padding: "10px 14px",
              background: "#FFE8E5",
              border: "1px solid #DA3327",
              borderRadius: 8,
              fontSize: 12.5, color: "#7A1A14", fontWeight: 600,
              lineHeight: 1.45,
            }}>
              Couldn't analyze this screenshot — {error}. Try again, or file a ticket and we'll review it manually.
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

const kbd = {
  display: "inline-block",
  padding: "1px 5px",
  fontFamily: "ui-monospace, SF Mono, Menlo, monospace",
  fontSize: 10.5,
  background: "#FFFFFF",
  border: "1px solid rgba(33,30,30,0.3)",
  borderRadius: 3,
  color: "#211E1E",
  fontWeight: 600,
};

// --------------------------------------------------------------------
//  AnalyzingView — image with scanning line + streamed status
// --------------------------------------------------------------------
function AnalyzingView({ file, progress }) {
  const stages = [
    { at: 10,  label: "Reading the image…" },
    { at: 35,  label: "Identifying app and error state…" },
    { at: 65,  label: "Cross-referencing common fixes…" },
    { at: 90,  label: "Picking the right guide…" },
  ];
  const current = [...stages].reverse().find(s => progress >= s.at) || stages[0];

  return (
    <div>
      <div style={{
        position: "relative",
        background: "#211E1E",
        border: "1px solid #211E1E",
        borderRadius: 12,
        overflow: "hidden",
        marginBottom: 18,
      }}>
        <img
          src={file?.dataUrl}
          alt=""
          style={{
            width: "100%",
            maxHeight: 280,
            objectFit: "contain",
            display: "block",
            opacity: 0.85,
          }}
        />
        {/* Scanning line */}
        <div style={{
          position: "absolute", left: 0, right: 0,
          height: 3,
          background: "linear-gradient(90deg, transparent, #FDC831, transparent)",
          boxShadow: "0 0 16px #FDC831",
          animation: "scanLine 1.6s linear infinite",
        }}/>
        {/* Corner markers */}
        {[
          { top: 10, left: 10 }, { top: 10, right: 10 },
          { bottom: 10, left: 10 }, { bottom: 10, right: 10 },
        ].map((pos, i) => (
          <div key={i} style={{
            position: "absolute",
            ...pos,
            width: 14, height: 14,
            border: "1px solid #FDC831",
            borderRadius: 2,
          }}/>
        ))}
      </div>

      {/* Progress bar */}
      <div style={{
        height: 8,
        background: "#FFFFFF",
        border: "1px solid #211E1E",
        borderRadius: 999,
        overflow: "hidden",
        marginBottom: 12,
      }}>
        <div style={{
          height: "100%",
          width: `${progress}%`,
          background: "#211E1E",
          transition: "width .25s var(--ease)",
        }}/>
      </div>

      <div style={{
        fontFamily: "Archivo, sans-serif",
        fontSize: 13.5, fontWeight: 700,
        color: "#211E1E",
        display: "flex", alignItems: "center", gap: 10,
      }}>
        <span style={{
          width: 8, height: 8, borderRadius: "50%",
          background: "#0A8A3E",
          animation: "pulseBox 1.2s ease-in-out infinite",
        }}/>
        {current.label}
      </div>
    </div>
  );
}

// --------------------------------------------------------------------
//  ResultView — diagnosis + suggested guide + next steps + ticket
// --------------------------------------------------------------------
function ResultView({ file, result, onOpenGuide, onOpenSpecificGuide, onFileTicket, onRetry }) {
  const confPct = Math.round((result.confidence || 0) * 100);
  const confTone = result.confidence >= 0.7 ? "high" : (result.confidence >= 0.5 ? "med" : "low");
  const confColor = confTone === "high" ? "#0A8A3E" : (confTone === "med" ? "#B8860B" : "#DA3327");
  const isHardware = result.is_hardware_issue === true;
  const suggestions = Array.isArray(result.guide_suggestions) ? result.guide_suggestions : [];
  const steps = Array.isArray(result.next_steps) ? result.next_steps : [];
  const clues = Array.isArray(result.clues) ? result.clues : [];

  return (
    <div>
      {/* Image thumb + diagnosis */}
      <div style={{ display: "grid", gridTemplateColumns: "120px 1fr", gap: 16, alignItems: "flex-start", marginBottom: 20 }}>
        <div style={{
          width: 120, height: 90,
          background: "#211E1E",
          border: "1px solid #211E1E",
          borderRadius: 8,
          overflow: "hidden",
          flexShrink: 0,
        }}>
          <img src={file?.dataUrl} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }}/>
        </div>
        <div>
          <div style={{
            display: "inline-flex", alignItems: "center", gap: 8,
            padding: "3px 10px",
            background: isHardware ? "#DA3327" : confColor,
            color: "#FFFFFF",
            border: `1.5px solid ${isHardware ? "#DA3327" : confColor}`,
            borderRadius: 999,
            fontFamily: "Archivo, sans-serif",
            fontSize: 10, fontWeight: 800,
            letterSpacing: "0.06em", textTransform: "uppercase",
            marginBottom: 8,
          }}>
            <span style={{ width: 6, height: 6, borderRadius: "50%", background: "#FFFFFF" }}/>
            {isHardware ? "Hardware issue" : `${confPct}% confident`}
          </div>
          <div style={{
            fontFamily: "Archivo, sans-serif",
            fontSize: 10.5, fontWeight: 900,
            letterSpacing: "0.06em", textTransform: "uppercase",
            color: "#4A3F2E", marginBottom: 4,
          }}>What we see</div>
          <h3 style={{
            fontFamily: "Archivo, sans-serif",
            fontSize: 22, fontWeight: 800,
            letterSpacing: "-0.02em", lineHeight: 1.15,
            margin: 0, color: "#211E1E",
          }}>
            {result.diagnosis}
          </h3>
        </div>
      </div>

      {/* Hardware short-circuit — replaces Clues + Steps + Guides with one
          clear "go file a ticket" message so users don't try to self-repair
          a damaged device. */}
      {isHardware && (
        <div style={{
          background: "#FFE8E5",
          border: "1px solid #DA3327",
          borderRadius: 10,
          boxShadow: "2px 2px 0 #DA3327",
          padding: "16px 18px",
          marginBottom: 18,
        }}>
          <div style={{
            fontFamily: "Archivo, sans-serif",
            fontSize: 10.5, fontWeight: 900,
            letterSpacing: "0.06em", textTransform: "uppercase",
            color: "#7A1A14", marginBottom: 6,
          }}>Hardware repair — IT Team only</div>
          <div style={{ fontSize: 14, color: "#211E1E", lineHeight: 1.55, marginBottom: 6 }}>
            This looks like physical damage or a hardware failure. Don't try to fix it yourself —
            stop using the device if it's unsafe (battery swelling, smoke, liquid damage), back up
            anything you can still reach, and file a ticket so the <strong>IT Team</strong> can
            inspect it or swap the device.
          </div>
          {clues.length > 0 && (
            <ul style={{ margin: "8px 0 0", paddingLeft: 20, fontSize: 13, color: "#3D1E1B", lineHeight: 1.55 }}>
              {clues.map((c, i) => <li key={i}>{c}</li>)}
            </ul>
          )}
        </div>
      )}

      {/* Clues + Next-steps + Guide suggestions — software path only */}
      {!isHardware && (
        <>
          {clues.length > 0 && (
            <div style={{
              background: "#FFFFFF",
              border: "1px solid #211E1E",
              borderRadius: 8,
              padding: "14px 18px",
              marginBottom: 18,
            }}>
              <div style={{
                fontFamily: "Archivo, sans-serif",
                fontSize: 10.5, fontWeight: 800,
                letterSpacing: "0.06em", textTransform: "uppercase",
                color: "#4A3F2E", marginBottom: 8,
              }}>What gave it away</div>
              <ul style={{ margin: 0, paddingLeft: 20, fontSize: 13.5, color: "#211E1E", lineHeight: 1.6 }}>
                {clues.map((c, i) => <li key={i}>{c}</li>)}
              </ul>
            </div>
          )}

          {/* Suggested guides — up to 3, real KB rows. Click opens the guide. */}
          {suggestions.length > 0 && (
            <div style={{ marginBottom: 18 }}>
              <div style={{
                fontFamily: "Archivo, sans-serif",
                fontSize: 10.5, fontWeight: 800,
                letterSpacing: "0.06em", textTransform: "uppercase",
                color: "#4A3F2E", marginBottom: 10,
              }}>{suggestions.length === 1 ? "Recommended guide" : "Recommended guides"}</div>
              <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                {suggestions.map((g, i) => (
                  <div
                    key={g.id ?? i}
                    onClick={() => onOpenSpecificGuide && onOpenSpecificGuide(g)}
                    className="ss-action-btn"
                    style={{
                      background: i === 0 ? "#FDC831" : "#FFFFFF",
                      border: "1px solid #211E1E",
                      borderRadius: 10,
                      boxShadow: "2px 2px 0 #211E1E",
                      padding: "12px 16px",
                      cursor: "pointer",
                      display: "flex", alignItems: "center", gap: 14,
                    }}
                  >
                    <div style={{
                      width: 36, height: 36, borderRadius: 8,
                      background: "#211E1E", color: "#FDC831",
                      border: "1px solid #211E1E",
                      display: "grid", placeItems: "center",
                      fontFamily: "Archivo, sans-serif",
                      fontSize: 16, fontWeight: 900,
                      flexShrink: 0,
                    }}>→</div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{
                        fontFamily: "Archivo, sans-serif",
                        fontSize: 15, fontWeight: 800,
                        color: "#211E1E", letterSpacing: "-0.01em",
                      }}>{g.title}</div>
                      {(g.reason || g.category) && (
                        <div style={{ fontSize: 12, color: "#4A3F2E", marginTop: 2, lineHeight: 1.4 }}>
                          {g.reason || g.category}
                        </div>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* What to try */}
          {steps.length > 0 && (
            <div style={{ marginBottom: 22 }}>
              <div style={{
                fontFamily: "Archivo, sans-serif",
                fontSize: 10.5, fontWeight: 800,
                letterSpacing: "0.06em", textTransform: "uppercase",
                color: "#4A3F2E", marginBottom: 10,
              }}>Try this in order</div>
              <ol style={{ margin: 0, paddingLeft: 0, listStyle: "none" }}>
                {steps.map((s, i) => (
                  <li key={i} style={{
                    display: "grid", gridTemplateColumns: "26px 1fr",
                    gap: 12, padding: "8px 0",
                    borderBottom: i < steps.length - 1 ? "1px dashed rgba(33,30,30,0.18)" : "none",
                  }}>
                    <div style={{
                      width: 22, height: 22, borderRadius: "50%",
                      background: "#FFFFFF",
                      border: "1px solid #211E1E",
                      display: "grid", placeItems: "center",
                      fontFamily: "Archivo, sans-serif",
                      fontSize: 11, fontWeight: 800,
                      color: "#211E1E",
                      flexShrink: 0,
                    }}>{i + 1}</div>
                    <div style={{ fontSize: 14, color: "#211E1E", lineHeight: 1.5, paddingTop: 1 }}>
                      {s}
                    </div>
                  </li>
                ))}
              </ol>
            </div>
          )}
        </>
      )}

      {/* Footer actions */}
      <div style={{
        display: "flex", gap: 10, justifyContent: "space-between", alignItems: "center", flexWrap: "wrap",
        paddingTop: 18, borderTop: "1px dashed rgba(33,30,30,0.2)",
      }}>
        <button
          onClick={onRetry}
          style={{
            padding: "10px 16px",
            background: "transparent",
            border: "1px solid #211E1E", borderRadius: 4,
            fontFamily: "Archivo, sans-serif",
            fontWeight: 800, fontSize: 12,
            letterSpacing: "0.04em", textTransform: "uppercase",
            color: "#211E1E", cursor: "pointer",
          }}
        >
          ↺ Try a different screenshot
        </button>
        <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
          <button
            onClick={onFileTicket}
            className="ss-action-btn"
            style={{
              padding: "11px 18px",
              background: isHardware ? "#211E1E" : "#FFFFFF",
              color: isHardware ? "#FDC831" : "#211E1E",
              border: "1px solid #211E1E", borderRadius: 4,
              boxShadow: isHardware ? "2px 2px 0 #FDC831" : "2px 2px 0 #211E1E",
              fontFamily: "Archivo, sans-serif",
              fontWeight: 800, fontSize: 12.5,
              letterSpacing: "0.04em", textTransform: "uppercase",
              cursor: "pointer",
            }}
          >
            {isHardware ? "File ticket with the IT Team →" : "File ticket with screenshot"}
          </button>
          {!isHardware && suggestions.length > 0 && (
            <button
              onClick={onOpenGuide}
              className="ss-action-btn"
              style={{
                padding: "11px 18px",
                background: "#211E1E",
                color: "#FDC831",
                border: "1px solid #211E1E", borderRadius: 4,
                boxShadow: "2px 2px 0 #FDC831",
                fontFamily: "Archivo, sans-serif",
                fontWeight: 800, fontSize: 12.5,
                letterSpacing: "0.04em", textTransform: "uppercase",
                cursor: "pointer",
                display: "inline-flex", alignItems: "center", gap: 6,
              }}
            >
              Walk me through the fix →
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

// --------------------------------------------------------------------
//  ScreenshotEntry — landing-page entry-point card next to search
// --------------------------------------------------------------------
// Inline call-out used inside a guide step — invites the user to drop a
// screenshot of where they got stuck so we can take a look.
function ScreenshotEntry({ onOpen, headline, subline }) {
  return (
    <button
      onClick={onOpen}
      className="ss-action-btn"
      style={{
        width: "100%",
        display: "flex", alignItems: "center", gap: 14,
        padding: "14px 18px",
        background: "#FFFFFF",
        border: "1px dashed #211E1E",
        borderRadius: 12,
        boxShadow: "2px 2px 0 #211E1E",
        cursor: "pointer",
        textAlign: "left",
        fontFamily: "inherit",
      }}
    >
      <div style={{
        width: 40, height: 40, borderRadius: 8,
        background: "#FDC831",
        border: "1px solid #211E1E",
        color: "#211E1E",
        display: "grid", placeItems: "center",
        fontFamily: "Archivo, sans-serif",
        fontSize: 20, fontWeight: 900,
        flexShrink: 0,
      }}>📷</div>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{
          fontFamily: "Archivo, sans-serif",
          fontSize: 14.5, fontWeight: 800, color: "#211E1E",
          letterSpacing: "-0.012em",
        }}>
          {headline || "Add a screenshot of what you're seeing"}
        </div>
        <div style={{ fontSize: 12, color: "#4A3F2E", marginTop: 2, lineHeight: 1.4 }}>
          {subline || "We'll take a look and point you at the right fix."}
        </div>
      </div>
      <div style={{
        fontFamily: "Archivo, sans-serif",
        fontSize: 11, fontWeight: 800,
        letterSpacing: "0.06em", textTransform: "uppercase",
        color: "#4A3F2E",
        display: "inline-flex", alignItems: "center", gap: 6,
        flexShrink: 0,
      }}>
        Open <span style={{ fontSize: 14 }}>→</span>
      </div>
    </button>
  );
}

// Export
window.ScreenshotHelper = ScreenshotHelper;
window.ScreenshotEntry = ScreenshotEntry;


// ====================================================================
//  GuideExperience — single-page reader. Fetches guide body from
//  /api/guides/:id and renders the markdown in one big content card.
//  Title sits on the yellow page background; content lives in a single
//  full-width card below. No step-by-step nav.
// ====================================================================

// Date/time tokens embedded in content (guides, bot answers): an author writes
// an absolute instant and every reader sees it in their OWN local timezone —
// the browser resolves the zone for us, so nothing needs passing through.
//   {{d:<ISO>}}   → date only        e.g. "July 23, 2026"
//   {{dt:<ISO>}}  → date + time + tz e.g. "July 23, 2026, 1:00 AM GMT+1"
// An unparseable instant is left as its literal text rather than throwing.
function substituteDateTokens(str) {
  if (!str || str.indexOf('{{') === -1) return str;
  return String(str).replace(/\{\{(dt|d):\s*([^}]+?)\s*\}\}/g, (whole, kind, iso) => {
    const dt = new Date(iso);
    if (Number.isNaN(dt.getTime())) return whole; // not a valid instant — leave as-is
    return kind === 'dt'
      ? dt.toLocaleString(undefined, { year: 'numeric', month: 'long', day: 'numeric', hour: 'numeric', minute: '2-digit', timeZoneName: 'short' })
      : dt.toLocaleDateString(undefined, { year: 'numeric', month: 'long', day: 'numeric' });
  });
}

function renderMarkdown(md, opts = {}) {
  const stepStyle = opts.stepStyle === 'cards' ? 'cards' : 'plain';
  // Chat answers reference excerpt cards shown below as [1] [2] [3]. Those
  // markers add noise inline — strip them before rendering. (Real markdown
  // links of the form [Text](url) survive because the regex only matches
  // brackets containing digits.)
  const stripCitations = opts.stripCitations === true || stepStyle === 'cards';
  let raw = substituteDateTokens(String(md ?? '').replace(/\r\n/g, '\n'));
  if (stripCitations) {
    raw = raw.replace(/\s*\[\d+\](?:\s*\[\d+\])*/g, '');
  }
  const lines = raw.split('\n');
  const out = [];
  let i = 0;
  let key = 0;

  function inline(text) {
    const nodes = [];
    let buf = '';
    let j = 0;
    const flush = () => { if (buf) { nodes.push(buf); buf = ''; } };
    while (j < text.length) {
      // Image: ![alt](url) — Notion-style chrome (no border, soft shadow, max
      // height capped so tall screenshots don't dominate, centered by default).
      // The class="guide-img" + cursor opt-in lets the parent reader catch
      // clicks and open a fullscreen lightbox.
      if (text.slice(j, j + 2) === '![') {
        const close = text.indexOf(']', j + 2);
        if (close !== -1 && text[close + 1] === '(') {
          const urlEnd = text.indexOf(')', close + 2);
          if (urlEnd !== -1) {
            flush();
            const alt = text.slice(j + 2, close);
            const src = text.slice(close + 2, urlEnd);
            nodes.push(<img key={key++} className="guide-img" src={src} alt={alt} loading="lazy" style={{ display: 'block', maxWidth: 'calc(100% - 20px)', maxHeight: '70vh', width: 'auto', height: 'auto', borderRadius: 10, margin: '14px 0 14px 20px', boxShadow: '0 1px 2px rgba(17,24,39,0.04), 0 1px 3px rgba(17,24,39,0.06)', cursor: 'zoom-in' }} />);
            j = urlEnd + 1; continue;
          }
        }
      }
      // Inline HTML <img ...> — supports the editor's width/data-align attrs
      // when the saved markdown chose HTML over the plain ![](…) form.
      const imgHtml = text.slice(j).match(/^<img\b([^>]*)\/?>/i);
      if (imgHtml) {
        const attrs = imgHtml[1];
        const src = (attrs.match(/\bsrc\s*=\s*"([^"]*)"/i) || attrs.match(/\bsrc\s*=\s*'([^']*)'/i) || [])[1];
        if (src) {
          flush();
          const alt = (attrs.match(/\balt\s*=\s*"([^"]*)"/i) || attrs.match(/\balt\s*=\s*'([^']*)'/i) || [])[1] || '';
          const align = (attrs.match(/\bdata-align\s*=\s*"([^"]*)"/i) || attrs.match(/\bdata-align\s*=\s*'([^']*)'/i) || [])[1];
          const widthCss = (attrs.match(/width\s*:\s*([^;"']+)/i) || [])[1];
          const widthAttr = (attrs.match(/\bwidth\s*=\s*"([^"]*)"/i) || attrs.match(/\bwidth\s*=\s*'([^']*)'/i) || [])[1];
          const w = widthCss || widthAttr;
          // Default left-align with a 20px gutter from the text edge — most
          // screenshots are wider than they are tall and benefit from the
          // breathing room. Explicit `data-align="right"` still right-aligns.
          const margin = align === 'right' ? '14px 0 14px auto' : '14px 0 14px 20px';
          const cappedMaxWidth = align === 'right' ? '100%' : 'calc(100% - 20px)';
          nodes.push(<img key={key++} className="guide-img" src={src} alt={alt} loading="lazy" style={{ display: 'block', maxWidth: cappedMaxWidth, maxHeight: '70vh', width: w || 'auto', height: 'auto', borderRadius: 10, margin, boxShadow: '0 1px 2px rgba(17,24,39,0.04), 0 1px 3px rgba(17,24,39,0.06)', cursor: 'zoom-in' }} />);
          j += imgHtml[0].length; continue;
        }
      }
      if (text.slice(j, j + 2) === '**') {
        const end = text.indexOf('**', j + 2);
        if (end !== -1) { flush(); nodes.push(<strong key={key++}>{inline(text.slice(j + 2, end))}</strong>); j = end + 2; continue; }
      }
      // Strike: ~~text~~
      if (text.slice(j, j + 2) === '~~') {
        const end = text.indexOf('~~', j + 2);
        if (end !== -1) { flush(); nodes.push(<s key={key++} style={{ color: '#888' }}>{inline(text.slice(j + 2, end))}</s>); j = end + 2; continue; }
      }
      if (text[j] === '`') {
        const end = text.indexOf('`', j + 1);
        if (end !== -1) {
          flush();
          nodes.push(<code key={key++} style={{ background: '#F7F4EF', padding: '1px 6px', borderRadius: 4, fontFamily: 'ui-monospace, "SF Mono", Menlo, monospace', fontSize: '0.92em' }}>{text.slice(j + 1, end)}</code>);
          j = end + 1; continue;
        }
      }
      if (text[j] === '*' && text[j + 1] !== '*') {
        const end = text.indexOf('*', j + 1);
        if (end !== -1 && text[end + 1] !== '*') { flush(); nodes.push(<em key={key++}>{text.slice(j + 1, end)}</em>); j = end + 1; continue; }
      }
      // Inline HTML pass-through for <u>, <mark>, <s>, <br>
      const htmlMatch = text.slice(j).match(/^<(u|mark|s|br)\b[^>]*>/i);
      if (htmlMatch) {
        const tag = htmlMatch[1].toLowerCase();
        if (tag === 'br') { flush(); nodes.push(<br key={key++} />); j += htmlMatch[0].length; continue; }
        const closeTag = `</${tag}>`;
        const closeIdx = text.toLowerCase().indexOf(closeTag, j + htmlMatch[0].length);
        if (closeIdx !== -1) {
          flush();
          const inner = text.slice(j + htmlMatch[0].length, closeIdx);
          if (tag === 'u') nodes.push(<u key={key++}>{inline(inner)}</u>);
          else if (tag === 'mark') nodes.push(<mark key={key++} style={{ background: '#FEF3C7', padding: '0 2px', borderRadius: 2 }}>{inline(inner)}</mark>);
          else if (tag === 's') nodes.push(<s key={key++} style={{ color: '#888' }}>{inline(inner)}</s>);
          j = closeIdx + closeTag.length; continue;
        }
      }
      if (text[j] === '[') {
        const close = text.indexOf(']', j);
        if (close !== -1 && text[close + 1] === '(') {
          const urlEnd = text.indexOf(')', close + 2);
          if (urlEnd !== -1) {
            flush();
            const linkText = text.slice(j + 1, close);
            const url = text.slice(close + 2, urlEnd);
            nodes.push(<a key={key++} href={url} target="_blank" rel="noopener noreferrer" style={{ color: '#211E1E', textDecoration: 'underline', fontWeight: 600 }}>{linkText}</a>);
            j = urlEnd + 1; continue;
          }
        }
      }
      buf += text[j];
      j++;
    }
    flush();
    return nodes;
  }

  while (i < lines.length) {
    const line = lines[i];
    if (!line.trim()) { i++; continue; }

    if (line.startsWith('```')) {
      const code = [];
      i++;
      while (i < lines.length && !lines[i].startsWith('```')) { code.push(lines[i]); i++; }
      i++;
      out.push(
        <pre key={key++} style={{
          background: '#211E1E', color: '#FDC831',
          padding: '16px 20px', borderRadius: 8,
          fontSize: 13, lineHeight: 1.5,
          fontFamily: 'ui-monospace, "SF Mono", Menlo, monospace',
          overflowX: 'auto', margin: '0 0 18px',
        }}>{code.join('\n')}</pre>
      );
      continue;
    }

    const h = line.match(/^(#{1,3})\s+(.*)/);
    if (h) {
      const level = h[1].length;
      const isFirstElement = out.length === 0;
      const sizes = { 1: isFirstElement ? 32 : 28, 2: 22, 3: 17 };
      const margins = { 1: '36px 0 14px', 2: '30px 0 12px', 3: '22px 0 10px' };
      const Tag = `h${Math.min(level + 1, 6)}`;
      out.push(
        <Tag key={key++} style={{
          fontFamily: "'Archivo', sans-serif",
          fontSize: sizes[level], fontWeight: level === 1 ? 900 : 800,
          letterSpacing: '-0.015em', color: '#211E1E',
          margin: isFirstElement ? '0 0 12px' : margins[level],
          lineHeight: 1.2,
        }}>{inline(h[2])}</Tag>
      );
      if (isFirstElement && level === 1) {
        out.push(
          <hr key={key++} style={{
            border: 'none', height: 1, background: '#E5E7EB',
            margin: '0 0 24px',
          }} />
        );
      }
      i++;
      continue;
    }

    if (line.startsWith('>')) {
      const quote = [line.replace(/^>\s?/, '')];
      i++;
      while (i < lines.length && lines[i].startsWith('>')) { quote.push(lines[i].replace(/^>\s?/, '')); i++; }
      out.push(
        <blockquote key={key++} style={{
          borderLeft: '4px solid #FDC831',
          paddingLeft: 16, margin: '0 0 18px',
          color: '#4A3F2E', fontStyle: 'italic',
        }}>{inline(quote.join(' '))}</blockquote>
      );
      continue;
    }

    if (line.match(/^[-*]\s+/)) {
      const items = [];
      while (i < lines.length && lines[i].match(/^[-*]\s+/)) { items.push(lines[i].replace(/^[-*]\s+/, '')); i++; }
      out.push(<ul key={key++} style={{ margin: '0 0 18px', paddingLeft: 24 }}>
        {items.map((it, k) => <li key={k} style={{ marginBottom: 6 }}>{inline(it)}</li>)}
      </ul>);
      continue;
    }

    if (line.match(/^\d+\.\s+/)) {
      // Group consecutive numbered items. Be tolerant of blank lines between
      // them — Claude often writes `1.\n\n1.\n\n1.` and we want it to render
      // as ONE list (auto-renumbered 1, 2, 3…), not three lists each starting
      // at 1.
      const items = [];
      while (i < lines.length) {
        const cur = lines[i];
        if (cur.match(/^\d+\.\s+/)) {
          items.push(cur.replace(/^\d+\.\s+/, ''));
          i++;
        } else if (cur.trim() === '') {
          let k = i + 1;
          while (k < lines.length && lines[k].trim() === '') k++;
          if (k < lines.length && lines[k].match(/^\d+\.\s+/)) {
            i = k; // jump past the blank gap, keep the list going
          } else {
            break;
          }
        } else {
          break;
        }
      }
      if (stepStyle === 'cards') {
        // Compact card-style steps for chat answers.
        out.push(<ol key={key++} style={{ listStyle: 'none', padding: 0, margin: '0 0 14px', display: 'block' }}>
          {items.map((it, k) => (
            <li key={k} style={{
              display: 'grid',
              gridTemplateColumns: '28px 1fr',
              gap: 10,
              alignItems: 'start',
              padding: '10px 14px',
              marginBottom: 6,
              background: '#FFFFFF',
              border: '1px solid #211E1E',
              borderRadius: 8,
              boxShadow: '1px 1px 0 #211E1E',
              width: '100%',
              boxSizing: 'border-box',
            }}>
              <div style={{
                width: 22, height: 22, borderRadius: '50%',
                background: '#FDC831', border: '1px solid #211E1E',
                color: '#211E1E',
                display: 'grid', placeItems: 'center',
                fontFamily: "'Archivo', sans-serif",
                fontSize: 11, fontWeight: 800,
                flexShrink: 0,
                marginTop: 1,
              }}>{k + 1}</div>
              <div style={{ fontSize: 14, lineHeight: 1.5, color: '#211E1E', minWidth: 0, wordBreak: 'break-word' }}>
                {inline(it)}
              </div>
            </li>
          ))}
        </ol>);
      } else {
        out.push(<ol key={key++} style={{ margin: '0 0 18px', paddingLeft: 24 }}>
          {items.map((it, k) => <li key={k} style={{ marginBottom: 6 }}>{inline(it)}</li>)}
        </ol>);
      }
      continue;
    }

    const para = [line];
    i++;
    while (i < lines.length && lines[i].trim() && !lines[i].match(/^(#{1,3}\s|>|[-*]\s|\d+\.\s|```)/)) { para.push(lines[i]); i++; }
    out.push(<p key={key++} style={{ margin: '0 0 14px' }}>{inline(para.join(' '))}</p>);
  }

  return out;
}

// Some legacy/seeded guides start their body with `# <Title>` — the admin
// editor now strips that on save so the title is a single source of truth, but
// older rows still have it. Drop it from the body before rendering so the
// title doesn't show up twice on the live page.
function stripLeadingTitleFromBody(body, title) {
  if (!body) return body || '';
  const t = String(title || '').trim();
  if (!t) return body;
  const escaped = t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return body.replace(new RegExp(`^\\s*#\\s+${escaped}\\s*\\n+`, 'i'), '');
}

// Renders a guide body in whichever format it was stored in.
//
// Guides written in the admin's Lexical editor arrive as Lexical EditorState
// JSON; everything authored before that is Markdown. There is no migration and
// no conversion — the column holds both and the renderer branches, which is the
// same mixed-format approach slicedesk uses for its own Lexical columns
// (client/src/components/ui/lexical/lexicalUtils.js:8).
//
// Deliberately NOT converting Lexical→Markdown to reuse renderMarkdown(): that
// path is lossy (tables collapse, embeds vanish, bold/italic is dropped) and
// renderMarkdown() cannot render tables or task lists at all.
function GuideBody({ body, title, onOpenGuide }) {
  // @mentions render as spans carrying data-guide-id. One delegated click
  // handler on the wrapper turns them into navigation — cheaper and more
  // robust than a listener per chip, and it keeps working when the viewer
  // re-renders the tree.
  const onClick = React.useCallback((e) => {
    const chip = e.target.closest?.('.lexical-mention');
    if (!chip) return;
    const id = chip.getAttribute('data-guide-id');
    if (!id || !onOpenGuide) return;
    e.preventDefault();
    onOpenGuide({ id: /^\d+$/.test(id) ? Number(id) : id });
  }, [onOpenGuide]);

  if (isLexicalJson(body)) {
    // stripLeadingTitleFromBody is Markdown-specific (it strips a leading
    // `# Title`). Lexical bodies never carry a duplicated H1 — the admin editor
    // strips it on save — so it is not needed, and applying a regex to JSON
    // would corrupt it.
    return (
      <div className="guide-lexical-body" onClick={onClick}>
        {/* Fallback is a plain block rather than a spinner: the chunk is small
            and usually cached, so a spinner would flash more than it informs. */}
        <React.Suspense fallback={<div style={{ minHeight: 120 }} aria-busy="true" />}>
          <LexicalViewer value={body} />
        </React.Suspense>
      </div>
    );
  }
  return renderMarkdown(stripLeadingTitleFromBody(body, title));
}

// Where the guide's tool icons, back arrow and (once condensed) the title all
// pin. Single source of truth so the three sticky layers cannot drift apart.
const STICKY_TOP = 16;

function GuideExperience({ guide, onClose, onFileTicket, onOpenGuide }) {
  const [body, setBody] = React.useState(null);
  const [title, setTitle] = React.useState(guide?.title || '');
  const [category, setCategory] = React.useState(guide?.category || '');
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState(null);
  const [feedback, setFeedback] = React.useState(null);
  const [related, setRelated] = React.useState([]);
  const [shareCopied, setShareCopied] = React.useState(false);
  // Pinned, the title must hold ONE line: wrapping would grow the sticky
  // header as you scroll. At rest it wraps freely — it is a 32px heading with
  // the full column to use.
  const titleRef = React.useRef(null);
  const [titleStuck, setTitleStuck] = React.useState(false);
  React.useEffect(() => {
    const el = titleRef.current;
    if (!el) return undefined;
    let raf = 0;
    const check = () => { raf = 0; setTitleStuck(el.getBoundingClientRect().top <= STICKY_TOP + 1); };
    const onScroll = () => { if (!raf) raf = requestAnimationFrame(check); };
    check();
    // Capture phase on document, not window: the guide sits in its own
    // overflow-y container and scroll events do not bubble.
    document.addEventListener('scroll', onScroll, { capture: true, passive: true });
    window.addEventListener('resize', onScroll);
    return () => {
      document.removeEventListener('scroll', onScroll, { capture: true });
      window.removeEventListener('resize', onScroll);
      if (raf) cancelAnimationFrame(raf);
    };
  }, [body, title]);

  React.useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    setBody(null);
    setTitle(guide?.title || '');
    setFeedback(null);

    const idStr = String(guide.id ?? '');
    const isDbGuide = /^\d+$/.test(idStr);

    if (isDbGuide) {
      fetch(`/api/guides/${idStr}`)
        .then((r) => (r.ok ? r.json() : Promise.reject(new Error('Guide not found'))))
        .then((g) => {
          if (cancelled) return;
          setBody(g.body);
          // Title lives on the guide row, not in the body — admin's editor
          // strips the leading "# Title" before saving so it's a single source
          // of truth. Pull it from the API response and render it explicitly.
          setTitle(g.title || guide?.title || '');
          setCategory(g.category || guide?.category || '');
          setLoading(false);
        })
        .catch((e) => { if (!cancelled) { setError(e.message); setLoading(false); } });
    } else {
      setError("This guide isn't in the knowledge base yet — file a ticket and we'll add it.");
      setLoading(false);
    }
    return () => { cancelled = true; };
  }, [guide.id]);

  // Pull other guides in the same category for the "try one of these" chips
  // shown when the user marks the guide as not helpful.
  React.useEffect(() => {
    let cancelled = false;
    if (!category) { setRelated([]); return; }
    fetch('/api/guides')
      .then((r) => (r.ok ? r.json() : []))
      .then((all) => {
        if (cancelled) return;
        const cat = String(category).toLowerCase();
        const same = (all || [])
          .filter((g) => g.id !== guide.id && String(g.category || '').toLowerCase() === cat)
          .slice(0, 5);
        setRelated(same);
      })
      .catch(() => { if (!cancelled) setRelated([]); });
    return () => { cancelled = true; };
  }, [category, guide.id]);

  // Guide search in the top bar — jump to any other guide without leaving
  // the reader.
  const [searchQ, setSearchQ] = React.useState("");
  const [searchHover, setSearchHover] = React.useState(false);
  const [searchFocus, setSearchFocus] = React.useState(false);
  const searchInputRef = React.useRef(null);
  // Collapsed to a magnifier by default; expands on hover and stays open
  // while focused or holding a query.
  const searchOpen = searchHover || searchFocus || searchQ.trim() !== "";
  const [allGuides, setAllGuides] = React.useState([]);
  React.useEffect(() => {
    fetch('/api/guides', { credentials: 'include' })
      .then((r) => (r.ok ? r.json() : []))
      .then((rows) => setAllGuides(Array.isArray(rows) ? rows : []))
      .catch(() => {});
  }, []);
  const searchHits = React.useMemo(() => {
    const q = searchQ.trim().toLowerCase();
    if (!q) return [];
    return allGuides
      .filter((g) => String(g.id) !== String(guide.id))
      .filter((g) => (g.title || '').toLowerCase().includes(q) || (g.category || '').toLowerCase().includes(q))
      .slice(0, 8);
  }, [allGuides, searchQ, guide.id]);

  // Pin — the SAME pin list as SliceDesk Docs (user_pinned_docs): pinning
  // here surfaces the guide on the portal home, SliceDesk Docs home,
  // profile, and the Pinned Docs widget.
  const [pinned, setPinned] = React.useState(false);
  React.useEffect(() => {
    let alive = true;
    fetch('/api/guides/pins', { credentials: 'include' })
      .then((r) => (r.ok ? r.json() : []))
      .then((rows) => { if (alive) setPinned((rows || []).some((g) => String(g.id) === String(guide.id))); })
      .catch(() => {});
    return () => { alive = false; };
  }, [guide.id]);
  const togglePin = React.useCallback(async () => {
    const next = !pinned;
    setPinned(next);
    try {
      await fetch(`/api/guides/${encodeURIComponent(guide.id)}/pin`, { method: next ? 'POST' : 'DELETE', credentials: 'include' });
    } catch { setPinned(!next); }
  }, [pinned, guide.id]);

  // Export — same md/html/pdf exports as SliceDesk Docs. Downloads go
  // through fetch (the network shim attaches the hub_token header, which a
  // plain <a href> wouldn't get) then a blob object-URL click.
  const [exportOpen, setExportOpen] = React.useState(false);
  // Close the export menu on any press outside it (pointerdown, not click,
  // so it also closes when the outside press starts a drag or text-select).
  const exportRef = React.useRef(null);
  React.useEffect(() => {
    if (!exportOpen) return;
    const onDown = (e) => {
      if (exportRef.current && !exportRef.current.contains(e.target)) setExportOpen(false);
    };
    document.addEventListener('pointerdown', onDown);
    return () => document.removeEventListener('pointerdown', onDown);
  }, [exportOpen]);
  const exportGuide = React.useCallback(async (fmt) => {
    setExportOpen(false);
    try {
      const r = await fetch(`/api/guides/${encodeURIComponent(guide.id)}/export?format=${fmt}`, { credentials: 'include' });
      if (!r.ok) throw new Error('export failed');
      const blob = await r.blob();
      const cd = r.headers.get('content-disposition') || '';
      const m = cd.match(/filename="([^"]+)"/);
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = m ? m[1] : `guide-${guide.id}.${fmt}`;
      document.body.appendChild(a); a.click(); a.remove();
      setTimeout(() => URL.revokeObjectURL(a.href), 4000);
    } catch {}
  }, [guide.id]);

  const shareLink = React.useCallback(async () => {
    const url = `${window.location.origin}/portal/?guide=${guide.id}`;
    try {
      await navigator.clipboard.writeText(url);
      setShareCopied(true);
      setTimeout(() => setShareCopied(false), 1800);
    } catch {
      // Older browsers / secure-context fallback: dump into a temp textarea
      const ta = document.createElement('textarea');
      ta.value = url;
      ta.style.position = 'fixed'; ta.style.opacity = '0';
      document.body.appendChild(ta); ta.select();
      try { document.execCommand('copy'); setShareCopied(true); setTimeout(() => setShareCopied(false), 1800); } catch {}
      document.body.removeChild(ta);
    }
  }, [guide.id]);

  // Image lightbox — click any guide image to open it fullscreen.
  // Uses event delegation on the article so newly-rendered images Just Work
  // without rewiring listeners every time the markdown re-renders. We also
  // collect every image in the article on click so the lightbox can offer
  // prev/next navigation through them.
  const articleRef = React.useRef(null);
  const [lightbox, setLightbox] = React.useState(null);

  // Escape peels back one layer at a time: export menu first, then (when no
  // lightbox is up — that has its own Escape handling) the guide itself.
  React.useEffect(() => {
    const onKey = (e) => {
      if (e.key !== 'Escape') return;
      if (exportOpen) { setExportOpen(false); return; }
      if (!lightbox) onClose();
    };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [onClose, exportOpen, lightbox]);
  React.useEffect(() => {
    const el = articleRef.current;
    if (!el) return;
    const onClick = (e) => {
      const img = e.target.closest && e.target.closest('img.guide-img');
      if (!img) return;
      e.preventDefault();
      const all = Array.from(el.querySelectorAll('img.guide-img')).map((n) => ({
        src: n.currentSrc || n.src,
        alt: n.alt || '',
      }));
      const idx = Math.max(0, all.findIndex((x) => x.src === (img.currentSrc || img.src)));
      setLightbox({ images: all.length > 0 ? all : [{ src: img.currentSrc || img.src, alt: img.alt || '' }], index: idx });
    };
    el.addEventListener('click', onClick);
    return () => el.removeEventListener('click', onClick);
  }, [body]);

  const sendFeedback = (rating) => {
    if (feedback === rating) return; // already this answer
    setFeedback(rating);
    fetch(`/api/guides/${guide.id}/feedback`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ rating }),
    }).catch(() => {});
  };

  const fbBtn = (active) => ({
    background: active ? '#211E1E' : '#FFFFFF',
    color: active ? '#FDC831' : '#211E1E',
    border: '1px solid #211E1E',
    padding: '12px 22px',
    borderRadius: 8,
    fontWeight: 800,
    fontFamily: "'Archivo', sans-serif",
    fontSize: 14,
    cursor: 'pointer',
    boxShadow: active ? '1px 1px 0 #FDC831' : '1px 1px 0 #211E1E',
  });

  // Square icon button shared by the sticky top-right tools (pin / share /
  // export) and the top-left back arrow. 34px matches the collapsed search;
  // minWidth (not width) lets a button widen to reveal its hover label.
  const toolBtn = (active) => ({
    minWidth: 34, height: 34, padding: '0 8px', flexShrink: 0,
    display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
    background: active ? '#211E1E' : '#FFFFFF',
    color: active ? '#FDC831' : '#211E1E',
    border: '1px solid #211E1E', borderRadius: 8,
    boxShadow: '1px 1px 0 #211E1E', cursor: 'pointer', boxSizing: 'border-box',
  });

  return (
    <div style={{
      position: 'fixed', inset: 0, zIndex: 100,
      background: '#FDC831',
      overflowY: 'auto',
      animation: 'fadeIn .25s var(--ease) both',
      display: 'flex', flexDirection: 'column',
    }}>
      <style>{`
        .back-to-hub-btn,
        .share-guide-btn,
        .feedback-btn,
        .file-ticket-btn {
          transition: transform .15s var(--ease, cubic-bezier(.22,.61,.36,1)),
                      box-shadow .15s var(--ease, cubic-bezier(.22,.61,.36,1));
        }
        .back-to-hub-btn:hover,
        .share-guide-btn:hover,
        .feedback-btn:not(:disabled):hover {
          transform: translate(-2px, -2px);
          box-shadow: 2px 2px 0 #211E1E;
        }
        .back-to-hub-btn:active,
        .share-guide-btn:active,
        .feedback-btn:not(:disabled):active {
          transform: translate(1px, 1px);
          box-shadow: 1px 1px 0 #211E1E;
        }
        .back-to-hub-arrow {
          display: inline-block;
          transition: transform .18s var(--ease, cubic-bezier(.22,.61,.36,1));
        }
        .back-to-hub-btn:hover .back-to-hub-arrow {
          transform: translateX(-4px);
        }
        /* Guide chrome — icon tools grow sideways on hover/focus/open,
           revealing their text label ("Pin", "Copy link", "Export"). The
           cluster is right-anchored, so a growing button only extends toward
           the bar's empty middle: it never retreats from the pointer, and the
           buttons to its right never move. Press sinks into the shadow. */
        .guide-tool, .guide-back {
          transition: transform .16s cubic-bezier(.34,1.56,.64,1),
                      box-shadow .16s var(--ease, cubic-bezier(.22,.61,.36,1)),
                      background .16s ease, color .16s ease;
        }
        .guide-tool:hover, .guide-tool:focus-visible, .guide-tool[aria-expanded="true"] {
          box-shadow: 2px 2px 0 #211E1E; transform: translate(-1px, -1px); z-index: 2;
        }
        .guide-tool:active { transform: translate(1px, 1px); box-shadow: 1px 1px 0 #211E1E; }
        .guide-tool-label {
          display: inline-block; max-width: 0; opacity: 0; margin-left: 0;
          overflow: hidden; white-space: nowrap;
          font-family: 'Archivo', sans-serif; font-size: 12px; font-weight: 800;
          letter-spacing: 0.02em;
          transition: max-width .2s var(--ease, cubic-bezier(.22,.61,.36,1)),
                      opacity .15s ease, margin-left .2s var(--ease, cubic-bezier(.22,.61,.36,1));
        }
        .guide-tool:hover .guide-tool-label,
        .guide-tool:focus-visible .guide-tool-label,
        .guide-tool[aria-expanded="true"] .guide-tool-label {
          max-width: 96px; opacity: 1; margin-left: 7px;
        }
        .guide-menu-item { transition: background .12s ease; }
        .guide-menu-item:hover, .guide-menu-item:focus-visible { background: #FDF3D3; }
        .guide-back:hover { transform: scale(1.10); box-shadow: 2px 2px 0 #211E1E; }
        .guide-back:active { transform: scale(0.92); box-shadow: 1px 1px 0 #211E1E; }
        .guide-back-arrow {
          display: inline-block;
          transition: transform .18s var(--ease, cubic-bezier(.22,.61,.36,1));
        }
        .guide-back:hover .guide-back-arrow { transform: translateX(-3px); }
        .feedback-btn:not(:disabled):hover .feedback-emoji {
          transform: scale(1.18);
        }
        .feedback-emoji {
          display: inline-block;
          transition: transform .18s var(--ease, cubic-bezier(.22,.61,.36,1));
        }
        .file-ticket-btn:hover {
          transform: translateY(-1px);
          filter: brightness(1.08);
        }
        .file-ticket-btn:active {
          transform: translateY(1px);
          filter: brightness(0.95);
        }
      `}</style>
      {/* Top action bar — one white card matching the Tickets detail bar
          (solid white, ink outline, offset shadow). Back on the LEFT, guide
          search in the middle, Pin / Share / Export on the RIGHT. Fixed so
          the article scrolls cleanly under it. */}
      {/* Full-width opaque yellow mask: the article scrolling under the bar
          disappears behind it instead of peeking through the gap above. The
          white card inside is centered at the article text width. */}
      {/* Sticky INSIDE the scroll container (not fixed-to-viewport) so it
          shares the scrollbar context — and it reuses the article's exact
          830px/24px container, so the bar edges align pixel-perfect with
          the article card below. Opaque yellow wrapper masks content
          scrolling under. */}
      <div style={{
        maxWidth: 830, margin: '0 auto', padding: '20px 24px 80px',
        width: '100%', boxSizing: 'border-box',
        flex: '1 0 auto', display: 'flex', flexDirection: 'column',
      }}>
        <article ref={articleRef} style={{
          background: '#FFFFFF',
          border: '1px solid #211E1E',
          borderRadius: 14,
          boxShadow: '3px 3px 0 #211E1E',
          padding: '16px 64px 40px',
          fontSize: 15, lineHeight: 1.65, color: '#211E1E',
          fontFamily: "'Archivo', sans-serif",
          position: 'relative',
        }}>
          {/* Opaque backdrop behind the whole sticky header band (back arrow
              + tools row, y 0–62). The back arrow, search, pin, copy-link,
              and export buttons are each individually opaque, but there's
              no fill in the gaps between/around them — without this, the
              article's own scrolling text shows through those gaps once
              the buttons are pinned in place. Spans edge-to-edge (negative
              inset cancels the article's own padding) with matching corner
              radius so it doesn't square off past the card's rounded top. */}
          <div style={{ position: 'sticky', top: 0, zIndex: 3, height: 0, pointerEvents: 'none' }}>
            <div style={{
              position: 'absolute', top: 0, left: -64, right: -64, height: 62,
              background: '#FFFFFF', borderTopLeftRadius: 13, borderTopRightRadius: 13,
            }} />
          </div>
          {/* Tools — icon-only, parked at the article's top-right corner.
              Deliberately NOT sticky: these scroll away with the article once
              you start reading. Only the back arrow and the title stay pinned,
              so the reading area keeps a single slim header instead of a row of
              icons following you down the page. Zero-height, click-through
              wrapper; only the cluster captures the pointer. Search expands
              leftward on hover. */}
          <div style={{ position: 'relative', zIndex: 5, height: 0, pointerEvents: 'none' }}>
          <div style={{ position: 'absolute', top: 0, right: 16, display: 'flex', justifyContent: 'flex-end', alignItems: 'flex-start' }}>
          <div style={{ display: 'inline-flex', alignItems: 'center', gap: 8, flexShrink: 0, pointerEvents: 'auto' }}>
        {/* Guide search — a magnifying glass that expands on hover (stays
            open while focused / holding a query). Dropdown of matches below. */}
        <div
          onMouseEnter={() => setSearchHover(true)}
          onMouseLeave={() => setSearchHover(false)}
          onClick={() => searchInputRef.current && searchInputRef.current.focus()}
          style={{ position: 'relative', flexShrink: 0, width: 34, height: 34 }}
        >
          {/* Right-anchored overlay: expands LEFT over the bar's empty
              middle so the Pin/Share/Export buttons never move. */}
          <div style={{
            position: 'absolute', top: 0, right: 0, height: 34,
            display: 'flex', alignItems: 'center',
            border: '1px solid #211E1E', borderRadius: 8,
            background: '#FFFFFF', boxSizing: 'border-box',
            boxShadow: '1px 1px 0 #211E1E',
            width: searchOpen ? 'clamp(150px, calc(100vw - 470px), 340px)' : 34,
            transition: 'width .22s cubic-bezier(.22,.61,.36,1)',
            overflow: 'hidden', cursor: searchOpen ? 'text' : 'pointer',
            zIndex: 6,
          }}>
            <input
              ref={searchInputRef}
              value={searchQ}
              onChange={(e) => setSearchQ(e.target.value)}
              onFocus={() => setSearchFocus(true)}
              onBlur={() => setSearchFocus(false)}
              onKeyDown={(e) => { if (e.key === 'Escape') { setSearchQ(''); e.currentTarget.blur(); } }}
              placeholder="Search guides…"
              tabIndex={searchOpen ? 0 : -1}
              style={{
                flex: searchOpen ? 1 : '0 0 0px', minWidth: 0, width: searchOpen ? undefined : 0,
                border: 'none', outline: 'none',
                background: 'transparent', fontSize: 13, fontFamily: 'inherit',
                color: '#211E1E', padding: searchOpen ? '0 0 0 12px' : 0,
              }}
            />
            <span style={{ width: 32, textAlign: 'center', flexShrink: 0, display: 'inline-flex', justifyContent: 'center' }}>
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#211E1E" strokeWidth="2.4" strokeLinecap="round" aria-hidden="true">
                <circle cx="11" cy="11" r="7"/>
                <line x1="21" y1="21" x2="16.5" y2="16.5"/>
              </svg>
            </span>
          </div>
          {searchQ.trim() !== '' && (
            <div style={{
              position: 'absolute', top: '115%', right: 0, width: 'clamp(220px, calc(100vw - 470px), 340px)',
              background: '#FFFFFF', border: '1px solid #211E1E', borderRadius: 8,
              boxShadow: '3px 3px 0 rgba(33,30,30,0.9)', overflow: 'hidden',
              maxHeight: 280, overflowY: 'auto', zIndex: 120,
            }}>
              {searchHits.length === 0 ? (
                <div style={{ padding: '9px 12px', fontSize: 12.5, color: '#78684C', fontWeight: 600 }}>No matching guides.</div>
              ) : searchHits.map((g) => (
                <button key={g.id} className="guide-menu-item"
                  onClick={() => { setSearchQ(''); onOpenGuide && onOpenGuide({ id: g.id, title: g.title, category: g.category }); }}
                  style={{
                    display: 'block', width: '100%', textAlign: 'left',
                    padding: '8px 12px', fontSize: 13, fontFamily: 'inherit',
                    background: 'transparent', border: 'none', cursor: 'pointer', color: '#211E1E',
                  }}>
                  <b style={{ fontFamily: "'Archivo', sans-serif", fontWeight: 800 }}>{g.title}</b>
                  {g.category && <span style={{ color: '#78684C', marginLeft: 8, fontSize: 11.5, fontWeight: 600 }}>{g.category}</span>}
                </button>
              ))}
            </div>
          )}
        </div>
          {/* Pin — same pin list as SliceDesk Docs (home / profile / widget).
              Fills charcoal when pinned. */}
          <button
            className="guide-tool"
            onClick={togglePin}
            aria-label={pinned ? 'Unpin this guide' : 'Pin this guide'}
            aria-pressed={pinned}
            title={pinned ? 'Unpin this guide' : 'Pin this guide to your hub home + SliceDesk profile'}
            style={toolBtn(pinned)}>
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
              <path d="M12 17v5"/>
              <path d="M9 10.76a2 2 0 0 1-1.11 1.79l-1.78.9A2 2 0 0 0 5 15.24V16a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-.76a2 2 0 0 0-1.11-1.79l-1.78-.9A2 2 0 0 1 15 10.76V7a1 1 0 0 1 1-1 2 2 0 0 0 0-4H8a2 2 0 0 0 0 4 1 1 0 0 1 1 1z"/>
            </svg>
            <span className="guide-tool-label" aria-hidden="true">{pinned ? 'Pinned' : 'Pin'}</span>
          </button>

          {/* Copy-link — a check briefly replaces the link icon on success. */}
          <button
            className="guide-tool"
            onClick={shareLink}
            aria-label="Copy link to this guide"
            title={shareCopied ? 'Link copied!' : 'Copy link to this guide'}
            style={toolBtn(shareCopied)}>
            {shareCopied ? (
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                <polyline points="20 6 9 17 4 12"/>
              </svg>
            ) : (
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                <path d="M9 17H7A5 5 0 0 1 7 7h2"/>
                <path d="M15 7h2a5 5 0 1 1 0 10h-2"/>
                <line x1="8" y1="12" x2="16" y2="12"/>
              </svg>
            )}
            <span className="guide-tool-label" aria-hidden="true">{shareCopied ? 'Copied!' : 'Copy link'}</span>
          </button>

          {/* Export — PDF / Markdown / HTML, same engine as SliceDesk Docs. */}
          <div ref={exportRef} style={{ position: 'relative' }}>
            <button
              className="guide-tool"
              onClick={() => setExportOpen((v) => !v)}
              aria-label="Export this guide"
              aria-expanded={exportOpen}
              title="Export this guide"
              style={toolBtn(exportOpen)}>
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/>
                <polyline points="7 10 12 15 17 10"/>
                <line x1="12" y1="15" x2="12" y2="3"/>
              </svg>
              <span className="guide-tool-label" aria-hidden="true">Export</span>
            </button>
            {exportOpen && (
              <div style={{
                position: 'absolute', right: 0, top: '115%', minWidth: 160,
                background: '#FFFFFF', border: '1px solid #211E1E', borderRadius: 8,
                boxShadow: '3px 3px 0 rgba(33,30,30,0.9)', overflow: 'hidden', zIndex: 120,
              }}>
                {[['pdf', 'PDF document'], ['md', 'Markdown (.md)'], ['html', 'HTML file']].map(([f, l]) => (
                  <button key={f} className="guide-menu-item" onClick={() => exportGuide(f)}
                    style={{
                      display: 'block', width: '100%', textAlign: 'left',
                      padding: '9px 14px', fontSize: 13,
                      fontFamily: "'Archivo', sans-serif", fontWeight: 600,
                      background: 'transparent', border: 'none', cursor: 'pointer', color: '#211E1E',
                    }}>
                    {l}
                  </button>
                ))}
              </div>
            )}
          </div>
          </div>
          </div>
          </div>
          {/* Back arrow — sits in line with the four tool icons at rest, but
              unlike them it STAYS pinned as you scroll, so there is always a
              way back without scrolling up. Zero-height, click-through wrapper;
              nudged left of the content into the card's 64px padding. */}
          <div style={{ position: 'sticky', top: STICKY_TOP, zIndex: 5, height: 0, pointerEvents: 'none' }}>
            <button className="guide-back" onClick={onClose} aria-label="Back to Docs" title="Back to Docs" style={{
              ...toolBtn(false), pointerEvents: 'auto',
              position: 'relative', left: -48,
            }}>
              <span className="guide-back-arrow" style={{ display: 'inline-flex' }}>
                <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                  <line x1="19" y1="12" x2="5" y2="12"/>
                  <polyline points="12 19 5 12 12 5"/>
                </svg>
              </span>
            </button>
          </div>
          <div aria-hidden="true" style={{ height: 62 }} />
          {loading && <p style={{ color: '#888', margin: 0 }}>Loading…</p>}
          {error && (
            <div>
              <p style={{ color: '#888', fontStyle: 'italic', margin: '0 0 18px' }}>{error}</p>
              <button onClick={() => onFileTicket && onFileTicket({ source: 'guide', team: 'IT Team' })} style={{
                background: '#211E1E', color: '#FDC831',
                border: 'none', padding: '12px 24px',
                borderRadius: 8, fontWeight: 800,
                fontFamily: 'inherit', fontSize: 14, cursor: 'pointer',
              }}>File a ticket instead</button>
            </div>
          )}
          {/* Title stays put with the toolbar above while the body scrolls
              underneath — top:62 matches the spacer above (the toolbar's
              own reserved height), so it sits exactly where it always has
              at rest and only starts "sticking" once you scroll past it.
              The outer element carries the sticky position + solid white
              background + the 16px gap-after-the-divider as PADDING (not
              margin — a margin sits outside the background box, so a
              margin here would leave a thin unmasked strip the scrolling
              body text stays visible through). The inner span keeps the
              divider line 14px below the text, exactly as before. */}
          {body && title && (
            <h1 ref={titleRef} style={{
              margin: 0, padding: '0 0 16px',
              // Pins at the SAME offset as the back arrow, so the two travel
              // together as one slim header. The four tool icons deliberately
              // do NOT pin — they scroll away with the article.
              position: 'sticky', top: STICKY_TOP,
              zIndex: 4, background: '#FFFFFF',
            }}>
              <span style={{
                display: 'block', fontSize: 32, fontWeight: 900, letterSpacing: '-0.015em',
                lineHeight: 1.2, paddingBottom: 14,
                // Kept visible while pinned: it is the only thing separating
                // the header from the body scrolling underneath.
                borderBottom: '1px solid #E5E7EB', color: '#211E1E',
                // One line once pinned. With the tool icons scrolled away the
                // title has the full 652px column, and a 30-character title at
                // 32px needs ~506px — so this clips in practice only for
                // unusually long titles, where the ellipsis is the safety net.
                whiteSpace: titleStuck ? 'nowrap' : 'normal',
                overflow: 'hidden',
                textOverflow: 'ellipsis',
              }}>{title}</span>
            </h1>
          )}
          {body && <GuideBody body={body} title={title} onOpenGuide={onOpenGuide} />}
        </article>

        {body && (
          <FeedbackPanel
            prompt="Did this resolve it?"
            yesLabel="Yes, fixed"
            noLabel="No, not yet"
            reasons={["Outdated info", "Steps didn't work", "Wrong app or version", "Missing a step", "Not what I asked", "Other"]}
            thanksPositive="Thanks — we'll keep this one current."
            onVote={(rating, details) => {
              sendFeedback(rating);
              if (details && (details.reasons?.length || details.note)) {
                try {
                  fetch(`/api/guides/${guide?.id}/feedback-detail`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ rating, ...details }),
                  });
                } catch {}
              }
            }}
            onFileTicket={(fb) => onFileTicket && onFileTicket({ source: 'guide', team: 'IT Team', guideTitle: title, ...(fb || {}) })}
            relatedGuides={related}
            onOpenGuide={onOpenGuide}
          />
        )}
        {/* The "Built by the Slice IT Team" footer is intentionally absent
            inside a guide: it added 56px of dead space under every article,
            and by that point the reader has already passed the feedback
            panel. Still shown on the other portal screens. */}
      </div>
      {lightbox && (
        <ImageLightbox
          images={lightbox.images}
          index={lightbox.index}
          onClose={() => setLightbox(null)}
        />
      )}
    </div>
  );
}

// Notion-style image lightbox: dim overlay, image centered, click backdrop /
// ✕ / ESC to close. Click image to toggle 1× ↔ 2× zoom. When the article has
// multiple images, ‹ › buttons (and ←/→ keys) cycle through them.
function ImageLightbox({ images, index, onClose }) {
  const [i, setI] = React.useState(index || 0);
  const [zoomed, setZoomed] = React.useState(false);
  const total = images.length;
  const current = images[i] || images[0];

  // Bounded navigation — once you reach the first/last image the arrow on
  // that side disables (no infinite loop). The user found wrap-around
  // confusing because it looked like the same image was opening again.
  const atStart = i <= 0;
  const atEnd = i >= total - 1;
  const prev = React.useCallback(() => {
    setZoomed(false);
    setI((cur) => Math.max(0, cur - 1));
  }, []);
  const next = React.useCallback(() => {
    setZoomed(false);
    setI((cur) => Math.min(total - 1, cur + 1));
  }, [total]);

  React.useEffect(() => {
    const onKey = (e) => {
      if (e.key === 'Escape') onClose();
      else if (e.key === 'ArrowLeft' && total > 1 && !atStart) prev();
      else if (e.key === 'ArrowRight' && total > 1 && !atEnd) next();
    };
    document.addEventListener('keydown', onKey);
    const savedOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => {
      document.removeEventListener('keydown', onKey);
      document.body.style.overflow = savedOverflow;
    };
  }, [onClose, prev, next, total, atStart, atEnd]);

  const navBtn = (side, disabled) => ({
    position: 'fixed',
    top: '50%', transform: 'translateY(-50%)',
    [side]: 18,
    width: 48, height: 48, borderRadius: '50%',
    background: '#FFFFFF', color: '#211E1E',
    border: '1px solid #211E1E',
    boxShadow: '2px 2px 0 rgba(0,0,0,0.45)',
    cursor: disabled ? 'not-allowed' : 'pointer',
    display: 'grid', placeItems: 'center',
    fontSize: 22, fontWeight: 800,
    fontFamily: "'Archivo', sans-serif",
    zIndex: 1010,
    opacity: disabled ? 0.35 : 1,
    pointerEvents: disabled ? 'none' : 'auto',
  });

  return (
    <div
      onClick={onClose}
      style={{
        position: 'fixed', inset: 0, zIndex: 1000,
        background: 'rgba(15, 13, 13, 0.86)',
        backdropFilter: 'blur(4px)',
        WebkitBackdropFilter: 'blur(4px)',
        display: 'grid', placeItems: 'center',
        cursor: 'zoom-out',
        animation: 'fadeIn .18s var(--ease, cubic-bezier(.22,.61,.36,1)) both',
        padding: 40,
      }}
    >
      <img
        key={current.src}
        src={current.src}
        alt={current.alt || ''}
        onClick={(e) => { e.stopPropagation(); setZoomed((z) => !z); }}
        style={{
          maxWidth: zoomed ? '180vw' : '92vw',
          maxHeight: zoomed ? '180vh' : '90vh',
          borderRadius: 8,
          boxShadow: '0 20px 60px rgba(0,0,0,0.55), 0 0 0 1px rgba(255,255,255,0.06)',
          cursor: zoomed ? 'zoom-out' : 'zoom-in',
          transition: 'max-width .25s var(--ease, cubic-bezier(.22,.61,.36,1)), max-height .25s var(--ease, cubic-bezier(.22,.61,.36,1))',
          userSelect: 'none',
          animation: 'fadeIn .18s var(--ease, cubic-bezier(.22,.61,.36,1)) both',
        }}
      />

      {total > 1 && (
        <>
          <button onClick={(e) => { e.stopPropagation(); if (!atStart) prev(); }} aria-label="Previous image" disabled={atStart} style={navBtn('left', atStart)}>‹</button>
          <button onClick={(e) => { e.stopPropagation(); if (!atEnd) next(); }} aria-label="Next image" disabled={atEnd} style={navBtn('right', atEnd)}>›</button>
        </>
      )}

      <button
        onClick={onClose}
        aria-label="Close"
        style={{
          position: 'fixed', top: 22, right: 22,
          width: 40, height: 40, borderRadius: '50%',
          background: '#FFFFFF', color: '#211E1E',
          border: '1px solid #211E1E',
          boxShadow: '2px 2px 0 rgba(0,0,0,0.4)',
          cursor: 'pointer',
          display: 'grid', placeItems: 'center',
          fontSize: 16, fontWeight: 800,
          fontFamily: "'Archivo', sans-serif",
        }}
      >✕</button>

      {(current.alt || total > 1) && (
        <div style={{
          position: 'fixed', bottom: 24, left: '50%', transform: 'translateX(-50%)',
          maxWidth: 'calc(100vw - 40px)',
          padding: '8px 14px',
          background: 'rgba(0,0,0,0.55)',
          color: '#FFFFFF',
          fontFamily: "'Archivo', sans-serif",
          fontSize: 13, fontWeight: 500,
          borderRadius: 8,
          textAlign: 'center',
          backdropFilter: 'blur(8px)',
          WebkitBackdropFilter: 'blur(8px)',
          display: 'flex', alignItems: 'center', gap: 12,
        }}>
          {current.alt && <span>{current.alt}</span>}
          {total > 1 && (
            <span style={{
              fontWeight: 700, fontSize: 12, letterSpacing: '0.04em',
              color: '#FDC831',
            }}>{i + 1} / {total}</span>
          )}
        </div>
      )}
    </div>
  );
}


// ====================================================================
// FeedbackPanel — shared "Did this help?" surface used by guides + search.
// Three states: idle (Y/N), positive (thank-you), negative (reasons +
// optional note + file-ticket CTA). Reasons help us aggregate why a guide
// or search result fell short without forcing users to write paragraphs.
// ====================================================================
function FeedbackPanel({
  prompt = "Did this resolve it?",
  yesLabel = "Yes, fixed",
  noLabel = "No, not yet",
  reasons = ["Outdated info", "Steps didn't work", "Wrong app or version", "Not what I asked", "Other"],
  thanksPositive = "Thanks — we'll keep this one current.",
  onVote,
  onFileTicket,
  // Related guides surfaced when the user says "no, not yet" — gives them a
  // fast escape hatch to a similar guide before they have to open a ticket.
  // Shape: [{ id, title, category }]
  relatedGuides = [],
  onOpenGuide,
}) {
  const [state, setState] = React.useState("idle");
  const [picked, setPicked] = React.useState(new Set());
  const [note, setNote] = React.useState("");

  const togglePick = (r) => setPicked((prev) => {
    const next = new Set(prev);
    if (next.has(r)) next.delete(r); else next.add(r);
    return next;
  });
  // Allow flipping the answer BEFORE submitting — once 'sent', it's locked.
  const handleYes = () => {
    if (state === "sent") return;
    if (state === "positive") return; // already there
    setState("positive");
    setPicked(new Set()); setNote(""); // reset any negative-path drafts
    onVote && onVote(1);
  };
  const handleNo = () => {
    if (state === "sent") return;
    if (state === "negative") return; // already there
    setState("negative");
    onVote && onVote(-1);
  };
  const submitDetails = () => {
    onVote && onVote(-1, { reasons: [...picked], note: note.trim() });
    setState("sent");
  };

  return (
    <div className="feedback-panel" style={{
      marginTop: 28, padding: "20px 24px",
      background: "#FFFFFF",
      border: "1px solid #211E1E",
      borderRadius: 14,
      boxShadow: "2px 2px 0 #211E1E, 0 4px 14px rgba(33,30,30,0.06)",
    }}>
      <style>{`
        .fb-btn {
          display: inline-flex; align-items: center; gap: 8px;
          padding: 10px 18px;
          background: #FFFFFF; color: #211E1E;
          border: 1px solid #211E1E; border-radius: 8px;
          box-shadow: 1px 1px 0 #211E1E, 0 2px 6px rgba(33,30,30,0.05);
          font-family: 'Archivo', sans-serif;
          font-weight: 800; font-size: 13.5px;
          cursor: pointer;
          transition: transform .2s cubic-bezier(.34, 1.56, .64, 1), box-shadow .2s ease, background .18s ease;
        }
        .fb-btn:disabled { cursor: default; box-shadow: 1px 1px 0 #211E1E; opacity: 0.85; }
        /* Default hover only applies to NON-active buttons. The active states
           have their own hover rules below so their text doesn't go white-on-
           white when the user re-hovers their selection. */
        .fb-btn:not(:disabled):not(.is-yes-on):not(.is-no-on):hover {
          transform: translate(-2px,-2px);
          background: #FFF9E6;
          box-shadow: 2px 2px 0 #211E1E, 0 8px 18px rgba(33,30,30,0.12);
        }
        .fb-btn:not(:disabled):active {
          transform: translate(1px,1px);
          box-shadow: 1px 1px 0 #211E1E;
          transition-duration: .08s;
        }
        .fb-btn .fb-emoji {
          font-size: 16px;
          transition: transform .25s cubic-bezier(.34, 1.56, .64, 1);
          display: inline-block;
        }
        .fb-btn:not(:disabled):hover .fb-emoji { transform: scale(1.30) rotate(-6deg); }

        /* Active states — both have explicit hover rules so the dark fill +
           bright text combination stays intact when re-hovered. */
        .fb-btn.is-yes-on { background: #211E1E; color: #FDC831; box-shadow: 1px 1px 0 #FDC831; opacity: 1; }
        .fb-btn.is-yes-on:not(:disabled):hover {
          background: #000000; color: #FDC831;
          transform: translate(-2px,-2px);
          box-shadow: 2px 2px 0 #FDC831, 0 8px 18px rgba(33,30,30,0.18);
        }
        .fb-btn.is-no-on  { background: #B92323; color: #FFFFFF; box-shadow: 1px 1px 0 #211E1E; opacity: 1; }
        .fb-btn.is-no-on:not(:disabled):hover {
          background: #D32D2D; color: #FFFFFF;
          transform: translate(-2px,-2px);
          box-shadow: 2px 2px 0 #211E1E, 0 8px 18px rgba(185,35,35,0.22);
        }

        .fb-reason {
          padding: 6px 12px;
          background: #FFFFFF; color: #211E1E;
          border: 1px solid #211E1E; border-radius: 999px;
          box-shadow: 1px 1px 0 #211E1E;
          font-family: 'Archivo', sans-serif;
          font-size: 12px; font-weight: 700;
          cursor: pointer;
          transition: transform .18s cubic-bezier(.34, 1.56, .64, 1), box-shadow .18s ease, background .18s ease, color .18s ease;
        }
        .fb-reason:hover {
          transform: translate(-1.5px,-1.5px);
          background: #FFF9E6;
          box-shadow: 3.5px 3.5px 0 #211E1E;
        }
        .fb-reason.is-on { background: #211E1E; color: #FDC831; box-shadow: 1px 1px 0 #FDC831; }
        .fb-reason.is-on:hover { box-shadow: 3.5px 3.5px 0 #FDC831; }
        .fb-textarea {
          width: 100%;
          padding: 10px 12px;
          background: #FFFFFF;
          border: 1px solid #211E1E;
          border-radius: 8px;
          font-family: 'Archivo', sans-serif;
          font-size: 13.5px; color: #211E1E;
          resize: vertical; min-height: 64px;
          box-shadow: 1px 1px 0 #211E1E;
          outline: none; box-sizing: border-box;
          transition: box-shadow .15s ease;
        }
        .fb-textarea:focus { box-shadow: 2px 2px 0 #FDC831, 0 0 0 3px rgba(253,200,49,0.25); }
        .fb-submit {
          padding: 10px 22px;
          background: #211E1E; color: #FFFFFF;
          border: 1px solid #211E1E; border-radius: 8px;
          box-shadow: 2px 2px 0 #FDC831, 0 4px 10px rgba(33,30,30,0.10);
          font-family: 'Archivo', sans-serif;
          font-weight: 800; font-size: 13.5px;
          letter-spacing: 0.04em; text-transform: uppercase;
          cursor: pointer;
          transition: transform .18s cubic-bezier(.34, 1.56, .64, 1), box-shadow .18s ease, background .18s ease;
        }
        .fb-submit:hover {
          transform: translate(-2px,-2px);
          background: #000;
          box-shadow: 3px 3px 0 #FDC831, 0 10px 20px rgba(33,30,30,0.16);
        }
        .fb-submit:active { transform: translate(1px,1px); box-shadow: 1px 1px 0 #FDC831; transition-duration: .08s; }
        .fb-ticket {
          padding: 10px 22px;
          background: #B92323; color: #FFFFFF;
          border: 1px solid #211E1E; border-radius: 8px;
          box-shadow: 2px 2px 0 #211E1E, 0 4px 10px rgba(185,35,35,0.16);
          font-family: 'Archivo', sans-serif;
          font-weight: 800; font-size: 13.5px;
          letter-spacing: 0.04em; text-transform: uppercase;
          cursor: pointer;
          transition: transform .18s cubic-bezier(.34, 1.56, .64, 1), box-shadow .18s ease, background .18s ease;
        }
        .fb-ticket:hover {
          transform: translate(-2px,-2px);
          background: #D32D2D;
          box-shadow: 3px 3px 0 #211E1E, 0 10px 20px rgba(185,35,35,0.22);
        }
        .fb-ticket:active { transform: translate(1px,1px); box-shadow: 1px 1px 0 #211E1E; transition-duration: .08s; }
        @keyframes fbSlide {
          from { opacity: 0; transform: translateY(-6px); }
          to   { opacity: 1; transform: translateY(0);    }
        }
        /* No max-height / overflow:hidden — those clipped the bottom buttons.
           Pure opacity + translate animation slides the panel in cleanly. */
        .fb-expand { animation: fbSlide .25s cubic-bezier(.22,.61,.36,1) both; }
        .fb-related {
          display: inline-flex; align-items: center;
          padding: 8px 14px;
          background: #FFF9E6; color: #211E1E;
          border: 1px solid #211E1E; border-radius: 999px;
          box-shadow: 1px 1px 0 #211E1E;
          font-family: 'Archivo', sans-serif;
          font-size: 12.5px; font-weight: 700;
          cursor: pointer;
          max-width: 100%;
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
          transition: transform .18s cubic-bezier(.34, 1.56, .64, 1), box-shadow .18s ease, background .18s ease;
        }
        .fb-related:hover {
          transform: translate(-2px,-2px);
          background: #FDC831;
          box-shadow: 2px 2px 0 #211E1E;
        }
        .fb-related:active {
          transform: translate(1px,1px);
          box-shadow: 1px 1px 0 #211E1E;
          transition-duration: .08s;
        }
      `}</style>

      <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
        <span style={{
          fontWeight: 800, fontSize: 15, fontFamily: "'Archivo', sans-serif",
          color: "#211E1E", letterSpacing: "-0.005em",
        }}>{prompt}</span>
        {state === "positive" && (
          <span style={{
            color: "#0A6B30", fontWeight: 700, fontSize: 13.5,
            display: "inline-flex", alignItems: "center", gap: 6,
            fontFamily: "'Archivo', sans-serif",
          }}>
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
              <polyline points="20 6 9 17 4 12"/>
            </svg>
            {thanksPositive}
          </span>
        )}
        <button className={"fb-btn" + (state === "positive" ? " is-yes-on" : "")}
          disabled={state === "sent"}
          onClick={handleYes}
          style={{ marginLeft: "auto" }}>
          <span className="fb-emoji">👍</span> {yesLabel}
        </button>
        <button className={"fb-btn" + (state === "negative" || state === "sent" ? " is-no-on" : "")}
          disabled={state === "sent"}
          onClick={handleNo}>
          <span className="fb-emoji">👎</span> {noLabel}
        </button>
      </div>

      {state === "negative" && (
        <div className="fb-expand" style={{ marginTop: 18, paddingTop: 18, borderTop: "1px dashed rgba(33,30,30,0.18)" }}>
          {relatedGuides && relatedGuides.length > 0 && onOpenGuide && (
            <div style={{ marginBottom: 16 }}>
              <div style={{
                fontFamily: "'Archivo', sans-serif",
                fontSize: 10.5, fontWeight: 900, letterSpacing: "0.08em",
                textTransform: "uppercase", color: "#78684C", marginBottom: 8,
              }}>Try one of these instead</div>
              <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
                {relatedGuides.slice(0, 5).map((g) => (
                  <button
                    key={g.id}
                    type="button"
                    className="fb-related"
                    onClick={() => onOpenGuide(g)}
                  >
                    <span style={{ fontWeight: 800 }}>{g.title}</span>
                    <span aria-hidden style={{ marginLeft: 6, opacity: 0.7 }}>→</span>
                  </button>
                ))}
              </div>
            </div>
          )}
          <div style={{ marginBottom: 14 }}>
            <div style={{
              fontFamily: "'Archivo', sans-serif",
              fontSize: 14.5, fontWeight: 800, color: "#211E1E",
              marginBottom: 4, letterSpacing: "-0.005em",
            }}>Sorry this didn't fix it.</div>
            <div style={{ fontSize: 13, color: "#4A3F2E", lineHeight: 1.5 }}>
              Pick what was off so we can sharpen the guide — or just file a ticket and someone will follow up.
            </div>
          </div>

          <div style={{ marginBottom: 14 }}>
            <div style={{
              fontFamily: "'Archivo', sans-serif",
              fontSize: 10.5, fontWeight: 900, letterSpacing: "0.08em",
              textTransform: "uppercase", color: "#78684C", marginBottom: 8,
            }}>What was off? <span style={{ fontWeight: 600, opacity: 0.7 }}>(optional · multi-select)</span></div>
            <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
              {reasons.map((r) => (
                <button key={r} type="button"
                  className={"fb-reason" + (picked.has(r) ? " is-on" : "")}
                  onClick={() => togglePick(r)}>
                  {r}
                </button>
              ))}
            </div>
          </div>

          <div style={{ marginBottom: 16 }}>
            <div style={{
              fontFamily: "'Archivo', sans-serif",
              fontSize: 10.5, fontWeight: 900, letterSpacing: "0.08em",
              textTransform: "uppercase", color: "#78684C", marginBottom: 8,
            }}>Anything else? <span style={{ fontWeight: 600, opacity: 0.7 }}>(optional)</span></div>
            <textarea className="fb-textarea" value={note} onChange={(e) => setNote(e.target.value)}
              placeholder="What were you trying to do? What happened instead?" rows={3} />
          </div>

          <div style={{ display: "flex", flexWrap: "wrap", gap: 10, alignItems: "center" }}>
            <button type="button" className="fb-submit" onClick={submitDetails}>Send feedback</button>
            <button type="button" className="fb-ticket"
              onClick={() => { submitDetails(); onFileTicket && onFileTicket({ reasons: [...picked], note: note.trim() }); }}>
              File a ticket →
            </button>
            <span style={{
              fontSize: 11.5, color: "#78684C", fontWeight: 600,
              fontFamily: "'Archivo', sans-serif", marginLeft: "auto",
            }}>Your feedback shapes the next iteration.</span>
          </div>
        </div>
      )}

      {state === "sent" && (
        <div className="fb-expand" style={{
          marginTop: 18, paddingTop: 18,
          borderTop: "1px dashed rgba(33,30,30,0.18)",
          display: "flex", alignItems: "center", gap: 10,
        }}>
          <div style={{
            width: 28, height: 28, borderRadius: "50%",
            background: "#0A8A3E", color: "#FFFFFF",
            display: "grid", placeItems: "center", flexShrink: 0,
          }}>
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
              <polyline points="20 6 9 17 4 12"/>
            </svg>
          </div>
          <div style={{ flex: 1 }}>
            <div style={{ fontFamily: "'Archivo', sans-serif", fontWeight: 800, fontSize: 14, color: "#211E1E" }}>Thanks — we got it.</div>
            <div style={{ fontSize: 12.5, color: "#4A3F2E", lineHeight: 1.4 }}>
              We review every piece of feedback weekly. {picked.size > 0 ? `Tagged: ${[...picked].join(", ")}.` : ""}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// ====================================================================
//  SearchResults — page shown after a free-text search from Landing.
//  Uses /api/chat retrieval and renders the matched guides as cards
//  (plus the LLM answer when Claude is configured).
// ====================================================================

// Pick an icon for a guide based on its category. Falls back to IconBook
// when the category doesn't match any of the buckets we know about.
function categoryIconFor(category) {
  const c = String(category || '').toLowerCase();
  if (/(password|account|access|identity|sso|login|mfa|onelogin|2fa|auth)/.test(c)) return IconLock;
  if (/(network|wi-?fi|wifi|vpn|internet|globalprotect)/.test(c)) return IconWifi;
  if (/(headphone|jabra|audio|sound|peripheral|monitor|display|keyboard|mouse|charger|cable|hardware|laptop|mac|windows|device)/.test(c)) return IconLaptop;
  if (/(meeting|zoom|meet|video|call|webex|teams|conferenc)/.test(c)) return IconStatus;
  if (/(email|mail|gmail|inbox|calendar|outlook)/.test(c)) return IconMail;
  if (/(slack|chat|message|comm)/.test(c)) return IconSlack;
  if (/(print|printer)/.test(c)) return IconPrinter;
  if (/(onboard|offboard|new hire|hire)/.test(c)) return IconPerson;
  if (/(security|shield|policy|compliance|phish|virus)/.test(c)) return IconShield;
  if (/(database|salesforce|amazon connect|ccp|crm)/.test(c)) return IconDatabase;
  if (/(plug|power)/.test(c)) return IconPlug;
  if (/(performance|slow|maintenance|storage|disk|memory)/.test(c)) return IconBolt;
  if (/(ticket|support|request)/.test(c)) return IconTicket;
  return IconBook;
}

function HubSearchResults({ query, citations, suggestions = [], answer, mode, chatLogId, loading, onBack, onOpenGuide, onFileTicket }) {
  const [feedback, setFeedback] = React.useState(null);
  const sendFeedback = (rating) => {
    setFeedback(rating);
    if (chatLogId) {
      fetch(`/api/chat/${chatLogId}/feedback`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ rating }),
      }).catch(() => {});
    }
  };

  return (
    <div className="page" style={{
      background: '#FDC831',
      display: 'flex', flexDirection: 'column',
    }}>
      <style>{`
        .search-back-btn,
        .search-card,
        .search-fb-btn {
          transition: transform .15s var(--ease, cubic-bezier(.22,.61,.36,1)),
                      box-shadow .15s var(--ease, cubic-bezier(.22,.61,.36,1));
        }
        .search-back-btn:hover {
          transform: translate(-2px, -2px);
          box-shadow: 2px 2px 0 #211E1E;
        }
        .search-back-btn:hover .search-back-arrow { transform: translateX(-4px); }
        .search-back-arrow {
          display: inline-block;
          transition: transform .18s var(--ease, cubic-bezier(.22,.61,.36,1));
        }
        .search-card:hover {
          transform: translate(-2px, -2px);
          box-shadow: 4px 4px 0 #211E1E;
        }
        .search-card:active {
          transform: translate(1px, 1px);
          box-shadow: 2px 2px 0 #211E1E;
        }
        .search-card .card-arrow {
          transition: transform .2s var(--ease, cubic-bezier(.22,.61,.36,1)), opacity .2s;
          opacity: 0.55;
        }
        .search-card:hover .card-arrow {
          transform: translateX(5px);
          opacity: 1;
        }
        .search-card .card-icon {
          transition: transform .2s var(--ease, cubic-bezier(.22,.61,.36,1));
        }
        .search-card:hover .card-icon {
          transform: rotate(-3deg) scale(1.05);
        }
        .search-fb-btn:not(:disabled):hover {
          transform: translate(-2px, -2px);
          box-shadow: 2px 2px 0 #211E1E;
        }
        .search-fb-btn:not(:disabled):active {
          transform: translate(1px, 1px);
          box-shadow: 1px 1px 0 #211E1E;
        }
        .search-ticket-btn {
          transition: transform .15s var(--ease, cubic-bezier(.22,.61,.36,1)),
                      box-shadow .15s var(--ease, cubic-bezier(.22,.61,.36,1));
        }
        .search-ticket-btn:hover {
          transform: translate(-2px, -2px);
          box-shadow: 5px 5px 0 #211E1E;
        }
        .search-ticket-btn:active {
          transform: translate(1px, 1px);
          box-shadow: 2px 2px 0 #211E1E;
        }
        .search-ticket-btn svg {
          transition: transform .2s var(--ease, cubic-bezier(.22,.61,.36,1));
        }
        .search-ticket-btn:hover svg {
          transform: translateX(3px) rotate(-6deg);
        }
      `}</style>

      <button className="search-back-btn" onClick={onBack} style={{
        position: 'fixed', top: 20, left: 20, zIndex: 110,
        background: '#FFFFFF',
        border: '1px solid #211E1E',
        borderRadius: 8,
        padding: '8px 14px',
        fontFamily: "'Archivo', sans-serif",
        fontSize: 13, fontWeight: 700,
        color: '#211E1E',
        cursor: 'pointer',
        display: 'inline-flex', alignItems: 'center', gap: 8,
        boxShadow: '1px 1px 0 #211E1E',
      }}>
        <span className="search-back-arrow">←</span>
        Back to hub
      </button>

      <div style={{
        maxWidth: 920, boxSizing: 'content-box', margin: '0 auto', padding: '32px 32px 80px',
        width: '100%',
        flex: '1 0 auto', display: 'flex', flexDirection: 'column',
      }}>
        <div style={{
          fontFamily: "'Archivo', sans-serif",
          fontSize: 11, fontWeight: 900, letterSpacing: '0.08em',
          textTransform: 'uppercase', color: '#4A3F2E', marginBottom: 8,
        }}>
          Results for
        </div>
        <h1 style={{
          fontFamily: "'Archivo', sans-serif",
          fontSize: 40, fontWeight: 900, letterSpacing: '-0.025em',
          margin: '0 0 32px', color: '#211E1E', lineHeight: 1.1,
        }}>
          "{query}"
        </h1>

        {loading && (
          <div>
            <div style={{
              background: '#FFFFFF', border: '1px solid #211E1E', borderRadius: 14,
              padding: '24px 28px', boxShadow: '2px 2px 0 #211E1E',
              display: 'flex', alignItems: 'center', gap: 14,
            }}>
              <div style={{
                width: 28, height: 28, borderRadius: '50%',
                background: '#FDC831', color: '#211E1E',
                display: 'grid', placeItems: 'center', flexShrink: 0,
                fontSize: 11, fontWeight: 900,
                fontFamily: "'Archivo', sans-serif",
                border: '1px solid #211E1E',
                animation: 'pizzaPulse 1.4s ease-in-out infinite',
              }}>S</div>
              <TypingDots />
              <LoadingPatter
                messages={[
                  'Slicing through the knowledge base…',
                  'Pulling matching guides from the oven…',
                  'Picking the freshest answers…',
                  'Plating it up — almost there…',
                ]}
              />
            </div>
            <TipCard />
          </div>
        )}

        {!loading && answer && (() => {
          // Split off the "Still stuck? … Support" trailer so it can render
          // right-aligned as a button rather than as another paragraph in
          // the body. Server always emits the canonical line; we match it
          // generously in case the model paraphrased.
          const m = answer.match(/(.*?)(\n+\s*(?:>\s*)?_?Still stuck\?[^\n]*?https:\/\/it\.slicelife\.com[^\n]*_?\s*)$/is);
          const mainText = m ? m[1].trimEnd() : answer;
          const hasTrailer = !!m;
          return (
            <div style={{
              background: '#FFF9E6', border: '1px solid #211E1E', borderRadius: 14,
              padding: '22px 26px', boxShadow: '2px 2px 0 #211E1E', marginBottom: 28,
            }}>
              <div style={{
                display: 'flex', alignItems: 'center', gap: 10, marginBottom: 12,
              }}>
                <div style={{
                  width: 26, height: 26, borderRadius: '50%',
                  background: '#FDC831', border: '1px solid #211E1E',
                  display: 'grid', placeItems: 'center',
                  fontFamily: "'Archivo', sans-serif",
                  fontSize: 11, fontWeight: 900, color: '#211E1E',
                  flexShrink: 0,
                }}>S</div>
                <div style={{
                  fontFamily: "'Archivo', sans-serif",
                  fontSize: 11, fontWeight: 900, letterSpacing: '0.08em',
                  textTransform: 'uppercase', color: '#4A3F2E',
                }}>Slice IT · here's what to try</div>
              </div>
              <div style={{ fontSize: 14.5, lineHeight: 1.55, color: '#211E1E' }}>
                {renderMarkdown(mainText, { stepStyle: 'cards' })}
              </div>
              <div style={{
                marginTop: 16, paddingTop: 16,
                borderTop: '1px dashed rgba(33,30,30,0.20)',
                display: 'flex', alignItems: 'center', gap: 12, flexWrap: 'wrap',
              }}>
                <span style={{
                  fontSize: 13, color: '#4A3F2E', fontWeight: 600,
                  fontFamily: "'Archivo', sans-serif",
                }}>
                  Still stuck? We'll file a ticket with everything from this chat.
                </span>
                <button
                  className="search-ticket-btn"
                  onClick={() => onFileTicket && onFileTicket({ source: 'answer' })}
                  style={{
                    marginLeft: 'auto',
                    display: 'inline-flex', alignItems: 'center', gap: 8,
                    padding: '11px 20px',
                    background: '#211E1E', color: '#FDC831',
                    border: '1px solid #211E1E', borderRadius: 8,
                    boxShadow: '3px 3px 0 #211E1E', cursor: 'pointer',
                    fontFamily: "'Archivo', sans-serif", fontWeight: 800, fontSize: 13.5,
                    letterSpacing: '0.02em',
                  }}>
                  <IconTicket size={16} stroke={2} /> Submit a ticket
                </button>
              </div>
            </div>
          );
        })()}

        {!loading && citations.length > 0 && (
          <>
            <div style={{
              fontFamily: "'Archivo', sans-serif",
              fontSize: 11, fontWeight: 900, letterSpacing: '0.08em',
              textTransform: 'uppercase', color: '#4A3F2E', marginBottom: 12,
            }}>Top matching guides</div>
            <div style={{ display: 'grid', gap: 14, marginBottom: 28 }}>
              {citations.map((c, i) => {
                const Icon = categoryIconFor(c.category);
                return (
                  <button
                    key={c.chunk_id ?? c.guide_id ?? i}
                    className="search-card"
                    onClick={() => onOpenGuide && onOpenGuide({ id: c.guide_id, title: c.title, category: c.category })}
                    style={{
                      textAlign: 'left',
                      background: '#FFFFFF',
                      border: '1px solid #211E1E',
                      borderRadius: 14,
                      padding: '20px 22px',
                      boxShadow: '3px 3px 0 #211E1E',
                      cursor: 'pointer',
                      fontFamily: "'Archivo', sans-serif",
                      color: '#211E1E',
                      display: 'grid',
                      gridTemplateColumns: '44px 1fr 24px',
                      gap: 16,
                      alignItems: 'flex-start',
                    }}
                  >
                    <div className="card-icon" style={{
                      width: 40, height: 40, borderRadius: 10,
                      background: '#FDC831', border: '1px solid #211E1E',
                      display: 'grid', placeItems: 'center', flexShrink: 0,
                      marginTop: 2,
                    }}>
                      <Icon size={20} stroke={2} />
                    </div>
                    <div style={{ minWidth: 0 }}>
                      {c.category && (
                        <div style={{
                          fontSize: 10.5, fontWeight: 800, letterSpacing: '0.08em',
                          textTransform: 'uppercase', color: '#78684C', marginBottom: 4,
                        }}>{c.category}</div>
                      )}
                      <div style={{
                        fontSize: 18, fontWeight: 800, letterSpacing: '-0.012em',
                        marginBottom: c.content_preview ? 6 : 0, lineHeight: 1.25,
                      }}>{c.title}</div>
                      {c.content_preview && (
                        <div style={{
                          fontSize: 13.5, color: '#4A3F2E', lineHeight: 1.55,
                          display: '-webkit-box',
                          WebkitLineClamp: 3,
                          WebkitBoxOrient: 'vertical',
                          overflow: 'hidden',
                        }}>{c.content_preview}</div>
                      )}
                    </div>
                    <div className="card-arrow" style={{
                      alignSelf: 'center',
                      display: 'grid', placeItems: 'center',
                      width: 24, height: 24,
                      flexShrink: 0,
                      color: '#211E1E',
                    }}>
                      <IconArrow size={18} stroke={2.4} />
                    </div>
                  </button>
                );
              })}
            </div>
          </>
        )}

        {!loading && suggestions && suggestions.length > 0 && (
          <div style={{
            background: '#FFFFFF', border: '1px solid #211E1E', borderRadius: 14,
            padding: '20px 22px', boxShadow: '2px 2px 0 #211E1E', marginBottom: 28,
          }}>
            <div style={{
              fontFamily: "'Archivo', sans-serif",
              fontSize: 11, fontWeight: 900,
              letterSpacing: '0.08em', textTransform: 'uppercase',
              color: '#4A3F2E', marginBottom: 8,
            }}>
              ✨ Did you mean…?
            </div>
            <div style={{ fontSize: 13, color: '#4A3F2E', marginBottom: 14, lineHeight: 1.5 }}>
              {citations.length === 0
                ? "We didn't find a direct guide for that, but these might still help:"
                : "Other guides that might be useful here:"}
            </div>
            <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
              {suggestions.map((s, i) => (
                <li key={i} style={{
                  marginBottom: i < suggestions.length - 1 ? 12 : 0,
                  paddingBottom: i < suggestions.length - 1 ? 12 : 0,
                  borderBottom: i < suggestions.length - 1 ? '1px dashed rgba(33,30,30,0.12)' : 'none',
                }}>
                  <button
                    onClick={() => onOpenGuide && onOpenGuide({ id: s.guide_id, title: s.title, category: s.category })}
                    style={{
                      background: 'transparent', border: 'none', padding: 0,
                      cursor: 'pointer', textAlign: 'left', width: '100%',
                      fontFamily: 'inherit',
                    }}>
                    <div style={{
                      fontSize: 14.5, fontWeight: 700, color: '#211E1E',
                      textDecoration: 'underline', textUnderlineOffset: 3,
                      marginBottom: 4,
                    }}>{s.title}</div>
                    <div style={{ fontSize: 12.5, color: '#4A3F2E', lineHeight: 1.5 }}>
                      {s.reason}
                    </div>
                  </button>
                </li>
              ))}
            </ul>
          </div>
        )}

        {!loading && citations.length === 0 && (!suggestions || suggestions.length === 0) && (
          <div style={{
            background: '#FFFFFF', border: '1px solid #211E1E', borderRadius: 14,
            padding: '24px 28px', boxShadow: '2px 2px 0 #211E1E', marginBottom: 28,
          }}>
            <div style={{ fontSize: 16, fontWeight: 700, marginBottom: 6 }}>No matching guides yet.</div>
            <div style={{ fontSize: 13, color: '#4A3F2E', marginBottom: 14 }}>
              Either the knowledge base doesn't cover this topic yet, or try rephrasing. You can also file a ticket so IT can both fix your issue and add a guide.
            </div>
            <button onClick={() => onFileTicket && onFileTicket({ source: 'search' })} style={{
              background: '#211E1E', color: '#FDC831',
              border: 'none', padding: '11px 22px',
              borderRadius: 8, fontWeight: 800,
              fontFamily: "'Archivo', sans-serif", fontSize: 14, cursor: 'pointer',
            }}>File a ticket</button>
          </div>
        )}

        {!loading && (citations.length > 0 || answer) && chatLogId && (
          <FeedbackPanel
            prompt="Did these answers help?"
            yesLabel="Yes, that's it"
            noLabel="No, didn't help"
            reasons={["Wrong answer", "Outdated info", "Not what I asked", "Too generic", "Couldn't find the right guide", "Other"]}
            thanksPositive="Thanks — we'll keep these surfacing first."
            onVote={(rating, details) => {
              sendFeedback(rating);
              if (details && (details.reasons?.length || details.note)) {
                try {
                  fetch('/api/chats/feedback-detail', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ chat_log_id: chatLogId, rating, ...details }),
                  });
                } catch {}
              }
            }}
            onFileTicket={() => onFileTicket && onFileTicket({ source: 'search' })}
            relatedGuides={[
              ...citations.map((c) => ({ id: c.guide_id, title: c.title, category: c.category })),
              ...((suggestions || []).map((s) => ({ id: s.guide_id, title: s.title, category: s.category })))
            ].filter((g, i, arr) => g.id && arr.findIndex((x) => x.id === g.id) === i)}
            onOpenGuide={onOpenGuide}
          />
        )}

        <div style={{
          marginTop: 'auto', paddingTop: 56, textAlign: 'center',
          fontSize: 10.5, color: '#4A3F2E',
          fontWeight: 800, letterSpacing: '0.08em', textTransform: 'uppercase',
          fontFamily: "'Archivo', sans-serif",
        }}>Built by the Slice IT Team</div>
      </div>
    </div>
  );
}


// Export
window.GuideExperience = GuideExperience;
window.HubSearchResults = HubSearchResults;

// Default export so main.jsx can mount <App />.
export default App;